INSERT INTO m248_art VALUES
(0,0,$m248$الديباجة$m248$,$m248$قانون رقم 182 لسنة 2018 بإصدار قانون تنظيم التعاقدات التى تبرمها الجهات العامة
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m248$,'8d040080b823fdcd4310ef3e7bfec9f7'),
(1,-1,$m248$المادة الأولى إصدار$m248$,$m248$يعمل بأحكام القانون المرافق فى شأن تنظيم التعاقدات التى تبرمها الجهات العامة ، وتسرى أحكامه على الجهات التى تضمها الموازنة العامة للدولة ، ووحدات الجهاز الإدارى للدولة من وزارات ومصالح وأجهزة لها موازنات خاصة ، ووحدات الإدارة المحلية ، والهيئات العامة الخدمية والاقتصادية ، وما يتبع هذه الجهات من وحدات ذات طابع خاص والصناديق الخاصة فيما عدا صناديق الرعاية الاجتماعية المنشأة بها والتى تعتمد فى تمويلها بصفة أساسية على الاشتراكات المالية من أعضائها ، والمشروعات الممولة من الحسابات الخاصة ، دون الإخلال بأحكام الاتفاقيات الدولية ، وذلك كله فيما لم يرد فى شأنه نص خاص فى القوانين أو القرارات الصادرة بإنشائها أو بتنظيمها ، أو فى لوائحها الصادرة بناء على تلك القوانين أو القرارات .$m248$,'84008c25cccc3e461313cabcce0217be'),
(2,-1,$m248$المادة الثانية إصدار$m248$,$m248$لا تخل أحكام القانون المرافق بقانون تنظيم مشاركة القطاع الخاص فى مشروعات البنية الأساسية والخدمات والمرافق العامة الصادر بالقانون رقم 67 لسنة 2010 ، وغيره من قوانين التزامات المرافق العامة القطاعية .
ولا تخل أحكامه بالقانون رقم 5 لسنة 2015 فى شأن تفضيل المنتجات المصرية فى العقود الحكومية ، وذلك فيما لم يرد بشأنه نص خاص .
كما لا تخل أحكامه بقانون الاستثمار الصادر بالقانون رقم 72 لسنة 2017$m248$,'725e251d6e2742044120a54dd8b7425e'),
(3,-1,$m248$المادة الثالثة إصدار$m248$,$m248$يلغى قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998
واستثناء من حكم الفقرة السابقة ، تستمر العمليات التى تم طرحها أو التعاقد عليها بالفعل قبل تاريخ العمل بهذا القانون خاضعة لأحكام قانون تنظيم المناقصات والمزايدات المشار إليه ، إلى حين إتمام تنفيذ التعاقد .$m248$,'b0c8e48d0a3c12737d2be3f17882be80'),
(4,-1,$m248$المادة الرابعة إصدار$m248$,$m248$يصدر وزير المالية اللائحة التنفيذية للقانون المرافق خلال ستة أشهر من تاريخ العمل به ، ويجب أن تتضمن اللائحة القواعد والإجراءات وغيرها من الضوابط اللازمة لتنفيذ أحكامه .
وإلى أن تصدر هذه اللائحة يستمر العمل باللوائح والقرارات القائمة فى تاريخ العمل بهذا القانون فيما لا يتعارض مع أحكام القانون المرافق .$m248$,'2b0a6a24386255d777aed79beb021104'),
(5,-1,$m248$المادة الخامسة إصدار$m248$,$m248$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتبارا من مضى ثلاثين يوما على تاريخ نشره .$m248$,'585d9e6e2d0706e792074afe3051734b'),
(1,0,$m248$المادة 1$m248$,$m248$فى تطبيق أحكام هذا القانون ، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
الجهة الإدارية : أى من الجهات العامة أو الهيئات أو الوحدات المنصوص عليها فى المادة الأولى من مواد إصدار هذا القانون ، وما يتبعها من صناديق خاصة أو حسابات على النحو المبين فى المادة المشار إليها .
السلطة المختصة : الوزير ، ومن له سلطاته ، أو المحافظ ، أو رئيس مجلس إدارة الهيئة العامة أو الصندوق ، أو من يعادلهم من سلطات فى الجهات المنصوص عليها فى المادة الأولى من مواد إصدار هذا القانون ، كل فى نطاق اختصاصه .
بوابة التعاقدات العامة : الموقع الإلكترونى المخصص على شبكة المعلومات الدولية (الإنترنت) للنشر عن البيانات والمعلومات المتعلقة بالتعاقدات العامة التى تجريها الجهات الإدارية الخاضعة لأحكام هذا القانون ، والإجراءات المتعلقة بها فى الحدود المنصوص عليها به واللائحة التنفيذية له .
طلب إبداء الاهتمام : إجراء تتخذه الجهة الإدارية ، وتعلن عنه فى العمليات التى تتطلب معرفة مسبقة للمشتغلين بنشاط معين والوقوف على قدراتهم وخبراتهم بهدف الوصول إلى قائمة مختصرة منهم ، أو معرفة مدى اهتمامهم بالمشاركة فى العملية المقترح طرحها .
التأهيل المسبق : إجراء تتخذه الجهة الإدارية ، وتعلن عنه للتأكد من توافر القدرات الفنية والإمكانيات المالية والإدارية والبشرية وغيرها لدى الموردين أو المقاولين أو مقدمى الخدمات أو الاستشاريين للقيام بتنفيذ أحد العقود بالكفاءة المطلوبة قبل دعوتهم لتقديم العطاءات ، وذلك وفقا لمتطلبات ومعايير التقييم المحددة بمستندات طلب التأهيل المسبق .
مقاولات الأعمال : كل ما يدخل ضمن التصنيف الصادر عن الاتحاد المصرى لمقاولى التشييد والبناء ، ويعتمد من وزير الإسكان والمرافق والمجتمعات العمرانية ، وتخطر به الهيئة العامة للخدمات الحكومية لنشره على بوابة التعاقدات العامة .
الخدمات : ما يكون التعاقد فيها على أساس أداء عمل مادى يمكن توصيفه ، ومن ذلك: الصيانة ، الأمن ، النظافة ، رسم الخرائط ، التصوير بالأقمار الصناعية ، تطوير البرمجيات ، وخدمات النقل .
الدراسات الاستشارية : ما يغلب عليه الطابع الفكرى أو الإرشادى ، ومن ذلك: الدراسات الهندسية أو المهنية أو الاقتصادية أو المالية أو الإدارية أو القانونية ، بما فى ذلك مهام الإعداد أو التصميم أو الإشراف على التنفيذ أو التقييم أو الاستلام .
الأعمال الفنية : ما يتسم بالإبداع الفنى وفقا للطابع الشخصى ، ومن ذلك: الرسم ، التصوير ، تأليف الكتب ، والبحوث .
التقييم بنظام النقاط : أحد أساليب تقييم العطاءات ، يتم فيه تطبيق معايير الجودة الفنية والسعر مجتمعين عن طريق تحديد أسس وعناصر التقييم ، والوزن النسبى للجانب الفنى أو الفنى والمالى للعطاءات بحسب طبيعة العملية ، والحد الأدنى للقبول وصولا إلى درجات أو نسب إجمالية لكل عطاء ، بما يكفل تحديد أولوية ترتيبه .
التواطؤ : ترتيب يتم بين طرفين أو أكثر قبل أو بعد تقديم العطاء ، لتحقيق غرض غير مشروع أو للإخلال بمبدأ تكافؤ الفرص ، ومبدأ حرية المنافسة بما فى ذلك التأثير بشكل مباشر أو غير مباشر على تصرفات طرف آخر ، بهدف تقسيم العقود بين مقدمى العطاءات أو تثبيت أسعار العطاءات بشكل غير تنافسى .
الاحتيال : أى فعل أو امتناع عن فعل يؤدى إلى تضليل الطرف الآخر بهدف الحصول على منفعة مالية أو عينية أو أى منفعة أخرى ، أو التأثير فى العملية المطروحة ، أو لتجنب الالتزام فى تنفيذ العقد .
الفساد : أى عرض أو إعطاء أو استلام أو طلب لأى شىء ذى قيمة ، أو الحث على ارتكاب أفعال غير مناسبة ، سواء بطريقة مباشرة أو غير مباشرة ، للتأثير بشكل غير مشروع على أداء طرف آخر فى العملية المطروحة أو فى تنفيذ العقد .$m248$,'68ce50be93cd757302465cc113792640'),
(2,0,$m248$المادة 2$m248$,$m248$يهدف تطبيق أحكام هذا القانون إلى :
1 - تنظيم إجراءات تخطيط وتنفيذ التعاقدات العامة ، ومتابعة تنفيذ العقود .
2 - تحقيق كفاءة وفاعلية الإنفاق العام .
3 - تعزيز مبادئ الحوكمة ، وتطبيق معايير العلانية والشفافية والنزاهة وحرية المنافسة والمساواة وتكافؤ الفرص ، وتجنب تعارض المصالح .
4 - تطبيق أساليب الإدارة الحديثة ، والانتقال مرحليا إلى استخدام تكنولوجيا المعلومات فى الإجراءات .
5 - تطوير طرق الشراء والبيع وأنماط التعاقد لمسايرة التطورات الاقتصادية ، وتلبية احتياجات الجهات الإدارية بفاعلية .
6 - توفير معاملة عادلة للمتعاملين من مجتمع الأعمال مع الجهات الإدارية ، وفى ذات الوقت منع ممارسات التواطؤ والاحتيال والفساد والاحتكار .
7 - تشجيع الجهات الخاضعة لأحكام هذا القانون على تبنى الحلول والمبادرات الابتكارية والتقنيات المتطورة عند التعاقد على تلبية احتياجاتها ، وكذلك تبنى سياسات التعاقد المستدام .
8 - تهيئة المناخ للشركات والمشروعات المتوسطة والصغيرة والمتناهية الصغر للمنافسة فيما يتم طرحه من عمليات .$m248$,'417f67986cd424c02c1f915484a39eb9'),
(3,0,$m248$المادة 3$m248$,$m248$تنشأ بالجهة الإدارية إدارة للتعاقدات ، أيا كان مستواها الوظيفى بالهيكل التنظيمى ، تشكل من عدد كاف من العناصر المؤهلة والمدربة ، وتتولى مباشرة الاختصاصات الآتية :
1 - تخطيط الاحتياجات السنوية للجهة الإدارية ، واتخاذ الإجراءات اللازمة للتعاقد عليها .
2 - متابعة تنفيذ العقود التى يتم إبرامها ، وتلقى وإرسال الإخطارات اللازمة ، واتخاذ الإجراءات الواجبة طبقا لأحكام هذا القانون ولائحته التنفيذية وما تتضمنه العقود المبرمة .
3 - التنسيق مع الإدارات والجهات المعنية ، وإعداد وتقديم جميع البيانات والتقارير المطلوبة فى شأن التعاقدات العمومية .
4 - القيام بجميع المهام الأخرى المنصوص عليها فى هذا القانون ولائحته التنفيذية .$m248$,'f161ad8d06f47355b5eacbdab8ca6cda'),
(4,0,$m248$المادة 4$m248$,$m248$تنشأ لجنة للمؤشرات والتغيرات الاقتصادية تضم الوزراء المعنيين بالشئون الاقتصادية ، وتختص بدراسة المشروعات والصفقات والتنبؤ ورصد وتحليل ودراسة المؤشرات والتغيرات الاقتصادية التى تؤثر فى توفير متطلبات الجهات الإدارية بما يدعم جهودها فى تقديم الخدمات المنوطة بها وفقا لاختصاصاتها بالجودة المطلوبة ، وتحسينها ورفع كفاءتها بشكل مستمر وبما يسهم فى جهود الدولة فى مجالات التنمية الاقتصادية .
وتعد اللجنة تقريرا بنتائج أعمالها وتوصياتها تعرضه على مجلس الوزراء لاعتماده ، واتخاذ ما يلزم من إجراءات لتنفيذ ما ورد به .
ويصدر بتشكيل اللجنة وقواعد وإجراءات عملها قرار من رئيس مجلس الوزراء .$m248$,'9163e2f8301669548cc1c38888128150'),
(5,0,$m248$المادة 5$m248$,$m248$يتولى مكتب شكاوى التعاقدات العمومية التابع لوزير المالية مباشرة تلقى الشكاوى المتعلقة بأى مخالفة لأحكام هذا القانون ولائحته التنفيذية وفحصها واتخاذ قرار فى شأنها دون مقابل ، ما لم تتطلب دراستها خبرات فنية متخصصة تمكنه من البت فيها ، وتكون قراراته ملزمة لطرفى الشكوى ، ويجب على الجهة الإدارية تنفيذ القرار خلال مدة لا تجاوز سبعة أيام من تاريخ تسلمه ودون أن يخل ذلك بحق مقدم الشكوى فى اللجوء إلى القضاء .
ويصدر بتنظيم العمل بالمكتب ، واختصاصاته الأخرى ، والمدد الزمنية لتلقى الشكاوى والبت فيها ، وآليات الاستعانة بالخبرات الفنية قرار من رئيس مجلس الوزراء .
ويكون لكل ذى شأن التقدم إلى الجهة الإدارية بشكواه كتابة بخصوص أى إجراء من إجراءات التعاقد وفى ذات التوقيت إخطار مكتب شكاوى التعاقدات العمومية بصورة منها ، وإذا لم يفصل فيها بمعرفة الجهة الإدارية يكون له الحق فى التقدم بشكواه إلى المكتب وذلك قبل اللجوء إلى جهات القضاء .
ويجوز للمكتب وقف إجراءات العملية محل الشكوى لمدة يحددها قرار رئيس مجلس الوزراء للفصل فيها إذا كانت هناك ضرورة لذلك عدا الحالات الطارئة أو العاجلة التى يقدرها وفقا للاعتبارات التى تقدمها الجهة الإدارية ، ويلتزم المكتب بنشر نتيجة ما ينتهى إليه فحصه للشكاوى المقدمة له على بوابة التعاقدات العامة .$m248$,'d60582a6483e4ce6ce28a38e0426cb24'),
(6,0,$m248$المادة 6$m248$,$m248$تخضع طرق التعاقد والإجراءات المنصوص عليها فى هذا القانون لمبادئ الشفافية ، وحرية المنافسة ، والمساواة ، وتكافؤ الفرص .$m248$,'3d26ce3c6c00c618422fcadcbd5a83fc'),
(7,0,$m248$المادة 7$m248$,$m248$يكون التعاقد وفق أحكام هذا القانون فى الحالات وبالطرق الآتية :
1 - يكون التعاقد على شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية بطريق المناقصة العامة ، ويجوز استثناء وبقرار مسبب من السلطة المختصة بناء على عرض إدارة التعاقدات إجراء هذا التعاقد بإحدى الطرق الآتية :
(أ) الممارسة العامة .
(ب) الممارسة المحدودة .
(ج) المناقصة المحدودة .
(د) المناقصة ذات المرحلتين .
(هـ) المناقصة المحلية .
(و) الاتفاق المباشر .
2 - يكون التعاقد على بيع أو تأجير المنقولات أو العقارات أو المشروعات التى ليس لها الشخصية الاعتبارية ، والترخيص بالانتفاع أو استغلال العقارات والمشروعات ومن ذلك المنشآت السياحية والمقاصف عن طريق مزايدة علنية عامة أو مزايدة بالمظاريف المغلقة ، ويجوز استثناء بقرار مسبب من السلطة المختصة بناء على عرض إدارة التعاقدات إجراء هذا التعاقد بإحدى الطرق الآتية :
(أ) المزايدة المحدودة .
(ب) المزايدة المحلية .
(ج) الاتفاق المباشر .
ويجوز للجهة الإدارية التعاقد على احتياجاتها باتباع أى من طرق التعاقد الواردة بالفقرة الأولى من هذه المادة للوصول إلى إبرام اتفاق إطارى وفقا لحكم المادة (65) من هذا القانون .
ولا يجوز بأى حال تحويل أى من طرق التعاقد المنصوص عليها فى هذه المادة إلى طريق تعاقد آخر .
وفى جميع الحالات يتم التعاقد فى الحدود وفقا للشروط والقواعد والإجراءات الواردة بهذا القانون ولائحته التنفيذية .$m248$,'9791e9cbbba19185f703b584e9befd0a'),
(8,0,$m248$المادة 8$m248$,$m248$يتعين على الجهات الخاضعة لأحكام هذا القانون مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية المعلنة من مجلس الوزراء فى تعاقداتها ، ومراعاة اعتبارات الجودة والتكلفة ، وتحقيق أفضل قيمة للمال العام على أساس كامل دورة الحياة لما يطرح ، ويجب تضمين متطلبات التعاقد المستدام شروط ومعايير التأهيل والتقييم ومؤشرات الأداء وغيرها .$m248$,'89b086000c5e8cdc86c6124dde431350'),
(9,0,$m248$المادة 9$m248$,$m248$يجب على الجهة الإدارية وضع خطة باحتياجاتها السنوية بالتزامن مع تقديم مشروع موازنتها لوزارة المالية ، تتضمن العمليات المتوقع تنفيذها خلال السنة المالية المقبلة وذلك وفقا للنماذج التى تعدها الهيئة العامة للخدمات الحكومية لهذا الغرض ، ويتم اعتمادها من السلطة المختصة دون غيرها ، وتنشر على بوابة التعاقدات العامة بغرض إعلام المتعاملين معها ، ودون أن يرتب ذلك أى التزامات على الجهة الإدارية .
وعلى الجهة الإدارية تعديل خطة احتياجاتها فى ضوء ما تم تخصيصه وإقراره لها من اعتمادات مالية ، واعتماد هذا التعديل من السلطة المختصة دون غيرها ، ويجب نشر الخطة المعدلة على بوابة التعاقدات العامة فور بداية السنة المالية .
ويستثنى من النشر الحالات التى تقتضى اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة .$m248$,'cc30a28231caf4b194d51e97bd2ad6e4'),
(10,0,$m248$المادة 10$m248$,$m248$يحظر اللجوء إلى تجزئة محل العقود التى تسرى عليها أحكام هذا القانون بقصد التحايل لتفادى الشروط والقواعد والإجراءات وغير ذلك من ضوابط وضمانات منصوص عليها فيه .$m248$,'e275492e5f3c6d328905350c3e95f602'),
(11,0,$m248$المادة 11$m248$,$m248$يجب على الجهة الإدارية قبل البدء فى اتخاذ إجراءات الطرح التحقق من توافر الاعتمادات المالية المخصصة لديها لتنفيذ موضوع التعاقد على أن تتضمن شروط الطرح ما يفيد ذلك ، ويكون التعاقد فى حدود الاحتياجات الفعلية الضرورية .
ويجوز إبرام عقود التوريدات والخدمات الدورية لمدة تجاوز السنة المالية بشرط ألا يترتب عليها زيادة الالتزامات فى إحدى السنوات المالية التالية عما هو مقرر فى السنة التى يتم فيها التعاقد .
ويكون التعاقد بالنسبة للمشروعات الاستثمارية المدرجة بالخطة فى حدود التكاليف الكلية المعتمدة ، على أن يتم الصرف فى حدود الاعتمادات المالية المقررة .
ويحظر التعاقد بقصد استنفاد الاعتمادات المالية ، كما يخطر التعاقد فى الشهر الأخير من السنة المالية إلا فى الحالات الاستثنائية التى تقتضيها ضرورة العمل ، وبموافقة السلطة المختصة .$m248$,'0675e50fc34a27bac7c289024547f0fc'),
(12,0,$m248$المادة 12$m248$,$m248$يجوز للجهة الإدارية إصدار طلب للحصول على معلومات أو مقترحات أو مواصفات أو غيرها ، بغرض استيفاء إجراءات دراسة السوق أو تحديد احتياجاتها على نحو دقيق وفقا لمستجدات السوق أو لإعداد خطة احتياجاتها السنوية ، على أن تعلن عن ذلك بإحدى الصحف اليومية واسعة الانتشار أو توجه الطلب بدعوة المشتغلين بنوع النشاط المطلوب ، وذلك بالإضافة للنشر على بوابة التعاقدات العامة .$m248$,'a0a724f48c984719f24660f8eacc0cd0'),
(13,0,$m248$المادة 13$m248$,$m248$للجهة الإدارية حال رغبتها فى معرفة المشاركين المحتملين أو المهتمين بالدخول فى عملية معينة تنوى طرحها بأى من طرق التعاقد أن تصدر طلبا لإبداء الاهتمام قبل الشروع فى طرح العملية على أن تعلن عنه بإحدى الصحف اليومية واسعة الانتشار وذلك بالإضافة لنشره على بوابة التعاقدات العامة ، ولا يجوز بأى حال أن يؤدى طلب إبداء الاهتمام إلى الحد من عدد المشاركين حال الطرح ، ولا أن يترتب عليه أى حق لمن قاموا بالرد على الطلب .$m248$,'8efce7107bf69afedfa3aa3eb10d56f8'),
(14,0,$m248$المادة 14$m248$,$m248$يكون الطرح على أساس مواصفات ورسومات فنية دقيقة ومفصلة ، أو معايير أداء عامة وكافية توضع بمعرفة لجنة فنية متخصصة ، ويوصف موضوع الطرح وصفا موضوعيا وعاما ، ويحدد فى ذلك الخصائص التقنية والنوعية ذات الصلة والخصائص المتعلقة بالأداء والجودة ومتطلبات الفحص والاختبار ، على أن تراعى المواصفات القياسية المصرية أو الدولية مع تجنب الإشارة إلى علامة تجارية معينة أو اسم تجارى أو براءة اختراع أو تصميم أو نوع أو منتج أو بلد معين أو الرقم الوارد فى قوائم الموردين أو مواصفات تنطبق على نماذج خاصة أو مميزة أو إدراج إشارة إلى أى منها ، ويستثنى من ذلك الأصناف التى يتعذر توصيفها بإضافة عبارة ما يعادلها أو ما يماثلها أو ما يكافئها فى الأداء .$m248$,'09760466fb1c3077b373c38cf2060dd9'),
(15,0,$m248$المادة 15$m248$,$m248$تشكل بقرار من السلطة المختصة لجنة تضم الخبرات والتخصصات النوعية اللازمة ، وتتولى إعداد القيمة التقديرية أو الثمن الأساسى للعملية محل التعاقد من خلال دراسة السوق وتعاقدات الجهة الإدارية السابقة أو تعاقدات غيرها من الجهات الإدارية إن وجدت ، آخذا فى الاعتبار المواصفات التى تتناسب واحتياجاتها ، وذلك قبل البدء فى اتخاذ إجراءات الطرح .
كما تتولى فى حالة البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال تحديد الثمن أو القيمة الأساسية لمحل التعاقد .
وفى جميع الأحوال ، يجب اعتماد القيمة التقديرية أو الثمن الأساسى من السلطة المختصة ، وتكون سرية فيما عدا الحالة المنصوص عليها فى المادة رقم (71) من هذا القانون .
ولا يجوز أن يشارك أعضاء اللجنة التى وضعت القيمة التقديرية أو الثمن الأساسى فى أى من اللجان الأخرى المنصوص عليها فى هذا القانون للعملية ذاتها .$m248$,'9b362fa18566453598d8a937af7d1a2c'),
(16,0,$m248$المادة 16$m248$,$m248$تحدد السلطة المختصة مبلغ التأمين المؤقت ضمن شروط الطرح ، ويجب تقديره دون مبالغة وبما لا يجاوز النسبة المنصوص عليها قرين العمليات الآتية :
1 - فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية : نسبة (1.5%) من القيمة التقديرية وبما يتماشى مع طبيعة العملية وحجمها ، وفى حالة الطرح فى مجموعات متجانسة يحسب التأمين المؤقت لكل مجموعة بذات النسبة .
2 - فى عمليات شراء أو استئجار العقارات : نسبة (0.5%) من القيمة التقديرية للعملية المطروحة .
3 - فى عمليات بيع وتأجير المنقولات والعقارات والمشروعات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات : يتم تحديد مبلغ التأمين المؤقت حسب طبيعة وأهمية المزايدة .
وفى جميع الأحوال ، يجب أن يكون التأمين المؤقت ساريا لمدة ثلاثين يوما بعد تاريخ انتهاء مدة صلاحية سريان العطاء أو تاريخ انتهاء مدة مد صلاحيته .$m248$,'bc496c210113d9264fff9638f0e11573'),
(17,0,$m248$المادة 17$m248$,$m248$على إدارة التعاقدات أن تعد مذكرة أو أكثر للعرض على السلطة المختصة للموافقة على البدء فى اتخاذ إجراءات الطرح والتعاقد وغيرها من الإجراءات ، ويجب أن تتضمن هذه المذكرة على وجه الخصوص بيان محل الطرح وطريقة التعاقد ومدة سريان العطاءات ، وغير ذلك من البيانات التى تحددها اللائحة التنفيذية لهذا القانون .$m248$,'cb24c052e50ac624264b2ecb0c571d16'),
(18,0,$m248$المادة 18$m248$,$m248$تحدد اللائحة التنفيذية لهذا القانون الصور والشروط والأوضاع الخاصة بالتأمين المؤقت ، وكيفية أدائه ورده واستبداله ، والإجراءات الواجب اتباعها فى شأنه .$m248$,'86368e2cd28a72ee2136c135ab6e5aa0'),
(19,0,$m248$المادة 19$m248$,$m248$على الجهة الإدارية قبل الإعلان أو الدعوة للاشتراك فى جميع طرق التعاقد الواردة بهذا القانون والتعاقد بطريق الاتفاق المباشر إذا تطلبت طبيعة العملية ذلك ، أن تعد كراسة للشروط والمواصفات تتضمن الإحالة لجميع القواعد والأحكام والإجراءات والشروط المنصوص عليها فى هذا القانون ولائحته التنفيذية ، ويجب أن تتضمن كراسة الشروط على وجه الخصوص طريقة التعاقد ، والمواصفات والأطر الفنية لموضوع التعاقد ومكان التنفيذ ، والبرنامج الزمنى المتوقع للإجراءات ومواعيد ومكان انعقاد الجلسات ، وشروط الطرح العامة والخاصة ، والتأمينات ، وطريقة السداد ، وتوقيتات تقديم الشكاوى ، وأسلوب التقييم ، وشروط فسخ العقد ، والجزاءات والغرامات ، ونسخة من مشروع العقد المزمع إبرامه متضمنا حقوق والتزامات طرفى التعاقد ، وأى بيانات أخرى بحسب طبيعة العملية .
ويجوز للجهة الإدارية إدخال تعديلات على كراسة الشروط والمواصفات إذا اقتضت المصلحة العامة ذلك أو بناء على جلسة الاستفسارات ، على أن يتم اعتماد تلك التعديلات من السلطة المختصة ، وإخطار من قاموا بشراء كراسة الشروط بها ، وذلك خلال ثلاثة أيام على الأكثر من تاريخ إجراء التعديلات أو جلسة الاستفسارات ، وفى جميع الأحوال ، لا يجوز أن تقل المدة بين الإخطار بهذه التعديلات والموعد المحدد لفتح المظاريف الفنية عن سبعة أيام ، ويتعين الرد كتابة على مقدمى الاستفسارات ومن قاموا بشراء كراسة الشروط بكتاب يرسل بالبريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ، بالإضافة إلى نشرها على بوابة التعاقدات العامة ، ولا يجوز التعديل فى كراسة الشروط والمواصفات بعد الموعد المحدد لفتح المظاريف الفنية .
ويتعين على الجهة الإدارية :
1 - الالتزام بنماذج كراسات الشروط والمواصفات ، وأنماط العقود النموذجية والأدلة الإرشادية ، وغيرها الصادرة عن الهيئة العامة للخدمات الحكومية والتى تعدها الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها ، على أن تتخذ الجهة الإدارية ما يلزم بشأن تضمين كراسة الشروط النموذجية المواصفات الفنية والتوصيف الفنى الكافى لموضوع التعاقد وأى اشتراطات إضافية ترى تضمينها بها ، وكذا نموذج العقد وبما يتناسب مع طبيعة العملية محل الطرح .
2 - تحديد ثمن شراء كراسة الشروط والمواصفات وفقا للشرائح التى تحددها اللائحة التنفيذية لهذا القانون ، وترجم كراسة الشروط والقوائم والمواصفات والتوصيف الفنى بحسب الأحوال فى حال الطرح فى الخارج ، مع ذكر أن النص العربى هو النص المعول عليه فى حالة الخلاف أو الالتباس فى مضمونها .
3 - نشر صورة كاملة ومطابقة من كراسات الشروط والمواصفات على بوابة التعاقدات العامة ، عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة .
وتلتزم الجهات المخاطبة بأحكام هذا القانون بإخطار لجنة تفضيل المنتج الصناعى المصرى بنسخة من شروط ومواصفات الطرح أو العقود التى تزيد قيمتها التقديرية على مليون جنيه ولا تجاوز عشرة ملايين جنيه ، وذلك قبل اتخاذ إجراءات الإعلان عنها أو الدعوة إليها بمدة لا تقل عن خمسة أيام ، كما تلتزم بموافاتها بنسخة من هذه الشروط والمواصفات متى كانت قيمتها التقديرية تزيد على عشرة ملايين جنيه ، وذلك قبل اتخاذ إجراءات الإعلان عنها أو الدعوة إليها أو إسنادها بطريق الاتفاق المباشر ، وذلك بمدة لا تقل عن خمسة عشر يوما ، وعلى اللجنة أن توافى تلك الجهات بملاحظاتها إن وجدت خلال خمسة عشر يوما من تاريخ تسلمها شروط ومواصفات الطرح ، ولا يجوز لتلك الجهات التعاقد خلال هذه المدة .$m248$,'941fa4d9baf84ec3be7335a7c98b532a'),
(20,0,$m248$المادة 20$m248$,$m248$يجب النشر عن العمليات التى يتم طرحها بجميع طرق التعاقد المنصوص عليها بالمادة (7) من هذا القانون على بوابة التعاقدات العامة ، عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة ، على أن يتضمن النشر طريق التعاقد وشروطه والأسباب المبررة لاتباع هذا الطريق ، وأسلوب التقييم الفنى والمالى ، وغيرهامن البيانات التى تحددها اللائحة التنفيذية لهذا القانون .
وفى حالة التعاقد عن طريق المناقصة العامة أو الممارسة العامة الداخلية أو المزايدة العلنية العامة أو المزايدة بالمظاريف المغلقة ، فيجب الإعلان مرة واحدة بإحدى الصحف اليومية واسعة الانتشار ، ويكون الإعلان عن المناقصة العامة والممارسة العامة الخارجية مرة واحدة بإحدى الصحف اليومية واسعة الانتشار ، وبإحدى الصحف الدولية وبالإعلام عنها من خلال السفارات والقنصليات .
وفى حالة التعاقد عن طريق المناقصة المحدودة أو المناقصة المحلية أو الممارسة المحدودة أو المزايدة المحدودة أو المزايدة المحلية ، فيجب توجيه الدعوة لأكبر عدد ممكن من المسجلين المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع الطرح .
وفى حالة إذا ما قررت الجهة الإدارية تأجيل موعد فتح المظاريف أو المزايدة ، فيجب أن يتم الإعلان عن الموعد الجديد بالطريقة ذاتها .
وفى جميع حالات الإعلان أو الدعوة للتعاقد المنصوص عليها فى هذا القانون يتعين الحصول على موافقة السلطة المختصة ، ويجوز بموافقتها الإعلان فى أكثر من صحيفة مصرية أو دولية وفقا لأهمية وطبيعة التعاقد فى الحالات التى تقتضى ذلك .$m248$,'f33bd0103f36a64bb9c929efb1463912'),
(21,0,$m248$المادة 21$m248$,$m248$يجوز للجهة الإدارية إصدار طلب للتأهيل المسبق للتحقق من توافر القدرات الفنية والإمكانيات المالية والإدارية والبشرية وغيرها فى طالبى التأهل لتنفيذ أحد العقود بالكفاءة المطلوبة قبل دعوتهم لتقديم عطاءات حال الطرح ، وذلك وفقا لمتطلبات ومعايير التقييم المحددة بمستندات طلب التأهيل المسبق ، ويتم الإعلان عن التأهيل المسبق بإحدى الصحف اليومية واسعة الانتشار بالإضافة للنشر عنه على بوابة التعاقدات العامة .$m248$,'15f949c7f05570c06f34a49e273c2f09'),
(22,0,$m248$المادة 22$m248$,$m248$فى غير حالات التعاقد بالاتفاق المباشر المطلوب فيها سداد تأمين مؤقت ، يجب أن يؤدى مع كل عطاء تأمين مؤقت لضمان جديته ، ويستبعد كل مقدم عطاء أو متزايد لم يسدد مبلغ التأمين المحدد .
وإذا انسحب مقدم العطاء من العملية قبل الميعاد المحدد لجلسة فتح المظاريف الفنية يصبح التأمين المؤقت المؤدى حقا للجهة الإدارية دون حاجة إلى إنذار أو الالتجاء إلى القضاء أو اتخاذ أى إجراءات أو إقامة الدليل على حصول ضرر ، أو استئدائه من أى مبالغ مستحقة أو تستحق لديها أو لدى أى جهة إدارية أخرى لصاحب العطاء المذكور .
ويجب رد التأمين المؤقت إلى أصحاب العطاءات غير المقبولة فنيا دون توقف على طلب منهم ، وذلك فور انتهاء جميع إجراءات مرحلة البت الفنى ، ويجب رد التأمين المؤقت إلى المتزايدين الذين لم ترس عليهم المزايدة فورا دون توقف على طلب منهم .
وفى جميع حالات التأخير فى رد التأمين المؤقت من الجهة الإدارية ، تلتزم الجهة الإدارية بأن تؤدى لمقدمه قيمة المظاريف البنكية لتجديد خطاب الضمان ، وتكلفة التمويل أو الفائدة المستحقة عن فترة التأخير فى الرد وفقا لسعر الائتمان والخصم المعلن من البنك المركزى ، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك .$m248$,'c649c226d885cccc6c86dd8fe156557a'),
(23,0,$m248$المادة 23$m248$,$m248$تقدم العطاءات فى مظروفين مغلقين ، أحدهما للعرض الفنى والآخر للعرض المالى ، وتلتزم الجهة الإدارية بالحصول على إقرار من مقدم العطاء يضمنه بمظروفه الفنى يفيد التزامه بالتأمين على العمالة وفقا لقوانين التأمينات السائدة إذا تطلبت طبيعة العملية ذلك .
ويكون فتح مظاريف العطاءات فى الوقت والمكان المحددين بكراسة الشروط والمواصفات فى جلسة علنية عامة بحضور من يرغب من مقدمى العطاءات ، ويجوز لمقدمى العطاءات تفويض من يرونه لحضور جلسة فتح المظاريف شريطة تقديم التفويض الدال على ذلك .
ويقتصر فتح مظاريف العروض المالية على العروض المقبولة فنيا .$m248$,'69190cc8e4d4cbfcd62afb42dcb017e1'),
(24,0,$m248$المادة 24$m248$,$m248$فى حالة وفاة مقدم العطاء إذا كان شخصا طبيعيا ، أو مالك شركة الشخص الواحد ، أو الشريك مع الغير بحصة حاكمة تسمح له بالتأثير فى اتخاذ قرار ذى صلة بالعطاء قبل البت ، جاز للجهة الإدارية استبعاد العطاء المقدم منه ورد التأمين المؤقت ، أو السماح للورثة بالاستمرار فى الإجراءات بشرط أن يعينوا عنهم وكيلا بتوكيل مصدق على التوقيعات فيه ، وتوافق عليه السلطة المختصة .$m248$,'7799d2de1c8a6584ec9171424964fe0e'),
(25,0,$m248$المادة 25$m248$,$m248$يجوز لمقدم العطاء أن يعهد ببعض بنود العملية محل التعاقد إلى غيره من الباطن على أن يتضمن عطاؤه بياناتهم وخبراتهم ، وما سيتم إسناده إليهم من بنود وذلك وفقا للمحددات وأى اشتراطات أخرى تضمنها الجهة الإدارية بكراسة الشروط والمواصفات .
ولا يجوز للمتعاقد تغيير أى منهم دون موافقة الجهة الإدارية المتعاقدة . وفى جميع الأحوال ، يظل المتعاقد دون غيره مسئولا أمام الجهة الإدارية المتعاقدة عن تنفيذ العقد .$m248$,'1d559270cc7f4ca286f208246234ac8e'),
(26,0,$m248$المادة 26$m248$,$m248$مع عدم الإخلال بأحكام القانون رقم 106 لسنة 2013 فى شأن حظر تعارض مصالح المسئولين فى الدولة ، وكذا القواعد الحاكمة للسلوك الوظيفى والمهنى ، يحظر على الموظفين والعاملين بالجهات الخاضعة لأحكام هذا القانون التقدم بالذات أو بالواسطة بعطاءات أو عروض لتلك الجهات ، ولا يجوز شراء أصناف منهم أو تكليفهم بأعمال .
ولا يسرى ذلك على شراء كتب من تأليفهم أو تكليفهم بأعمال فنية أو شرائها منهم إذا كانت ذات صلة بالأعمال المصلحية ، وبشرط ألا يشاركوا بأى صورة من الصور فى إجراءات قرار الشراء أو التكليف ، وأن يتم كل منهما فى الحدود ووفقا للقواعد والإجراءات التى تبينها اللائحة التنفيذية لهذا القانون .
كما يحظر على الموظفين والعاملين بالجهات المشار إليها فى الفقرة الأولى من هذه المادة ، الدخول بالذات أو بالواسطة فى المزايدات بأنواعها إلا إذا كانت الأصناف المشتراة لاستعمالهم الخاص ، وكانت مطروحة للبيع عن طريق جهات إدارية أخرى غير جهة عملهم ولا تخضع لإشراف هذه الجهة .$m248$,'5b8b7ce294725879f7c63f45b7593ac7'),
(27,0,$m248$المادة 27$m248$,$m248$يجب أن تتضمن مذكرة الطرح مدة سريان العطاءات ، بشرط ألا تقل هذه المدة عن خمسة وأربعين يوما وألا تجاوز تسعين يوما وفقا لطبيعة العملية . ويجوز استثناء تجاوز الحد الأقصى فى الحالات التى تتطلب طبيعتها ذلك ، ويتعين فى كل الحالات تضمين كراسة الشروط مدة سريان العطاءات المعتمدة من السلطة المختصة ، وتحسب مدة سريان العطاءات اعتبارا من التاريخ المحدد لفتح المظاريف الفنية .
وفى جميع الأحوال ، يجب أن يتم البت والإخطار بالترسية قبل انتهاء مدة سريان هذه العطاءات . فإذا تعذر ذلك ، تعين على إدارة التعاقدات العرض على السلطة المختصة بالأسباب التى أدت إلى التأخير ، واقتراح المدة المطلوب مدها للانتهاء من إجراءات الترسية ، ويجب حال موافقة السلطة المختصة على هذه المدة إخطار مقدمى العطاءات كتابة لمد مدة سريان عطاءاتهم لهذه المدة ، ومد مدة صلاحية التأمين المؤقت على أن يتم ذلك كله قبل تاريخ انتهاء مدة سريان العطاءات بخمسة عشر يوما ، ويستبعد كل عطاء لم يقبل صاحبه مد مدة سريان عطائه كتابة ، ويرد إليه تأمينه فور انتهاء مدة سريان العطاء .$m248$,'313b4262193dfec6c2f19abbd5d6da75'),
(28,0,$m248$المادة 28$m248$,$m248$تتولى إجراءات جميع طرق التعاقد المنصوص عليها بالمادة (7) من هذا القانون لجان تشكل بقرار من السلطة المختصة ، تضم عناصر فنية ومالية وقانونية وفقا لأهمية وطبيعة التعاقد ، على أن يتضمن قرار تشكيلها موعد انتهائها من أعمالها .
وتباشر هذه اللجان عملها على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .
ويكون البت فى المناقصات بأنواعها عن طريق لجنتين ، تتولى إحداهما فتح المظاريف وتتولى الأخرى البت فى المناقصة ، على أنه بالنسبة للمناقصة التى لا تجاوز قيمتها ثلاثمائة ألف جنيه ، يكون فتح المظاريف والبت فيها عن طريق لجنة واحدة .
ولا يجوز الجمع بين رئاسة اللجان المنصوص عليها بهذا القانون واعتماد أعمالها .$m248$,'8263710077f465425111a2e0aba1f00d'),
(29,0,$m248$المادة 29$m248$,$m248$يجب أن يشترك فى عضوية لجان فتح المظاريف ولجان البت فى المناقصات ولجنة الممارسة ممثل لوزارة المالية إذا تجاوزت القيمة التقديرية مليون جنيه ، وعضو من إدارة الفتوى المختصة بمجلس الدولة إذا تجاوزت القيمة التقديرية مليونى جنيه .
ويشترك فى عضوية لجنة البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال ممثل لوزارة المالية متى بلغ الثمن الأساسى مليون جنيه ، وعضو من إدارة الفتوى المختصة بمجلس الدولة متى بلغ الثمن الأساسى مليونى جنيه .
أما فى حالة شراء أو استئجار أو بيع أو تأجير العقارات التى تتم فى الخارج ، فيشترك فى العضوية ممثل لوزارة المالية وعضو من إدارة الفتوى المختصة بمجلس الدولة إذا تجاوزت القيمة التقديرية أو بلغ الثمن الأساسى ثمانية ملايين جنيه .
ويجب اشتراك ممثل لوزارة الإسكان فى عضوية اللجان المشار إليها فى حالات شراء أو استئجار العقارات .
وفى جميع الأحوال ، لا يكون انعقاد اللجنة صحيحا إلا بحضور ممثل وزارة المالية وعضو إدارة الفتوى المختصة بمجلس الدولة بحسب الأحوال ، وممثل لوزارة الإسكان فى الحالات التى تتطلب ذلك .$m248$,'4d073d0b4fb3b835d581cc8fc5cc3db8'),
(30,0,$m248$المادة 30$m248$,$m248$فى حالة التعاقد بالاتفاق المباشر على شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ، تتولى الإجراءات لجنة تشكل بقرار من السلطة المختصة من أهل الخبرة من بينهم عناصر فنية ومالية وقانونية وفقا لأهمية التعاقد وطبيعته ، ويقع على عاتقهم مسئولية التحقق من مطابقة محل التعاقد من النواحى الفنية المطلوبة ومناسبة الأسعار مقارنة بأسعار السوق السائدة وقت التعاقد أو لتحديد أقل العروض سعرا ، والذى يلبى جميع الشروط والمتطلبات التى حددتها الجهة الإدارية فى طلبها وذلك من واقع ما يتم الحصول عليه من عروض أسعار ، وكذا أسس اختيار المتعاقد معه ، ويكون اعتماد نتيجة عمل اللجنة من السلطة المختصة .$m248$,'6cd5b3291dfe293c318061b2779567d1'),
(31,0,$m248$المادة 31$m248$,$m248$مع مراعاة تشكيل اللجان المنصوص عليها فى هذا القانون ، تشكل بقرار من السلطة المختصة لجان متخصصة وفقا لطبيعة العملية تكون مهمتها مباشرة الإجراءات الواردة بأحكام هذا القانون ولائحته التنفيذية .$m248$,'2f31fbc809a21a358fc1fe96cad72251'),
(32,0,$m248$المادة 32$m248$,$m248$يتعين على الجهة الإدارية التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة فيمن يتم التعامل معهم وغيرها من المعايير الموضوعية التى تحددها الجهة الإدارية ضمن شروط الطرح ، وبما يتفق مع الأحكام المنصوص عليها فى هذا القانون ولائحته التنفيذية .$m248$,'c4dad3ae980803b8cf99353212c4f8d6'),
(33,0,$m248$المادة 33$m248$,$m248$يحظر على مقدمى العطاءات التقدم بالذات أو بالشراكة مع الغير بأكثر من عطاء لعملية واحدة ، ما لم يكن المتقدم شريكا مع الغير بحصة لا تسمح له بالتأثير فى اتخاذ قرار ذى صلة بالعطاء .
ويجب على الجهة الإدارية حال مخالفة الحظر المنصوص عليه فى الفقرة الأولى من هذه المادة استبعاد العطاءات المخالفة ، وأيلولة التأمين المؤقت إلى الجهة الإدارية ، أو فسخ العقد أو التنفيذ على الحساب ، وأيلولة التأمين النهائى ، وتحميل المتعاقد بأى خسارة تلحق بها إذا تبين لها مخالفة الحظر بعد التعاقد .
كما يجب على الجهات الإدارية إخطار جهاز حماية المنافسة ومنع الممارسات الاحتكارية بأى مخالفة لأحكام هذا القانون وتكون ذات صلة بأحكام قانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005$m248$,'3a91bbfb87023e302c341fb24a582723'),
(34,0,$m248$المادة 34$m248$,$m248$تتولى لجنة البت دراسة العطاءات المقدمة وفق أحكام هذا القانون ولائحته التنفيذية الشروط والمواصفات المعلن عنها ، ويجوز للجنة البت أن تعهد إلى لجان فرعية تشكلها من بين أعضائها بدراسة النواحى الفنية والمالية فى العطاءات المقدمة ومدى مطابقتها للشروط ، وعلى اللجنة التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة فى مقدمى العطاءات ، وذلك كله وفقا للشروط والمواصفات الواردة بكراسة الشروط ، وللجنة البت أن تضم لعضوية اللجان الفرعية التى تشكلها من ترى الاستعانة برأيهم من أهل الخبرة .
وتقدم اللجان الفرعية تقارير بنتائج أعمالهم وتوصياتها إلى لجنة البت .$m248$,'beab0dda119032c9b6e2bf7657a81963'),
(35,0,$m248$المادة 35$m248$,$m248$يجب استبعاد العطاءات غير المطابقة للشروط والمواصفات طبقا لأحكام هذا القانون ولائحته التنفيذية ، والشروط والمواصفات والمتطلبات المحددة بكراسة الشروط والمواصفات .
وتتم ترسية المناقصة أو الممارسة على صاحب العطاء الأفضل شروطا والأقل سعرا أو الذى يتم ترجيحه وفقا لنظام النقاط المحددة عناصره وأسسه بشروط الطرح ، وذلك بعد توحيد أسس المقارنة بين العطاءات من جميع النواحى الفنية والمالية ، مع الأخذ فى الاعتبار العناصر التى تؤثر فى تحديد القيمة المقارنة للعطاءات بحسب ظروف موضوع التعاقد وطبيعته .
ولا يجوز التعديل فى هذه الشروط بعد الموعد المحدد لفتح المظاريف الفنية .
وإذا تبين للجنة البت أن العطاء الأقل سعرا منخفض انخفاضا غير عادى مقارنة بالعطاءات الأخرى والقيمة التقديرية ، وجب عليها طلب تفاصيل العطاء المقدم كتابة ، فإذا تبين لها من دراسة ما قدمه من تفاصيل ومعلومات أن العرض المقدم منه ما يزال يثير الريبة ويتعذر التنفيذ به توصى اللجنة باستبعاده ، ويتعين أن توثق اللجنة كل ما يتخذ من إجراءات أدت إلى ذلك ، ووفقا لما تنظمه اللائحه التنفيذية لهذا القانون .
وترفع اللجنة محضرها متضمنا قراراتها وتوصياتها للسلطة المختصة للاعتماد أو لتقرير ما تراه .
ويجب أن يشتمل قرار الاستبعاد أو الترسية على الأسباب التى بنى عليها .
ومع مراعاة حكم المادة (4) من القانون رقم 5 لسنة 2015 فى شأن تفضيل المنتجات المصرية فى العقود الحكومية ، يعد المنتج المقدم عن توريدات مستوفية لنسبة المكون الصناعى المصرى أقل سعرا إذا لم تتجاوز نسبة الزيادة فيه (15%) من قيمة أقل عطاء غير مستوف .
ويعد العطاء المقدم عن الخدمات أو الأعمال الفنية التى تقوم بها جهات مصرية أقل سعرا إذا لم تتجاوز نسبة الزيادة فيه (15%) من قيمة أقل عطاء أجنبى ، ويستثنى من ذلك العطاءات المقدمة فى عقود المشروعات المنصوص عليها فى المادة (3) من القانون رقم 5 لسنة 2015 المشار إليه وما تشمله هذه المشروعات أو يكون لازما لها من خدمات أو أعمال فنية .
وفى جميع الأحوال ، يخطر صاحب العطاء الفائز بقبول عطائه بموجب خطاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ، كما يخطر باقى مقدمى العطاءات كتابة بما انتهت إليه الجهة الإدارية من قرارات مع وجوب إتاحة الفرصة لإيضاح أسباب عدم قبول العطاء لمن يطلب من مقدمى العطاءات .$m248$,'13be5676e3d45b9459ef30f667a30830'),
(36,0,$m248$المادة 36$m248$,$m248$تتم ترسية المزايدة على مقدم أعلى سعر مستوف للشروط بشرط ألا يقل السعر المقدم عن الثمن أو القيمة الأساسية ، وترفع اللجنة محضرها متضمنا توصياتها للسلطة المختصة للاعتماد أو تقرير ما تراه ، ويجب أن يشتمل قرار الترسية على الأسباب التى بنى عليها .$m248$,'91ac536c6ef31c261ad9dac13e846625'),
(37,0,$m248$المادة 37$m248$,$m248$تلغى المناقصة أو الممارسة بجميع أنواعها قبل البت فيها بقرار مسبب من السلطة المختصة إذا استغنى عنها نهائيا ، أو اقتضت المصلحة العامة ذلك ، أو فى حالة المنصوص عليها فى الفقرة الأولى من المادة (12) من القانون رقم 5 لسنة 2015 المشار إليه .
ويكون الإلغاء بقرار مسبب من السلطة المختصة سواء من تلقاء ذاتها أو بناء على توصية لجنة البت أو الممارسة إذا تبين وجود تواطؤ بين مقدمى العطاءات أو ممارسات احتيال أو فساد أو احتكار ، أو إذا تبين وجود نقص أو خطأ فى كراسة الشروط والمواصفات .
ويجوز الإلغاء فى أى من الحالات الآتية :
1 - إذا لم يقدم سوى عطاء وحيد ، أو لم يبق بعد العطاءات المستبعدة إلا عطاء واحد ما لم تكن حاجة العمل لاتسمح بإعادة الطرح ، ولا توجد فائدة ترجى من إعادة الطرح وبشرط أن يكون العطاء مطابقا للشروط ومناسبا للقيمة التقديرية .
2 - إذا اقترنت العطاءات كلها أو أغلبها بتحفظات .
3 - إذا كانت قيمة العطاء الأقل تجاوز القيمة التقديرية ، ما لم تبين دراسة لجنة البت أو لجنة الممارسة عدم جدوى إعادة الطرح والآثار المترتبة عليه .
ويكون الإلغاء فى الحالات المنصوص عليها فى الفقرة الثالثة من هذه المادة بقرار من السلطة المختصة بناء على توصية لجنة البت أو لجنة الممارسة ، ويجب أن يشتمل القرار على الأسباب التى بنى عليها ، ويخطر مقدمو العطاءات بذلك بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس ، بحسب الأحوال .
وفى جميع حالات الإلغاء ، يجب رد ثمن كراسة الشروط والمواصفات والتأمين المؤقت إلى أصحاب العطاءات عدا مقدمى العطاءات الذين تبين وجود تواطؤ بينهم أو ممارسات احتيال أو فساد أو احتكار .$m248$,'479d9bf8bcd9f66e73410333c2c57268'),
(38,0,$m248$المادة 38$m248$,$m248$تلغى المزايدة قبل البت فيها إذا استغنى عنها نهائيا ، أو إذا اقتضت المصلحة العامة ذلك ، أو لم تصل نتيجتها إلى الثمن أو القيمة الأساسية ، أو إذا تبين للجهة الإدارية وجود تواطؤ بين المتزايدين أو ممارسات احتيال أو فساد أو احتكار ، ويجوز إلغاؤها إذا لم يقدم سوى عرض وحيد مستوف للشروط .
وترفع لجنة المزايدة محضرا متضمنا قراراتها وتوصياتها للسلطة المختصة للاعتماد أو تقرير ما تراه ، ويجب أن يشتمل قرار إلغاء المزايدة على الأسباب التى بنى عليها .$m248$,'369455e528239622412e297fb9e5cc4f'),
(39,0,$m248$المادة 39$m248$,$m248$على إدارة التعاقدات إخطار مقدمى العطاءات بنتائج قرارات اللجان بالقبول أو الاستبعاد أو الإلغاء فور اعتماد السلطة المختصة لها بخطابات ترسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس ، بحسب الأحوال ، وفقا لعناوينهم وبياناتهم الواردة بالعطاء ، ويكون لهم حق التقدم بشكواهم كتابة خلال سبعة أيام تبدأ من اليوم التالى لإخطارهم بالقرار .
ويخطر صاحب العطاء الفائز بقبول عطائه خلال مدة لا تجاوز يومين بعد انقضاء السبعة الأيام المنصوص عليها فى الفقرة الأولى كما يخطر باقى مقدمى العطاءات بذلك .
وفور إرسال خطابات الإخطار ينشر عن نتائج قرارات اللجان ، وكذا عن نتيجة الترسية فى لوحة الإعلانات المخصصة لهذا الغرض والمحدد لها مكان ظاهر للكافة ، كما يتم النشر على بوابة التعاقدات العامة على أن يتضمن النشر الآتى :
1 - نتائج القرارات ، وأسبابها بالقبول أو الاستبعاد أو الإلغاء أو الترسية للعطاءات أو استبعاد المنتج الصناعى المصرى إن وجدت .
2 - القيمة النهائية للمشروع ، وقيمة المكون الصناعى المصرى الذى تم التعاقد عليه إن وجد .
3 - منشأ الصنع وبلده للمنتجات التى تضمنتها العقود التى أبرمت لشراء منتجات صناعية .$m248$,'33ad02bfe193c4dc7cef795684dce977'),
(40,0,$m248$المادة 40$m248$,$m248$على صاحب العطاء الفائز أن يؤدى التأمين النهائى بالنسب وخلال المدد بالأحكام المبينة قرين الحالات الآتية :
1 - عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية ، خلال عشرة أيام عمل بنسبة (5%) من قيمة العقد تبدأ من اليوم التالى لإخطاره بقبول عطائه ، وبالنسبة للعقود التى تبرم مع متعاقد فى الخارج يكون الأداء خلال عشرين يوم عمل ، ويتم الإخطار بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، معه تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ، ويجوز بموافقة السلطة المختصة منح مهلة إضافية للأداء بما لا يجاوز عشرة أيام عمل .
وفى حالات التعاقد بالاتفاق المباشر والتى تتطلب بحسب طبيعتها ضمان المتعاقد لسلامة محل التعاقد ، فيحجز ما يعادل نسبة (5%) من مستحقاته .
ولا يحصل من صاحب العطاء الفائز التأمين النهائى إذا ورد جميع الأصناف التى رسا عليه توريدها وقبلتها الجهة الإدارية بصفة نهائية خلال المهلة المحددة لأداء التأمين النهائى وذلك إذا لم يكن لهذه الأصناف مدة ضمان ، أما فى الحالات التى تتطلب طبيعتها ضمان المتعاقد لسلامة محل العقد فيتم خصم نسبة (5%) من مستحقاته .
2 - عمليات شراء العقارات : تحجز نسبة (3%) من الثمن ، وترد إلى البائع فور التسجيل أو مضى عام من تاريخ تسليم العقار للجهة الإدارية أيهما أبعد لمواجهة إصلاح أى عيوب قد تظهر خلال هذه المدة .
3 - حال بيع المنقولات ، يجب على من يرسو عليه المزايدة أن يسدد نسبة (30%) من قيمة ما تم ترسيته عليه فور الرسو .
4 - عمليات بيع العقارات والمشروعات : يجب على من ترسو عليه المزايدة أن يسدد نسبة (10%) من قيمة ما تم ترسيته عليه فور الرسو .
5 - فى حالة تأجير المنقولات والعقارات والمشروعات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات : يجب على من يرسو عليه المزاد فى العقود التى لا تزيد مدتها على ثلاث سنوات أن يقدم تأمينا نهائيا بما يعادل (10%) من القيمة الكلية الراسى بها المزاد عن مدة العقد بالكامل وذلك فور رسو المزاد ، ويجب أن يظل التأمين ساريا طوال مدة العقد ، فإذا زادت مدة العقد على ثلاث سنوات يحسب التأمين النهائى الواجب تقديمه بواقع (10%) من قيمة العقد عن الثلاث سنوات الأولى ، ويجدد هذا التأمين قبل بداية الثلاث سنوات التالية أو الفترة المتبقية من العقد أيهما أقل ، وذلك بمراعاة الزيادة السنوية فى قيمة التعاقد المنصوص عليها بالعقد .
ويكون التأمين النهائى ضامنا لتنفيذ العقد ، ويجب رده أو ما تبقى منه فور انتهاء مدة الضمان المحددة بالعقد بغير طلب خلال عشرة أيام عمل ما لم تعدل مدة التعاقد ، وإلا التزمت الجهة الإدارية بأن تؤدى للمتعاقد قيمة المصاريف البنكية لتجديد خطاب الضمان وتكلفة التمويل أو الفائدة المستحقة عن فترة التأخير فى الرد وفقا لسعر الائتمان والخصم المعلن من البنك المركزى ، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك .
وإذا تجاوزت قيمة التأمين المؤقت التأمين النهائى وجب رد الزيادة فورا بغير طلب .
وفى جميع حالات عدم السداد يكون التأمين المؤقت من حق الجهة الإدارية .$m248$,'6063f9e951a727af4aeb833662de226e'),
(41,0,$m248$المادة 41$m248$,$m248$إذا لم يقم صاحب العطاء الفائز بأداء التأمين النهائى خلال المهلة المحددة ، جاز للجهة الإدارية ، بموجب إخطار بكتاب يرسل له بخدمة البريد السريع ، عن طريق الهيئة القومية للبريد مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ودون حاجة لاتخاذ أى إجراء آخر ، إلغاء العقد أو تنفيذه بواسطة أحد مقدمى العطاءات التالية لعطائه بحسب ترتيب أولوياتها .
ويصبح التأمين المؤقت فى جميع الحالات من حق الجهة الإدارية ، كما يكون لها أن تخصم قيمة كل خسارة تلحق بها إذا تبين أنه المتسبب فيها من أى مبالغ مستحقة أو تستحق لديها لصاحب هذا العطاء ، وفى حالة عدم كفايتها تلجأ إلى خصمها من مستحقاته لدى أى جهة إدارية أخرى ، أيا كان سبب الاستحقاق ، وذلك كله مع عدم الإخلال بحقها فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى .$m248$,'b22dd909d59268d8bcb6dfb92514546c'),
(42,0,$m248$المادة 42$m248$,$m248$تحدد اللائحة التنفيذية لهذا القانون الصور والشروط والأوضاع الخاصة بالتأمين النهائى ، وكيفية أدائه ورده واستبداله ، والإجراءات الواجب اتباعها فى شأنه .$m248$,'7b008ae581dde52cc267caa1384429b1'),
(43,0,$m248$المادة 43$m248$,$m248$يكون تنفيذ العقود طبقا لما اشتملت عليه ، وبطريقة تتفق مع ما يوجبه حسن النية ، وفى الحدود ووفقا للشروط والقواعد والإجراءات الواردة بهذا القانون ولائحته التنفيذية .$m248$,'91734ff8ffa570babe3d7420cb910642'),
(44,0,$m248$المادة 44$m248$,$m248$يجوز للجهة الإدارية المتعاقدة بموافقة السلطة المختصة صرف دفعة مقدمة من قيمة التعاقد مقابل خطاب ضمان بنكى معتمد دون أى قيد أو شرط بالقيمة والعملة ذاتهما ، بشرط تضمين كراسة الشروط والمواصفات نسبة الدفعة وطلب تحديد أوجه صرفها ، ويتم استنزال قيمة الدفعة المقدمة مما يتم صرفه للمتعاقد مقابل تخفيض قيمة خطاب ضمان الدفعة المقدمة بالنسبة ذاتها .
وتحدد اللائحة التنفيذية لهذا القانون نسب وإجراءات صرف الدفعة المقدمة للمتعاقد ، ويجوز تجاوز تلك النسب بموافقة وزير المالية .$m248$,'d4874f49a05e0eb0746a7316b441c18f'),
(45,0,$m248$المادة 45$m248$,$m248$مع مراعاة شروط التعاقد ، يصرف ثمن الأصناف الموردة أو الخدمات المؤداة فى أقرب وقت ممكن وبما لا يجاوز ثلاثين يوما تحسب من تاريخ الفحص والقبول والاعتماد .
وفى مقاولات الأعمال تصرف الجهة الإدارية دفعات تحت الحساب تبعا لتقدم العمل ، وذلك خلال ستين يوما تحسب من تاريخ تقديم المستخلص لها معززا بالمستندات على النحو الوارد بشروط التعاقد وقبول هذه المستندات من الجهة الإدارية ، وتلتزم خلالها بمراجعته والوفاء بقيمة ما يعتمد .
ويجوز للمقاول فى حالة رفض الجهة الإدارية استلام المستخلص المستوفى لشروط التعاقد إرساله مرفقا به كافة المستندات المبينة بشروط التعاقد بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، على أن يكون تاريخ استلام الجهة الإدارية للمستخلص بالبريد هو بداية المدة اللازمة للبدء فى إجراءات الصرف .
وفى جميع الأحوال ، إذا لم يتم الوفاء بالمبالغ المستحقة للمتعاقد فى المواعيد المحددة تلتزم الجهة الإدارية بأن تؤدى للمتعاقد ما يعادل تكلفة التمويل لقيمة المطالبة أو المستخلص المعتمد عن فترة التأخير وفقا لسعر الائتمان والخصم المعلن من البنك المركزى وقت المحاسبة شريطة تقديم مستندات رسمية بالمبلغ المطالب به ، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك .$m248$,'9bd3a4cd710a873fa0ec77c021d5f3f2'),
(46,0,$m248$المادة 46$m248$,$m248$إذا طرأ من المستجدات بعد إبرام العقد ما يوجب تعديل حجم التعاقد يكون للجهة الإدارية أن تعدل عقودها بالزيادة أو النقص وبما لا يجاوز (25%) من كمية كل بند لعقود المقاولات ، وبما لا يجاوز (15%) من كمية كل بند لباقى العقود بذات الشروط والمواصفات والأسعار ، على أن تتضمن كراسة الشروط والمواصفات مضمون ذلك .
ويتعين لتعديل العقد الحصول على موافقة السلطة المختصة أو مجلس الوزراء بحسب الأحوال ، ووجود الاعتماد المالى اللازم ، وأن يصدر التعديل خلال فترة سريان العقد ، وألا يؤثر ذلك على أولوية المتعاقد فى ترتيب عطائه ، وأن تعدل مدة العقد الأصلى إذا تطلب الأمر ذلك بالقدر الذى يتناسب وحجم الزيادة أو النقص .$m248$,'355e5212bc763d16123442465eefc8c3'),
(47,0,$m248$المادة 47$m248$,$m248$فى عقود مقاولات الأعمال التى تكون مدة تنفيذها ستة أشهر فأكثر ، تلتزم الجهة الإدارية فى نهاية كل ثلاثة أشهر تعاقدية من التاريخ المحدد لفتح المظاريف الفنية أو تاريخ التعاقد المبنى على أمر الإسناد بالاتفاق المباشر بحسب الأحوال ، بتعديل قيمة العقد وفقا للزيادة أو النقص فى تكاليف بنود العقد التى طرأت بعد التاريخ المحدد لفتح المظاريف الفنية أو بعد تاريخ التعاقد المبنى على أمر الإسناد بالاتفاق المباشر وبمراعاة البرنامج الزمنى للتنفيذ من واقع نشرة الأرقام القياسية للمنتجين الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء ، ويكون هذا التعديل ملزما لطرفى التعاقد ، ويتعين تضمين العقد مضمون ذلك .
وعلى الجهة الإدارية تحديد البنود المتغيرة أو مكوناتها بكراسة الشروط والمواصفات وفقا للقائمة التى تصدرها وزارة الإسكان ، على أن يضع المقاول معاملاتها فى المظروف الفنى ، ويقع باطلا كل اتفاق يخالف ذلك .
وتبين اللائحة التنفيذية لهذا القانون الضوابط والإجراءات المتبعة فى هذا الشأن ، ومعادلة تغير الأسعار واشتراطات تطبيقها .$m248$,'e076caf29fb5bf9a4f9d35a8a589290b'),
(48,0,$m248$المادة 48$m248$,$m248$إذا تأخر المتعاقد أثناء تنفيذ العقد عن الميعاد المحدد له بالجدول الزمنى أو مدة التنفيذ المحددة بالعقد ، جاز للسلطة المختصة لدواعى المصلحة العامة إعطاؤه مهلة لإتمام التنفيذ دون تحصيل مقابل للتأخير منه إذا كان التأخير راجعا لسبب خارج عن إرادته .
وفى حالة عدم الالتزام بالتنفيذ ، لسبب راجع للمتعاقد ، يحصل مقابل للتأخير يحسب من بداية المهلة دون حاجة إلى تنبيه أو إنذار أو اتخاذ أى إجراء آخر وفقا للآتى :
1 - فى مقاولات الأعمال بما لا يجاوز مجموع مقابل التأخير نسبة (10%) من قيمة العقد إذا لم تتجاوز مدة التأخير نسبة (10%) من المدة الكلية للعملية ، ويزيد مقابل التأخير إلى نسبة (15%) إذا جاوزت مدة التأخير ذلك .
ويحسب مقابل التأخير من قيمة الأعمال المتأخرة فقط إذا رأت الجهة الإدارية أن الجزء المتأخر لا يمنع الانتفاع بما تم تنفيذه بشكل مباشر أو غير مباشر على الوجه الأكمل فى المواعيد المحددة ، أما إذا رأت أن الجزء المتأخر يمنع الانتفاع بما تم تنفيذه فيكون حساب مقابل التأخير من قيمة ختامى العملية .
ويتم تطبيق معادلة تغير الأسعار للكميات التى نفذت خلال المهلة بشرط أن يكون التأخير راجعا لأسباب خارجة عن إرادة المتعاقد ، على أن يعدل الجدول الزمنى بما يتفق عليه الطرفان إذا تطلب الأمر ذلك وبما يتناسب مع مدة التأخير .
2 - فى باقى العقود بما لا يجاوز مجموع مقابل التأخير نسبة (3%) من قيمة العقد إذا لم تتجاوز مدة التأخير نسبة (10%) من المدة الكلية للعقد ، ويزيد مقابل التأخير إلى نسبة (5%) إذا جاوزت مدة التأخير ذلك .
ويحسب مقابل التأخير من قيمة الجزء المتأخر فقط إذا رأت الجهة الإدارية أن الجزء المتأخر لا يمنع الانتفاع بما تم توريده أو تنفيذه بشكل مباشر أو غير مباشر على الوجه الأكمل فى المواعيد المحددة ، أما إذا رأت أن الجزء المتأخر يمنع الانتفاع بما تم توريده أو تنفيذه فيكون حساب مقابل التأخير من القيمة الإجمالية للعقد .
وفى جميع حالات تحصيل مقابل التأخير ، يكون الإعفاء منه بقرار من السلطة المختصة إذا تبين أن التأخير لأسباب خارجة عن إرادة المتعاقد ، وللسلطة المختصة فى غير هذه الحالة إعفاء المتعاقد من مقابل التأخير جزئيا أو كليا إذا لم ينتج عن التأخير ضرر ، ويجوز للسلطة المختصة استطلاع رأى إدارة الفتوى المختصة بمجلس الدولة إذا ارتأت ذلك .
ولا يخل تحصيل مقابل التأخير بحق الجهة الإدارية فى الرجوع على المتعاقد بكامل التعويض المستحق عما أصابها من أضرار بسبب التأخير .$m248$,'1dca0bb046e5eb23c5e7d519834f451c'),
(49,0,$m248$المادة 49$m248$,$m248$يجب على الجهة الإدارية استلام محل التعاقد فى المواعيد المحددة بالعقد حال مطابقتها للمواصفات والشروط المتفق عليها بالعقد ، وللمتعاقد حال تقاعس الجهة المتعاقدة عن الاستلام التقدم بطلب للسلطة المختصة لتشكيل لجنة محايدة لدراسة أسباب التقاعس ، وصورة منه لمكتب شكاوى التعاقدات العمومية وذلك للمتابعة .
وتلتزم السلطة المختصة خلال سبعة أيام من تاريخ استلامها للطلب بتشكيل لجنة ثلاثية متخصصة من جهات محايدة وتكون الجهة المتعاقدة طرفا فيها على أن تبدأ أعمالها فور صدور قرار تشكيلها وسداد المتعاقد أتعاب الجهات الخارجية المشاركة فيها ، وتقدم اللجنة تقريرها خلال مدة زمنية أقصاها ثلاثون يوما ما لم تتطلب طبيعة العملية وحجمها مدة تتجاوز ذلك ، ويكون تقريرها ملزما للطرفين ، وحال تبين تقاعس الجهة المتعاقدة عن الاستلام يتم رد أتعاب اللجنة للمتعاقد ، وإحالة المتسبب للتحقيق وتحميله بأتعاب اللجنة .
وتصدر السلطة المختصة قرارا بإنهاء إجراءات الاستلام فى مدة زمنية لا تجاوز مدة الفحص والاستلام المتفق عليها مسبقا بشروط الطرح والتعاقد .$m248$,'c161799b01c87810baf8ac8c649e8947'),
(50,0,$m248$المادة 50$m248$,$m248$يجب فسخ العقد فى الحالات الآتية :
1 - إذا تبين أن المتعاقد استعمل بنفسه أو بواسطة غيره الغش أو التلاعب فى تعامله مع الجهة الإدارية المتعاقدة أو فى حصوله على العقد .
2 - إذا تبين وجود تواطؤ أو ممارسات احتيال أو فساد أو احتكار .
3 - إذا أفلس المتعاقد أو أعسر .
ويتم الفسخ فى الأحوال المشار إليها تلقائيا ، ويشطب اسم المتعاقد فى الحالتين المنصوص عليهما فى البندين (1 ، 2) من سجل المتعاملين بعد أخذ رأى إدارة الفتوى المختصة بمجلس الدولة ، وتخطر الهيئة العامة للخدمات الحكومية بذلك لنشر قرار الشطب بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة .
ويعاد قيد المتعاقد الذى شطب اسمه فى سجل المتعاملين بناء على طلبه إذا انتفى سبب الشطب بصدور قرار من النيابة العامة بألا وجه لإقامة الدعوى الجنائية ضده أو بحفظها إداريا أو بصدور حكم نهائى ببراءته مما نسب إليه ، على أن تخطر الهيئة العامة للخدمات الحكومية بقرار إعادة القيد لنشره بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة .$m248$,'211e96eaac2efef5956df8b66cf04a87'),
(51,0,$m248$المادة 51$m248$,$m248$يجوز للجهة الإدارية فسخ العقد أو تنفيذه على حساب المتعاقد ، إذا أخل بأى شرط جوهرى من شروطه .
ويكون الفسخ أو التنفيذ على حساب المتعاقد بقرار مسبب من السلطة المختصة ، يخطر به المتعاقد بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى الوقت ذاته بالبريد الإلكترونى أو الفاكس بحسب الأحوال على عنوانه المبين فى العقد .
ولا يجوز للجهة الإدارية الجمع بين كل من الإجراءين المنصوص عليهما فى الفقرة السابقة لأى سبب .
وفى جميع حالات الفسخ أو التنفيذ على حساب المتعاقد يكون التأمين النهائى من حق الجهة الإدارية ، كما يكون لها أن تخصم ما تستحقه من مقابل التأخير وقيمة كل خسارة تلحق بها من أى مبالغ مستحقة أو تستحق للمتعاقد لديها ، وفى حالة عدم كفايتها تلجأ إلى خصمها من مستحقاته لدى أى جهة إدارية أخرى أيا كان سبب الاستحقاق ، دون حاجة إلى اتخاذ أى إجراءات قضائية ، وذلك كله مع عدم الإخلال بحقها فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى .$m248$,'01e72628deebc17fdc53db6111aedfe5'),
(52,0,$m248$المادة 52$m248$,$m248$فى حالة وفاة المتعاقد أثناء التنفيذ ، يحق للجهة الإدارية إنهاء العقد ورد التأمين النهائى للورثة ما لم يكن لها مطالبات قبل المتعاقد أو السماح لهم بالاستمرار فى تنفيذ العقد ، وإذا كان العقد مبرما مع أكثر من متعاقد وتوفى أحدهم ، جاز للجهة الإدارية إنهاء العقد مع رد التأمين النهائى ما لم يكن لها مطالبات أو السماح لباقى المتعاقدين بالاستمرار فى تنفيذه .$m248$,'c6648470eb12df5695b7a93085c92b9f'),
(53,0,$m248$المادة 53$m248$,$m248$تسرى أحكام هذا الباب على عمليات شراء أو استئجار المنقولات والعقارات ، والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية .$m248$,'5a1676412e490898165de7025da30126'),
(54,0,$m248$المادة 54$m248$,$m248$يكون التعاقد بطريق الممارسة العامة فى الحالات التى تتوافر فيها الشروط الآتية :
1 - أن يكون متاحا للجهة الإدارية وضع توصيف محدد ودقيق لموضوع التعاقد .
2 - أن يكون لموضوع التعاقد معايير قابلة للقياس الكمى والتى على أساسها يتم تحديد مدى استجابة العروض فنيا .
3 - أن يكون معلوما للجهة الإدارية وجود عدد كاف من الموردين أو المقاولين أو مقدمى الخدمات للمشاركة فى العملية لضمان تحقيق المنافسة الفعالة .$m248$,'f78238d348ac289a3204ae0ddb7ef841'),
(55,0,$m248$المادة 55$m248$,$m248$مع مراعاة حكمى البندين (1، 2) من المادة (54) من هذا القانون ، يقتصر التعاقد بطريق الممارسة المحدودة فى أى من الحالات الآتية :
1 - الأصناف التى يتم تصنيعها أو استيرادها أو تقديمها من قبل أشخاص أو كيانات بذاتها ، أو الأصناف التى تقتضى طبيعتها أو الغرض من الحصول عليها أن يكون اختيارها أو شراؤها من أماكن إنتاجها .
2 - التعاقدات المرتبطة باعتبارات الأمن القومى .
3 - الأصناف أو الأعمال أو الخدمات التى تتطلب أن تكون متوافقة مع ما هو موجود حاليا بسبب عدم وجود بدائل لها وتكون متوافرة لدى أكثر من مصدر .$m248$,'51e6f1e3cc89111287e8de7fa443417f'),
(56,0,$m248$المادة 56$m248$,$m248$تتم الممارسة بنوعيها بقيام مقدمى العطاءات المقبولة عروضهم فنيا دون غيرهم بالتمارس فى الجلسة المحددة لذلك من خلال جولة أو عدة جولات وصولا لاختيار العطاء الأفضل شروطا تعاقدية والأقل سعرا ، ما لم يكن التقييم فيها بنظام النقاط .
وتستخدم المنظومة الإلكترونية المخصصة لذلك فور اكتمالها وانتظامها وذلك فيما يتم ميكنته وإتاحته من إجراءات .$m248$,'5fa573b00aa703f6f778813ea326d30f'),
(57,0,$m248$المادة 57$m248$,$m248$يكون التعاقد بطريق المناقصة المحدودة فى أى من الحالات الآتية :
1 - العمليات التى تتطلب طبيعتها قصر الاشتراك فيها على موردين أو مقاولين أو فنيين أو استشاريين أو خبراء بذاتهم ، سواء فى مصر أو فى الخارج .
2 - العمليات التى أتخذت الجهة الإدارية إجراءات تأهيل مسبق فى شأنها ، وبحيث يتم دعوة من تم تأهيلهم للاشتراك فيها .
3 - التعاقدات المرتبطة باعتبارات الأمن القومى .
4 - توفير المستحضرات والأجهزة الطبية والأدوية ، وغيرها من المستلزمات المرتبطة بالمحافظة على الحياة والصحة .
5 - إذا كان الوقت أو التكلفة اللازمان للطرح بطريقة المناقصة العامة لا يتناسبان مع قيمة التعاقد .
6 - عزوف مقدمى العطاءات عن المشاركة فى المناقصات العامة التى تم طرحها مرة أو أكثر وانتهت دراسة الجهة الإدارية إلى مناسبة تغيير طريقة الطرح .$m248$,'9b3febd08292e400a9edd61abba5b8c7'),
(58,0,$m248$المادة 58$m248$,$m248$يجوز التعاقد تطبيقا لأحكام هذا الباب بطريق المناقصة ذات المرحلتين بما يمكن الجهة الإدارية من تحديد الجوانب الفنية أو التعاقدية بشكل متكامل للحصول على عطاءات تنافسية فى أى من الحالات التالية :
1 - التعاقدات ذات المواصفات الفنية المركبة .
2 - عندما ترغب الجهة الإدارية أن تأخذ فى الاعتبار مختلف الحلول الفنية أو التعاقدية والمزايا النسبية لتلك الحلول قبل اتخاذ قرار فى شأن المواصفات الفنية النهائية والشروط التعاقدية .
3 - عندما لا تتوافر تفاصيل المواصفات الفنية الدقيقة أو خصائص الموضوع محل التعاقد عند البدء فى إجراءات الطرح .
ويتم الإعلان عن المناقصة ذات المرحلتين بإحدى الصحف اليومية واسعة الانتشار أو بدعوة المسجلين أو المؤهلين من المشتغلين بالنشاط ، ويجب أن تتضمن كراسة الشروط والمواصفات فى المرحلة الأولى الغرض من التعاقد ، والأداء المتوقع ، والخطوط العريضة للمواصفات الفنية والميزات والمواصفات التى ترغب الجهة الإدارية فى التعاقد عليها ، والمؤهلات المطلوبة لتنفيذ العقد ، ويطلب من مقدمى العطاءات تقديم عروضهم الفنية الأولية بدون أسعار ، وكذلك تقديم ملاحظاتهم على شروط العقد المقترحة ، وأى شروط أخرى .
ويجوز للجهة الإدارية الدخول فى مناقشات فنية خلال المرحلة الأولى مع أى من أصحاب العروض المستجيبة للحد الأدنى من المتطلبات الأساسية الواردة بكراسة الشروط والمواصفات ، وذلك للوصول إلى إطار أعمال ومتطلبات فنية وتعاقدية مدققة تحقق احتياجات الجهة الإدارية وللوصول إلى أكبر قدر من المنافسة ، ويخطر مقدمو العروض بنتيجة المرحلة الأولى .
وتخطر الجهة الإدارية فى المرحلة الثانية مقدمى العروض المقبولة لتقديم عطاءاتهم ، متضمنة العرض الفنى والعرض المالى وفقا للشروط والمواصفات المدققة .
وفيما عدا إجراءات المرحلة الأولى تسرى على إجراءات المناقصة ذات المرحلتين ذات القواعد والإجراءات المنظمة للتعاقد بطريق المناقصة بحسب الأحوال .
ويجوز للجهة الإدارية إجراء تأهيل مسبق قبل الطرح إن ارتأت ذلك .$m248$,'4d55ab4e27a3080a840458f3852dce52'),
(59,0,$m248$المادة 59$m248$,$m248$يكون التعاقد بطريق المناقصة المحلية فيما لا تزيد قيمته على أربعة ملايين جنيه ، ويقصر الاشتراك فيها على الموردين والمقاولين ومقدمى الخدمات والأعمال الفنية والاستشاريين المحليين الذين يقع نشاطهم فى نطاق المحافظة التى يتم بدائرتها تنفيذ موضوع التعاقد ومن بينهم المشروعات المتوسطة والصغيرة والمتناهية الصغر .
ويجوز قصر التعاقد بطريق المناقصة المحلية فيما لا تزيد قيمته على مليونى جنيه على المشروعات المتوسطة والصغيرة والمتناهية الصغر التى يقع نشاطها فى نطاق المحافظة التى يتم بدائرتها تنفيذ موضوع التعاقد ، ويجوز فى هذه الحالة فقط وبقرار من السلطة المختصة الاكتفاء بتقديم إقرار بديل عن التأمين المؤقت فى العملية محل الطرح مفادة الالتزام بالسير فى الإجراءات ، كما يجوز للسلطة المختصة صرف دفعة مقدمة وفقا لما تعتمده على أن تتضمن شروط الطرح ذلك .
وفى حالة عدم تقدم أى منها للمناقصة ، يكون للجهة الإدارية حال إعادة الطرح توجيه الدعوة لهم ولغيرهم ، ولا يتم فى هذه الحالة الاستثناء من شرط التأمين المؤقت .
ويتعين على الجهات الإدارية قبل الطرح إخطار جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر لإعلام أصحاب تلك المشروعات بالمحافظة التى يتم بدائرتها التنفيذ لحثهم على تسجيل بياناتهم وتحديثها على بوابة التعاقدات العامة .$m248$,'6ba1bcf42486c690ec418e20b4eaf608'),
(60,0,$m248$المادة 60$m248$,$m248$تسرى على كل من المناقصة المحدودة والمناقصة ذات المرحلتين والمناقصة المحلية والممارسة بنوعيها ، الأحكام الخاصة بالمناقصة العامة فيما لم يرد فى شأنه نص خاص فى هذا القانون ولائحته التنفيذية .$m248$,'80fb24d55f4711ab150e4d8f9c247827'),
(61,0,$m248$المادة 61$m248$,$m248$تسرى على شراء أو استئجار العقارات ذات الأحكام المنظمة لشراء أو استئجار المنقولات ، وبما لا يتعارض مع طبيعتها .$m248$,'030eb04017d17568d134321ee4d929c2'),
(62,0,$m248$المادة 62$m248$,$m248$يجوز التعاقد بطريق الاتفاق المباشر فى أى من الحالات الآتية :
1 - الحالات الطارئة الناجمة عن الظروف الفجائية التى لم يكن فى الإمكان توقعها أو التنبؤ بها ، أو التى تتطلب الضرورة التعامل معها بشكل فورى ، ولا تحتمل اتباع إجراءات المناقصة أو الممارسة بنوعيهما .
2 - وجود مصدر واحد فقط لديه القدرة الفنية أو القدرة على تلبية متطلبات التعاقد أو لديه الحق الحصرى أو الاحتكارى لموضوع التعاقد .
3 - تحقيق أغراض التكامل مع ما هو موجود ، ولا يوجد له سوى مصدر واحد .
4 - عندما يكون موضوع التعاقد غير مشمول فى عقد قائم ، وتقتضى الضرورة الفنية تنفيذه بمعرفة المتعاقد القائم بالتنفيذ .
5 - الحالات العاجلة التى يكون التعاقد فيها خلال مدة زمنية لا تسمح باتخاذ إجراءات المناقصة أو الممارسة بنوعيهما ، وذلك لضمان سلامة وكفالة سير العمل بالجهات الإدارية ، وألا يكون ذلك ناجما عن سوء التقدير أو التأخر فى اتخاذ الإجراءات .
6 - فى حالة التوحيد القياسى مع ما هو قائم .
7 - فى حالات تعزيز السياسات الاجتماعية أو الاقتصادية التى تتبناها الدولة .
ويتعين الحصول على عروض أسعار عند التعاقد بالاتفاق المباشر فى الحالات المبينة قرين البنود (5)، و (6)، و(7) المشار إليها .$m248$,'c9c5c6aa81ce63bf837803e8453e04ec'),
(63,0,$m248$المادة 63$m248$,$m248$يكون التعاقد بطريق الاتفاق المباشر طبقا لحكم المادة (62) من هذا القانون بناء على ترخيص من :
1 - رئيس الهيئة ، أو رئيس المصلحة ومن له سلطاته فى الجهات الإدارية الأخرى أو رئيس الصندوق ، وذلك فيما لا تجاوز قيمته مليون جنيه بالنسبة لشراء أو استئجار المنقولات أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ، وخمسة ملايين جنيه بالنسبة لمقاولات الأعمال .
2 - الوزير ومن له سلطاته ، أو المحافظ ، فيما لا تجاوز قيمته عشرة ملايين جنيه بالنسبة لشراء أو استئجار المنقولات أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ، وعشرين مليون جنيه بالنسبة لمقاولات الأعمال .
ولمجلس الوزراء فى حالة الضرورة القصوى أن يأذن بالتعاقد بطريق الاتفاق المباشر، وذلك فيما يجاوز الحدود المنصوص عليها فى البند (2) .
كما يجوز بموافقة السلطة المختصة التعاقد بالاتفاق المباشر على شراء أو استئجار المنقولات أو الأعمال أو تلقى الخدمات منخفضة القيمة والتى لا تتجاوز قيمتها عشرين ألف جنيه فى المرة الواحدة ، ولا تجاوز مائة ألف جنيه خلال السنة المالية ، ويتبع فى شأنها الإجراءات التى تبينها اللائحة التنفيذية لهذا القانون ، ويجوز للسلطة المختصة التفويض فى اختصاصاتها فى هذه الحالة فقط .
3 - الوزير المختص بالصحة بالنسبة للأمصال واللقاحات والعقاقير الطبية ذات الطبيعة الاستراتيجية وألبان الأطفال ، وفقا للضوابط والشروط التى تحددها اللائحة التنفيذية لهذا القانون .
ولا يجوز لأى من هذه السلطات التفويض فى الاختصاصات الممنوحة لها للتعاقد بهذا الطريق .
ويستثنى من العرض على لجنة تفضيل المنتج الصناعى المصرى فى العقود الحكومية إذا اقتضت المصلحة العامة ذلك فى الحالات التى يصدر بها قرار من رئيس مجلس الوزراء ، بناء على عرض الوزير المختص بالتجارة والصناعة .
ويجب على إدارة التعاقدات توثيق مبررات اتباع طريق الاتفاق المباشر ، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .$m248$,'35328a1d75a9443b670af690cbb00297'),
(64,0,$m248$المادة 64$m248$,$m248$يجوز فى الحالات الطارئة ، أو فى الحالات العاجلة ، أو لدواعى المصلحة العامة أن يتم التعاقد على شراء أو استئجار العقارات بطريق الاتفاق المباشر ، وذلك بناء على ترخيص من :
1 - رئيس الهيئة ، أو رئيس المصلحة ومن له سلطاته فى الجهات الإدارية الأخرى أو رئيس الصندوق ، وذلك فيما لا تجاوز قيمته خمسمائة ألف جنيه بالنسبة للاستئجار ، ومليون جنيه بالنسبة للشراء خلال العام المالى .
2 - الوزير ومن له سلطاته أو المحافظ ، وذلك فيا لا تجاوز قيمته خمسة ملايين جنيه بالنسبة للاستئجار ، وعشرة ملايين جنيه بالنسبة للشراء خلال العام المالى .
ولا يجوز لأى من هذه السلطات التفويض فى الاختصاصات الممنوحة لها للتعاقد بهذا الطريق .
ولمجلس الوزراء فى حالة الضرورة القصوى ، أن يأذن بالتعاقد بطريق الاتفاق المباشر ، وذلك فيما يجاوز الحدود المنصوص عليها بالبند (2) .
ويجب على إدارة التعاقدات توثيق مبررات اتباع طريق الاتفاق المباشر ، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .$m248$,'0b395759c8eaf1a823d3311e76926e27'),
(65,0,$m248$المادة 65$m248$,$m248$يجوز للجهة الإدارية طرح احتياجاتها أو احتياجات جهة إدارية أخرى أو أكثر باتباع طريق المناقصة أو الممارسة بنوعيهما أو طريق الاتفاق المباشر وبما يتفق وطبيعة العملية محل الطرح وإبرام اتفاق إطارى مع من يقع عليه الاختيار يتضمن القواعد والشروط التى سيجرى من خلالها إصدار أوامر التوريد أو الإسناد ، وذلك فى أى من الحالات الآتية :
1 - الحاجة للتعاقد المتكرر على الأصناف أو لتنفيذ الأعمال أو الخدمات أو تقديم الدراسات الاستشارية ، والتى تتسم أى منها بالعمومية أو شيوع الاستخدام .
2 - توقع الجهة الإدارية وفقا للمجرى العادى للأمور بسبب طبيعة الأصناف أو الأعمال أو الخدمات أو الدراسات الاستشارية المطلوبة أن الحاجة ستنشأ إليها مستقبلا بصورة عاجلة ، دون أن يكون معلوما لديها على وجه الدقة توقيت توريدها أو تنفيذها أو كمياتها .
3 - الحالات الأخرى التى ترى الجهة الإدارية مناسبة اتباع هذا النمط من التعاقدات بما فى ذلك استهداف تنمية بعض الصناعات أو تنميط الاحتياجات وغيرها من الحالات المماثلة .
ويشترط أن تتضمن شروط الطرح المواصفات الفنية ، والبيانات الإحصائية لمعدلات الطلب ، ومعدلات الاستهلاك التاريخية ، والمؤشرات المستقبلية الاسترشادية لمحل الطرح والتعاقد أو أطر الأعمال أو الخدمات أو الدراسات الاستشارية ، بحسب الأحوال .
ويكون اتباع الاتفاقية الإطارية وفقا للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص بالجهة الإدارية أو قرار مجلس الوزراء فى حال تعدد الجهات الإدارية ، وذلك بعد موافقة وزيرى المالية والتخطيط .
وتبين اللائحة التنفيذية لهذا القانون قواعد وإجراءات إبرام أو إنهاء الاتفاقية الإطارية ، وأنماطها المختلفة ، ومدتها ، وإصدار أوامر التوريد أو الإسناد ، وأداء التأمين وفقا لها .$m248$,'7f3a02ef0ffd3747eb49277ad37b0bc7'),
(66,0,$m248$المادة 66$m248$,$m248$مع عدم الإخلال بأحكام قانون حماية حقوق الملكية الفكرية الصادر بالقانون رقم 82 لسنة 2002 ، يجوز للجهة الإدارية ودون التقيد بطرق التعاقد المنصوص عليها فى هذا القانون أن تعلن عن مسابقة للحصول على عمل ابتكارى يتم اختياره من خلال لجنة تحكيم متخصصة ومحايدة تشكل بقرار من السلطة المختصة لهذا الغرض وفقا لعناصر وأسس التقييم المعلنة لتحديد العمل الفائز .
وتحدد شروط المسابقة كيفية منح الجوائز أو المكافآت أو الامتيازات ، وكذا كيفية التعامل مع ملكية الأعمال المقدمة من المتسابقين .
ويكون الإعلان عن المسابقة بإحدى الصحف اليومية واسعة الانتشار ، بالإضافة إلى النشر عنها على بوابة التعاقدات العامة .$m248$,'527497387b299f56bb00c85c7b129066'),
(67,0,$m248$المادة 67$m248$,$m248$تسرى أحكام هذا الباب على عمليات بيع وتأجير المنقولات والعقارات ، والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات .$m248$,'631479d75cecc7f568cdef1bbd9ed624'),
(68,0,$m248$المادة 68$m248$,$m248$يكون التعاقد بطريق المزايدة المحدودة فى أى من الحالات الآتية :
1 - الأصناف التى يخشى عليها من التلف ببقاء تخزينها .
2 - الأصناف التى تتطلب طبيعتها قصر بيعها على المرخص لهم بالتعامل فيها .
3 - الحالات العاجلة التى لا تحتمل اتباع إجراءات المزايدة العلنية العامة أو بالمظاريف المغلقة .
4 - الحالات التى سبق عرضها فى مزايدة علنية عامة أو مزايدة بالمظاريف المغلقة لأكثر من مرة ، ولم تقدم عنها أى عروض أو لم يصل ثمنها إلى الثمن الأساسى ، وانتهت دراسة الجهة الإدارية إلى مناسبة تغيير طريقة الطرح .$m248$,'f32d11a45ba3ca6204cbdcf39ca9dd98'),
(69,0,$m248$المادة 69$m248$,$m248$يكون التعاقد بطريق المزايدة المحلية فيما لا يجاوز ثمنه الأساسى ستمائة ألف جنيه ، ويقصر الاشتراك فيها على المتزايدين المحليين الذين يقع نشاطهم داخل نطاق المحافظة التى ينفذ بدائرتها موضوع التعاقد .$m248$,'73a0652b16ecfa5d9a03ba5de09c1a38'),
(70,0,$m248$المادة 70$m248$,$m248$تسرى على بيع وتأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو استغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف ذات القواعد والإجراءات المنظمة لشراء المنقولات أو استئجارها فيما لم يرد بشأنه نص خاص ، وذلك كله بما لا يتعارض مع طبيعة البيع أو التأجير أو الترخيص أو الاستغلال .$m248$,'281d3a6c4726b19563068fecf7474e11'),
(71,0,$m248$المادة 71$m248$,$m248$يجوز فى الحالات الطارئة أو العاجلة التى لا تحتمل اتباع إجراءات المزايدة بجميع أنواعها ، أن يتم التعاقد على بيع أو تأجير المنقولات أو العقارات أو المشروعات التى ليس لها الشخصية الاعتبارية أو الترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف بطريق الاتفاق المباشر من خلال لجنة مشكلة لهذا الغرض بناء على ترخيص من :
1 - رئيس الهيئة ، أو رئيس المصلحة ومن له سلطاته فى الجهات الإدارية الأخرى أو رئيس الصندوق ، وذلك فيما لا تجاوز قيمته خمسمائة ألف جنيه .
2 - الوزير ، ومن له سلطاته أو المحافظ فيما لا تجاوز قيمته مليون جنيه .
ويجوز استثناء من أحكام الفقرة السابقة وبموافقة الوزير المختص بالجهة الإدارية ، فى الحالات التى سبق عرضها فى مزايدة علنية عامة أو بالمظاريف المغلقة لأكثر من مرة ، ولم تقدم عنها عروض أو لم يصل ثمنها إلى الثمن الأساسى أن يتم البيع أو التأجير أو الترخيص بالانتفاع أو بالاستغلال بالاتفاق المباشر ، وذلك على النحو الآتى :
1 - العقارات التى لا تجاوز قيمتها مليونى جنيه ، يتم إعلان الثمن الأساسى ، وبشرط ألا يقل سعر البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال عن هذا الثمن الأساسى .
2 - بيع المنقولات أو المشروعات التى ليس لها الشخصية الاعتبارية أو تأجيرها أو الترخيص بالمشروعات أو استغلالها بما فى ذلك المنشآت السياحية والمقاصف، بحسب الأحوال ، التى لا تجاوز قيمتها مليون جنيه بشرط ألا يقل ثمن البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال عن الثمن أو القيمة الأساسية .
وذلك كله بشرط أن يتم التعاقد مع مقدم العرض الأفضل شروطا والأعلى سعرا .
ولا يجوز لأى من هذه السلطات التفويض فى الاختصاصات الممنوحة لها للتعاقد بهذا الطريق .
ويجب على إدارة التعاقدات توثيق مبررات اتباع طريق الاتفاق المباشر ، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .$m248$,'6d1e2dce0f496efc95b7954b5a65f40f'),
(72,0,$m248$المادة 72$m248$,$m248$تسرى على شراء أو استئجار أو بيع أو تأجير العقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات فى الخارج أحكام هذا القانون ولائحته التنفيذية بما لا يتعارض مع الإجراءات المعمول بها فى الدولة محل التعاقد ، وفى حالة تعذر ذلك يتعين الحصول على موافقة مجلس الوزراء على التعاقد وفقا للشروط والقواعد التى يعتمدها بناء على اقتراح الوزير المختص بالجهة الإدارية .$m248$,'e0b56f374e795d9a484ffa3c164dcef5'),
(73,0,$m248$المادة 73$m248$,$m248$يكون التعاقد على الدراسات الاستشارية عن طريق المناقصة المحدودة أو المناقصة ذات المرحلتين أو المناقصة المحلية ، ويكون تقييم العطاءات بنظام النقاط ، على أن تتضمن شروط الطرح عناصر وأسس التقييم والحد الأدنى للقبول ، وكيفية التقييم للوصول إلى أفضلها شروطا وسعرا .
ويجوز استثناء فى العمليات ذات الطبيعة الروتينية أو البسيطة أو النمطية أو التى لها أطر فنية ثابتة التعاقد عليها بطريق المناقصة العامة أو المحلية أو الاتفاق المباشر إذا قدرت الجهة الإدارية أن أيا من هذه الطرق هو الأنسب بحسب طبيعة العملية وتتم الترسية فى هذه الحالات على أقل الأسعار من العروض المقبولة فنيا ، على أن تتضمن شروط الطرح المتطلبات الفنية والمؤهلات والخبرات وغيرها التى يتعين توافرها .
كما يجوز للجهة الإدارية التعاقد من خلال مناقصة محدودة أو مناقصة محلية أو اتفاق مباشر مع أحد الاستشاريين بذاته إذا قدرت أن المهام المطلوبة تعتمد بشكل كلى على خبراته ومؤهلاته .
ويصدر باتباع أى من هذه الطرق قرار مسبب من السلطة المختصة وفقا لظروف وطبيعة التعاقد ، وبما لا يتعارض مع القوانين المنظمة للمهن الحرة .
ويجوز للجهة الإدارية إجراء تأهيل مسبق قبل الطرح .$m248$,'8cc3b04a7a2dd1e9bb19e1adeb6f5af5'),
(74,0,$m248$المادة 74$m248$,$m248$مع مراعاة حكم المادة (63) من هذا القانون ، يجوز بموافقة السلطة المختصة التعاقد بالاتفاق المباشر مع أى من مقدمى الخدمات الأساسية الذى تمتلك الدولة فيه حصة حاكمة تسمح لها بتعيين أغلبية أعضاء مجلس إدارته أو التحكم على أى نحو فى القرارات الصادرة من مجلس إدارته أو من الجمعية العامة له على تقديم الخدمات الأساسية ومن ذلك الكهرباء ، والمياه ، والغاز وغيرها من الخدمات الأساسية اللازمة لتسيير المرفق العام ذات الطبيعة المماثلة والمحددة أسعارها من الدولة .
وفى هذه الحالة يستثنى مقدمو الخدمات الأساسية من تقديم خطاب ضمان الدفعة المقدمة ومن أداء التأمين بنوعيه ، ويكتفى بما يقدم منهم من تعهدات أو ضمانات تقرها السلطة المختصة .
وللسلطة المختصة التفويض فى أى من الاختصاصات المنصوص عليها فى هذه المادة .$m248$,'51dd044cc5b53a98305ed9e2960d6ebd'),
(75,0,$m248$المادة 75$m248$,$m248$يجب على الجهة الإدارية مراعاة إمكانيات المشروعات المتوسطة والصغيرة والمتناهية الصغر عند فتح باب التسجيل للمشتغلين بالأنشطة المختلفة أو عند إعدادها لشروط التأهيل المسبق أو مستندات الطرح ومعايير التقييم وغيرها ، وبما يتيح لهذه المشروعات المشاركة فى العمليات التى يتم طرحها ، ودون أن يؤثر ذلك على تكافؤ الفرص والالتزام بمعايير الجودة والأداء فى التنفيذ .
كما يجب على الجهة الإدارية إتاحة نسبة لا تقل عن (20%) من قيمة احتياجاتها السنوية للتعاقد مع تلك المشروعات ، ومن واقع ما تدرجه ويتم إقراره بخطتها السنوية المنصوص عليها بالمادة (9) من هذا القانون .
وعلى ممثلى وزارة المالية من أعضاء اللجان المنصوص عليها فى هذا القانون وبالوحدات الحسابية بالجهات الإدارية التحقق من التزام الجهات بتنفيذ ذلك .$m248$,'c20d9708007100e8997729bf593f5bf0'),
(76,0,$m248$المادة 76$m248$,$m248$فى حالات الضرورة ، يجوز لمجلس الوزراء أن يصرح لجهة إدارية بعينها ، لاعتبارات يقدرها ترتبط بطبيعة عمل تلك الجهة ونشاطها أو طبيعة العملية ، بالتعاقد بأى من طرق التعاقد المنصوص عليها بالمادة (7) من هذا القانون وفقا للشروط والقواعد التى يحددها .
كما يجوز لمجلس الوزراء أن يرخص لجهة إدارية بعينها بالتعاقد بالاتفاق المباشر مع الشخص الطبيعى أو الاعتبارى المصرى أو الأجنبى حال تقدمه بمشروع استثمارى متكامل شاملا التمويل إذا كان هذا المشروع يحقق للجهة الإدارية المتعاقدة الأهداف الاقتصادية والتنموية للدولة ، وذلك بناء على عرض من الوزير المختص بنتائج الجدوى الفنية والاقتصادية والاجتماعية للمشروع والدراسة التحليلية للهيكل الفنى والمالى له ، وعلى أن يكون ذلك بعد موافقة وزيرى المالية والتخطيط ، وذلك كله ما لم ينظم التعاقد قوانين أخرى .
وإذا لم ينطو المشروع المقدم على حقوق ملكية فكرية حصرية لمقدمه ورغبت الجهة الإدارية فى تنفيذه ، يحق لها فى ضوء دراستها طرحه للحصول على عطاءات تنافسية له، ويتم التعاقد وفقا للأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرامه ، والتى تقرها اللجنة المنصوص عليها بالمادة (4) من هذا القانون ويعتمدها مجلس الوزراء ويصدر بها دليل إجرائى ينظمها .$m248$,'3926af0e6bfcf8f50d77a00ea447a71d'),
(77,0,$m248$المادة 77$m248$,$m248$يجوز لوزارات الدفاع والإنتاج الحربى والداخلية وأجهزتها فى حالات الضرورة التى تقتضيها اعتبارات الأمن القومى ، التعاقد بطريق المناقصة المحدودة أو المناقصة ذات المرحلتين أو المناقصة المحلية أو الممارسة المحدودة أو الاتفاق المباشر ، وذلك مع إعمال أحكام القانون رقم 204 لسنة 1957 بشأن إعفاء العقود الخاصة بالتسليح من الضرائب والرسوم والقواعد المالية .
وللسلطة المختصة التفويض فى أى من الاختصاصات المقررة فى هذا الشأن .$m248$,'bf30d1365b2ee87eed4aee692f5ad79b'),
(78,0,$m248$المادة 78$m248$,$m248$يجوز للجهات المخاطبة بأحكام هذا القانون التعاقد فيما بينها بطريق الاتفاق المباشر بموافقة السلطة المختصة بكل منها ، وذلك دون التقيد بالإجراءات والحدود المالية الواردة بهذا القانون ، كما يجوز أن تنوب عن بعضها فى مباشرة إجراءات التعاقد فى مهمة معينة وفقا للقواعد المعمول بها فى الجهة الإدارية طالبة التعاقد .
ويحظر التنازل لغير هذه الجهات عن العقود التى تتم فيما بينها .
وتسرى أحكام هذه المادة على الهيئة العربية للتصنيع ، والهيئة القومية للإنتاج الحربى ، والمخابرات العامة ، ويجوز لأى منها إسناد التعاقدات المبرمة تطبيقا لأحكام هذه المادة مباشرة إلى أى من وحداتها التابعة .$m248$,'67f657a6d727c66628eaab457099fb6a'),
(79,0,$m248$المادة 79$m248$,$m248$استثناء من أحكام هذا القانون ، يجوز للجهة الإدارية التعاقد على الصفقات التى تتطلب منها السرعة فى اتخاذ قرار التعاقد بحكم طبيعتها أو التقلبات فى أسعارها وكمياتها الاقتصادية أو التى تغطى مدى زمنى مستقبلى أو العمليات المتعلقة بالمعاملات المنجزة فى الأسواق المالية الدولية أو عقود المشتقات المالية والمشتريات الآجلة والمستقبلية وما يرتبط بها ، وذلك كله وفقا للممارسات التجارية الدولية المطبقة التى تحددها السلطة المختصة بالجهة الإدارية وتقرها اللجنة المنصوص عليها بالمادة (4) من هذا القانون ويعتمدها مجلس الوزراء .
كما يجوز للجهة الإدارية استثناء من أحكام هذا القانون إبرام التعاقدات ذات الطبيعة المركبة أو المتشابكة أو متعددة الأطراف ، أو التعاقدات التى تتطلب هيكلا تمويليا كمشروعات البناء والتملك والتشغيل ونقل الملكية BOOT ، والبناء والتملك والتشغيل BOO ، والتصميم والاشتراء والتشييد + التمويل EPC+Finance وغيرها ، وذلك إذا كانت هذه التعاقدات تحقق للجهة الإدارية المتعاقدة أهدافها الاقتصادية والتنموية العاجلة ، أو استلزمت الظروف الاقتصادية أو الاجتماعية سرعة إتمامها فى توقيت معين . وتتم هذه التعاقدات وفقا للأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرامها والتى تقرها اللجنة المنصوص عليها فى المادة (4) من هذا القانون ، ويعتمدها مجلس الوزراء ويصدر بها دليل إجرائى ينظمها ، على أن يضع الوزير المختص بالجهة الإدارية القواعد الخاصة بكل مشروع بالاتفاق مع وزيرى المالية والتخطيط ، ويجب اعتماد هذه القواعد من مجلس الوزراء بناء على عرض الوزير المختص بالجهة الإدارية .
وتبين اللائحة التنفيذية لهذا القانون ضوابط وأوضاع إبرام هذه التعاقدات .$m248$,'6deffe5b0acbdeb40fe93000e4af864b'),
(80,0,$m248$المادة 80$m248$,$m248$يجوز التعامل بالاتفاق المباشر على العقارات بالبيع أو التأجير أو الترخيص بالانتفاع أو بالاستغلال فى حالات الضرورة ، لتحقيق اعتبارات اجتماعية أو اقتصادية تقتضيها المصلحة العامة ، وذلك بالاتفاق بين وزير المالية والوزير المختص بالجهة الإدارية أو المحافظ المختص ، بناء على مبررات تبديها الوزارة أو المحافظة طالبة الترخيص بالتعامل مع اقتراح مقابل التعامل وأسلوب السداد ، على أن تتحقق اللجنة العليا للتقييم بالهيئة العامة للخدمات الحكومية من مناسبة هذا المقابل ، ويعرض وزير المالية ما تنتهى إليه اللجنة على مجلس الوزراء للاعتماد .
وذلك كله وفقا للقواعد وبالضوابط والشروط التى يصدر بها قرار من مجلس الوزراء بناء على اقتراح وزير المالية .$m248$,'a7b61b6527175cc4a35b2a16ccc8cdd0'),
(81,0,$m248$المادة 81$m248$,$m248$مع مراعاة الحالات التى يحظر هذا القانون التفويض فيها . يجوز للسلطة المختصة أن تفوض فى أى من اختصاصاتها الواردة به لشاغلى الوظائف القيادية دون غيرهم ، وذلك وفقا للضوابط والإجراءات التى تبينها اللائحة التنفيذية لهذا القانون .$m248$,'36d1ed80dc6b59a0fdc21637b9080dfb'),
(82,0,$m248$المادة 82$m248$,$m248$تلتزم إدارة التعاقدات بالجهة الإدارية بفتح ملف لكل عملية تحفظ به جميع المستندات والبيانات المتعلقة بالإجراءات ، ويتضمن جميع المخاطبات الداخلية والمراسلات التى أرسلت منذ بداية إجراءات العملية ، مع الحفاظ على ما يحتويه الملف من مستندات وبيانات .
ولا يجوز إفشاء أى من هذه المستندات والبيانات أو الاطلاع عليها من أطراف أو أفراد غير معنيين بها إلا لجهات التفتيش والفحص والمراجعة ، وفقا للقوانين والقرارات المنظمة لذلك .$m248$,'c38953c70f285b0063c050ca82adef11'),
(83,0,$m248$المادة 83$m248$,$m248$تتولى الهيئة العامة للخدمات الحكومية نشر هذا القانون ولائحته التنفيذية وأى تعديلات عليهما ، وكذلك المنشورات العامة والكتب الدورية والقرارات المتعلقة بتطبيقهما فور صدورها، بما فيها قرارات الشطب أو إعادة القيد وغيرها، وذلك على بوابة التعاقدات العامة بالإضافة إلى قواعد النشر المقررة .$m248$,'05a96928e03663d7124d26bee625539e'),
(84,0,$m248$المادة 84$m248$,$m248$يجب على الجهات الخاضعة لأحكام هذا القانون اتخاذ إجراءات التعاقد إلكترونيا وفقا لما يتم ميكنته من إجراءات من خلال منظومة موحدة ومنتظمة ومؤمنة إلكترونيا ، على أن تتبع الإجراءات الميكنة حال اكتمالها وانتظامها .
وتبين اللائحة التنفيذية لهذا القانون محتوى المنظومة الإلكترونية وكيفية تشغيلها والضوابط والإجراءات المتبعة ذات الصلة .$m248$,'12afb95296f1f64eac019e7d7c691d05'),
(85,0,$m248$المادة 85$m248$,$m248$تمسك كل جهة إدارية سجلا لقيد الأسماء والبيانات الكافية للراغبين فى التعامل معها متضمنا تصنيفهم طبقا لقدراتهم الفنية والمالية وسمعتهم التجارية وخبراتهم السابقة وشهادات مزاولة النشاط ورقم الحساب البنكى الخاص بكل منهم ، وغيرها من المستندات المطلوبة طبقا للقوانين المنظمة ليتم من خلاله التعامل معهم ، ويتعين على الجهة الإدارية التحقق من تحديث تلك البيانات بصفة دورية سنويا قبل بداية العام المالى بشهر على الأقل .
ولا يجوز للجهة الإدارية التعامل مع المسجلين لديها بسجلاتها أو غيرهم إلا بعد تسجيلهم لبياناتهم على بوابة التعاقدات العامة أو تحديثها حال تعديلها ، وأن تطابق الجهة الإدارية تلك البيانات واعتمادها من واقع قاعدة البيانات ، على أن تتضمن بياناتهم رقم السجل التجارى أو الصناعى أو المهنى أو سجل مزاولة المهنة بحسب الأحوال ، ورقم البطاقة الضريبية أو أى بيانات أخرى ليتم من خلاله التعامل معهم .
وتمسك الهيئة العامة للخدمات الحكومية سجلا لقيد أسماء الممنوعين من التعامل مع أى جهة من الجهات الإدارية المذكورة سواء كان المنع بنص فى القانون ، أو بموجب قرارات إدارية ، أو لمن صدر ضده حكم نهائى فى إحدى الجرائم الواردة فى المادة (93) من هذا القانون ، ويحظر التعامل مع المقيدين فى هذا السجل ما لم يتم رفع هذا الحظر بانتفاء سببه .
ويقع باطلا كل عقد أو اتفاق يتم بالمخالفة لأحكام الفقرة السابقة .$m248$,'651e963bca711cd5a3710c527b93dbcb'),
(86,0,$m248$المادة 86$m248$,$m248$يجب على الجهة الإدارية استيفاء تقييم أداء المتعاقدين معها فى نهاية كل عام مالى أو بانتهاء التعاقد وفقا للنماذج التى تعدها والمعايير التى تحددها الهيئة العامة للخدمات الحكومية ، ويتم نشرها على بوابة التعاقدات العامة على أن يتضمن النشر أسماء المتعاقدين الذين أخلوا بشروط التعاقد والجزاءات التى وقعت عليهم ، ويستثنى من النشر العمليات التى تتطلب اعتبارات الأمن القومى أن تتم بطريقة سرية وفقا لما تقدره السلطة المختصة ، بالإضافة إلى الاحتفاظ بها بملف العملية ، على أن يتم توثيق أداء المتعاقد أولا بأول ، وبما يسهم فى إنجاز مشروعات الدولة بالجودة المطلوبة وفى الزمن المحدد .
كما يجب على الجهة الإدارية فى نهاية كل عام مالى إجراء استقصاء مع المتعاقدين معها بغرض إظهار الإيجابيات ، والوقوف على الإجراءات السلبية التى واجهتهم فى تعاملاتهم ، واتخاذ الإجراءات التصحيحية اللازمة ، وتقويم أداء العاملين بإدارة التعاقدات .$m248$,'16c4a3c1d5a0ec625c5ac01654a98486'),
(87,0,$m248$المادة 87$m248$,$m248$يجب على كل جهة إدارية إعداد قاعدة بيانات لجميع العقارات المملوكة لها ، وما تم التصرف فيه منها وأسلوب التصرف وقيمته والبيانات الكافية عن المتصرف إليهم .
وتخطر الهيئة العامة للخدمات الحكومية بصفة دورية بجميع ما يثبت من بيانات بتلك الجهات لإثباتها بقاعدة البيانات المركزية المنشأة لديها .$m248$,'369776b5fcd0a9408398dc2a34f87df7'),
(88,0,$m248$المادة 88$m248$,$m248$يشترط لشغل وظائف التعاقدات بالجهات الخاضعة لأحكام هذا القانون أو الاستمرار فى شغلها اجتياز التدريب اللازم لذلك . ويحدد وزير المالية بداية تنفيذ ذلك ومراحله، وتضع وزارة المالية (الهيئة العامة للخدمات الحكومية) لمقدمى خدمات التدريب والمراكز التدريبية برامج هذا التدريب ومناهجه ، كما يجوز لها المشاركة فى المبادرات التى من شأنها رفع كفاءة المتعاملين مع الجهات الإدارية ، وتحدد اللائحة التنفيذية لهذا القانون مستوى البرامج التدريبية المطلوبة ، وإجراءات التقدم لها ، وآلية اعتمادها ، وغيرها .$m248$,'8676cf940c99c844a60e06ab24294e63'),
(89,0,$m248$المادة 89$m248$,$m248$مع عدم الإخلال بحق ذوى الشأن فى إقامة الدعوى المدنية أو الجنائية ، يؤاخذ تأديبيا كل من خالف أحكام هذا القانون أو لائحته التنفيذية ، أو مدونة السلوك الوظيفى للعاملين بالتعاقدات والتى يصدر بها قرار من وزير المالية .$m248$,'bb645da3e5ef11c655b4559f35524301'),
(90,0,$m248$المادة 90$m248$,$m248$تتولى إدارة الفتوى المختصة بمجلس الدولة مراجعة مشروعات العقود التى تكون الجهة الإدارية طرفا فيها ، ونماذج كراسات الشروط ، وأنماط العقود النموذجية والأدلة الإرشادية وغيرها مما هو منصوص عليه فى المادة (19) من هذا القانون .$m248$,'f2678205b249feb99a7c6cc43b869a8d'),
(91,0,$m248$المادة 91$m248$,$m248$يجوز لطرفى العقد فى حالة حدوث خلاف أثناء تنفيذه ، وقبل اللجوء إلى القضاء أو التحكيم بحسب الأحوال ، الاتفاق على تسويته عن طريق التوفيق أو الوساطة ، وذلك إذا تضمنت شروط الطرح أو العقد جواز ذلك ، وبموافقة السلطة المختصة مع التزام كل طرف بالاستمرار فى تنفيذ التزاماته الناشئة عن العقد .
كما يجوز للمتعاقد اللجوء إلى القضاء للمطالبة بالتعويض عما يكون قد لحقه من أضرار نتيجة إخلال الجهة الإدارية بتنفيذ التزاماتها الواردة بالعقد بخطأ منها ، ما لم يوافق الوزير المختص بالجهة الإدارية على اللجوء إلى التحكيم وتتضمنه شروط العقد ، ويتفق عليه الطرفان وفقا للقواعد والإجراءات المنصوص عليها فى قانون التحكيم فى المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة 1994$m248$,'c3b429ecfdb14c0a9d7dff799815e0e8'),
(92,0,$m248$المادة 92$m248$,$m248$لا يجوز للمتعاقد النزول عن العقد أو عن المبالغ المستحقة له كلها أو بعضها ، ومع ذلك يجوز أن يتنازل عن تلك المبالغ لأحد البنوك ، ويكتفى فى هذه الحالة بتصديق البنك دون الإخلال بمسئولية المتعاقد عن تنفيذ العقد ، كما لا يخل قبول نزوله عن المبالغ المستحقة له بما يكون للجهة الإدارية قبله من حقوق .$m248$,'fce03ef6347521f38d733d927b2f8b41'),
(93,0,$m248$المادة 93$m248$,$m248$تخطر الجهات المختصة الهيئة العامة للخدمات الحكومية بمن صدر بحقه حكم نهائى فى إحدى الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات ، أو فى جرائم التهرب الضريبى أو الجمركى .$m248$,'363003d57a2357f474909fd143492343');

INSERT INTO m248_ver VALUES
(0,0,1,$m248$قانون رقم 182 لسنة 2018 بإصدار قانون تنظيم التعاقدات التى تبرمها الجهات العامة
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m248$,'8d040080b823fdcd4310ef3e7bfec9f7',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(1,-1,1,$m248$يعمل بأحكام القانون المرافق فى شأن تنظيم التعاقدات التى تبرمها الجهات العامة ، وتسرى أحكامه على الجهات التى تضمها الموازنة العامة للدولة ، ووحدات الجهاز الإدارى للدولة من وزارات ومصالح وأجهزة لها موازنات خاصة ، ووحدات الإدارة المحلية ، والهيئات العامة الخدمية والاقتصادية ، وما يتبع هذه الجهات من وحدات ذات طابع خاص والصناديق الخاصة فيما عدا صناديق الرعاية الاجتماعية المنشأة بها والتى تعتمد فى تمويلها بصفة أساسية على الاشتراكات المالية من أعضائها ، والمشروعات الممولة من الحسابات الخاصة ، دون الإخلال بأحكام الاتفاقيات الدولية ، وذلك كله فيما لم يرد فى شأنه نص خاص فى القوانين أو القرارات الصادرة بإنشائها أو بتنظيمها ، أو فى لوائحها الصادرة بناء على تلك القوانين أو القرارات .$m248$,'84008c25cccc3e461313cabcce0217be',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(2,-1,1,$m248$لا تخل أحكام القانون المرافق بقانون تنظيم مشاركة القطاع الخاص فى مشروعات البنية الأساسية والخدمات والمرافق العامة الصادر بالقانون رقم 67 لسنة 2010 ، وغيره من قوانين التزامات المرافق العامة القطاعية .
ولا تخل أحكامه بالقانون رقم 5 لسنة 2015 فى شأن تفضيل المنتجات المصرية فى العقود الحكومية ، وذلك فيما لم يرد بشأنه نص خاص .
كما لا تخل أحكامه بقانون الاستثمار الصادر بالقانون رقم 72 لسنة 2017$m248$,'725e251d6e2742044120a54dd8b7425e',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(3,-1,1,$m248$يلغى قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998
واستثناء من حكم الفقرة السابقة ، تستمر العمليات التى تم طرحها أو التعاقد عليها بالفعل قبل تاريخ العمل بهذا القانون خاضعة لأحكام قانون تنظيم المناقصات والمزايدات المشار إليه ، إلى حين إتمام تنفيذ التعاقد .$m248$,'b0c8e48d0a3c12737d2be3f17882be80',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(4,-1,1,$m248$يصدر وزير المالية اللائحة التنفيذية للقانون المرافق خلال ستة أشهر من تاريخ العمل به ، ويجب أن تتضمن اللائحة القواعد والإجراءات وغيرها من الضوابط اللازمة لتنفيذ أحكامه .
وإلى أن تصدر هذه اللائحة يستمر العمل باللوائح والقرارات القائمة فى تاريخ العمل بهذا القانون فيما لا يتعارض مع أحكام القانون المرافق .$m248$,'2b0a6a24386255d777aed79beb021104',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(5,-1,1,$m248$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتبارا من مضى ثلاثين يوما على تاريخ نشره .$m248$,'585d9e6e2d0706e792074afe3051734b',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(1,0,1,$m248$فى تطبيق أحكام هذا القانون ، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
الجهة الإدارية : أى من الجهات العامة أو الهيئات أو الوحدات المنصوص عليها فى المادة الأولى من مواد إصدار هذا القانون ، وما يتبعها من صناديق خاصة أو حسابات على النحو المبين فى المادة المشار إليها .
السلطة المختصة : الوزير ، ومن له سلطاته ، أو المحافظ ، أو رئيس مجلس إدارة الهيئة العامة أو الصندوق ، أو من يعادلهم من سلطات فى الجهات المنصوص عليها فى المادة الأولى من مواد إصدار هذا القانون ، كل فى نطاق اختصاصه .
بوابة التعاقدات العامة : الموقع الإلكترونى المخصص على شبكة المعلومات الدولية (الإنترنت) للنشر عن البيانات والمعلومات المتعلقة بالتعاقدات العامة التى تجريها الجهات الإدارية الخاضعة لأحكام هذا القانون ، والإجراءات المتعلقة بها فى الحدود المنصوص عليها به واللائحة التنفيذية له .
طلب إبداء الاهتمام : إجراء تتخذه الجهة الإدارية ، وتعلن عنه فى العمليات التى تتطلب معرفة مسبقة للمشتغلين بنشاط معين والوقوف على قدراتهم وخبراتهم بهدف الوصول إلى قائمة مختصرة منهم ، أو معرفة مدى اهتمامهم بالمشاركة فى العملية المقترح طرحها .
التأهيل المسبق : إجراء تتخذه الجهة الإدارية ، وتعلن عنه للتأكد من توافر القدرات الفنية والإمكانيات المالية والإدارية والبشرية وغيرها لدى الموردين أو المقاولين أو مقدمى الخدمات أو الاستشاريين للقيام بتنفيذ أحد العقود بالكفاءة المطلوبة قبل دعوتهم لتقديم العطاءات ، وذلك وفقا لمتطلبات ومعايير التقييم المحددة بمستندات طلب التأهيل المسبق .
مقاولات الأعمال : كل ما يدخل ضمن التصنيف الصادر عن الاتحاد المصرى لمقاولى التشييد والبناء ، ويعتمد من وزير الإسكان والمرافق والمجتمعات العمرانية ، وتخطر به الهيئة العامة للخدمات الحكومية لنشره على بوابة التعاقدات العامة .
الخدمات : ما يكون التعاقد فيها على أساس أداء عمل مادى يمكن توصيفه ، ومن ذلك: الصيانة ، الأمن ، النظافة ، رسم الخرائط ، التصوير بالأقمار الصناعية ، تطوير البرمجيات ، وخدمات النقل .
الدراسات الاستشارية : ما يغلب عليه الطابع الفكرى أو الإرشادى ، ومن ذلك: الدراسات الهندسية أو المهنية أو الاقتصادية أو المالية أو الإدارية أو القانونية ، بما فى ذلك مهام الإعداد أو التصميم أو الإشراف على التنفيذ أو التقييم أو الاستلام .
الأعمال الفنية : ما يتسم بالإبداع الفنى وفقا للطابع الشخصى ، ومن ذلك: الرسم ، التصوير ، تأليف الكتب ، والبحوث .
التقييم بنظام النقاط : أحد أساليب تقييم العطاءات ، يتم فيه تطبيق معايير الجودة الفنية والسعر مجتمعين عن طريق تحديد أسس وعناصر التقييم ، والوزن النسبى للجانب الفنى أو الفنى والمالى للعطاءات بحسب طبيعة العملية ، والحد الأدنى للقبول وصولا إلى درجات أو نسب إجمالية لكل عطاء ، بما يكفل تحديد أولوية ترتيبه .
التواطؤ : ترتيب يتم بين طرفين أو أكثر قبل أو بعد تقديم العطاء ، لتحقيق غرض غير مشروع أو للإخلال بمبدأ تكافؤ الفرص ، ومبدأ حرية المنافسة بما فى ذلك التأثير بشكل مباشر أو غير مباشر على تصرفات طرف آخر ، بهدف تقسيم العقود بين مقدمى العطاءات أو تثبيت أسعار العطاءات بشكل غير تنافسى .
الاحتيال : أى فعل أو امتناع عن فعل يؤدى إلى تضليل الطرف الآخر بهدف الحصول على منفعة مالية أو عينية أو أى منفعة أخرى ، أو التأثير فى العملية المطروحة ، أو لتجنب الالتزام فى تنفيذ العقد .
الفساد : أى عرض أو إعطاء أو استلام أو طلب لأى شىء ذى قيمة ، أو الحث على ارتكاب أفعال غير مناسبة ، سواء بطريقة مباشرة أو غير مباشرة ، للتأثير بشكل غير مشروع على أداء طرف آخر فى العملية المطروحة أو فى تنفيذ العقد .$m248$,'68ce50be93cd757302465cc113792640',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(2,0,1,$m248$يهدف تطبيق أحكام هذا القانون إلى :
1 - تنظيم إجراءات تخطيط وتنفيذ التعاقدات العامة ، ومتابعة تنفيذ العقود .
2 - تحقيق كفاءة وفاعلية الإنفاق العام .
3 - تعزيز مبادئ الحوكمة ، وتطبيق معايير العلانية والشفافية والنزاهة وحرية المنافسة والمساواة وتكافؤ الفرص ، وتجنب تعارض المصالح .
4 - تطبيق أساليب الإدارة الحديثة ، والانتقال مرحليا إلى استخدام تكنولوجيا المعلومات فى الإجراءات .
5 - تطوير طرق الشراء والبيع وأنماط التعاقد لمسايرة التطورات الاقتصادية ، وتلبية احتياجات الجهات الإدارية بفاعلية .
6 - توفير معاملة عادلة للمتعاملين من مجتمع الأعمال مع الجهات الإدارية ، وفى ذات الوقت منع ممارسات التواطؤ والاحتيال والفساد والاحتكار .
7 - تشجيع الجهات الخاضعة لأحكام هذا القانون على تبنى الحلول والمبادرات الابتكارية والتقنيات المتطورة عند التعاقد على تلبية احتياجاتها ، وكذلك تبنى سياسات التعاقد المستدام .
8 - تهيئة المناخ للشركات والمشروعات المتوسطة والصغيرة والمتناهية الصغر للمنافسة فيما يتم طرحه من عمليات .$m248$,'417f67986cd424c02c1f915484a39eb9',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(3,0,1,$m248$تنشأ بالجهة الإدارية إدارة للتعاقدات ، أيا كان مستواها الوظيفى بالهيكل التنظيمى ، تشكل من عدد كاف من العناصر المؤهلة والمدربة ، وتتولى مباشرة الاختصاصات الآتية :
1 - تخطيط الاحتياجات السنوية للجهة الإدارية ، واتخاذ الإجراءات اللازمة للتعاقد عليها .
2 - متابعة تنفيذ العقود التى يتم إبرامها ، وتلقى وإرسال الإخطارات اللازمة ، واتخاذ الإجراءات الواجبة طبقا لأحكام هذا القانون ولائحته التنفيذية وما تتضمنه العقود المبرمة .
3 - التنسيق مع الإدارات والجهات المعنية ، وإعداد وتقديم جميع البيانات والتقارير المطلوبة فى شأن التعاقدات العمومية .
4 - القيام بجميع المهام الأخرى المنصوص عليها فى هذا القانون ولائحته التنفيذية .$m248$,'f161ad8d06f47355b5eacbdab8ca6cda',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(4,0,1,$m248$تنشأ لجنة للمؤشرات والتغيرات الاقتصادية تضم الوزراء المعنيين بالشئون الاقتصادية ، وتختص بدراسة المشروعات والصفقات والتنبؤ ورصد وتحليل ودراسة المؤشرات والتغيرات الاقتصادية التى تؤثر فى توفير متطلبات الجهات الإدارية بما يدعم جهودها فى تقديم الخدمات المنوطة بها وفقا لاختصاصاتها بالجودة المطلوبة ، وتحسينها ورفع كفاءتها بشكل مستمر وبما يسهم فى جهود الدولة فى مجالات التنمية الاقتصادية .
وتعد اللجنة تقريرا بنتائج أعمالها وتوصياتها تعرضه على مجلس الوزراء لاعتماده ، واتخاذ ما يلزم من إجراءات لتنفيذ ما ورد به .
ويصدر بتشكيل اللجنة وقواعد وإجراءات عملها قرار من رئيس مجلس الوزراء .$m248$,'9163e2f8301669548cc1c38888128150',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(5,0,1,$m248$يتولى مكتب شكاوى التعاقدات العمومية التابع لوزير المالية مباشرة تلقى الشكاوى المتعلقة بأى مخالفة لأحكام هذا القانون ولائحته التنفيذية وفحصها واتخاذ قرار فى شأنها دون مقابل ، ما لم تتطلب دراستها خبرات فنية متخصصة تمكنه من البت فيها ، وتكون قراراته ملزمة لطرفى الشكوى ، ويجب على الجهة الإدارية تنفيذ القرار خلال مدة لا تجاوز سبعة أيام من تاريخ تسلمه ودون أن يخل ذلك بحق مقدم الشكوى فى اللجوء إلى القضاء .
ويصدر بتنظيم العمل بالمكتب ، واختصاصاته الأخرى ، والمدد الزمنية لتلقى الشكاوى والبت فيها ، وآليات الاستعانة بالخبرات الفنية قرار من رئيس مجلس الوزراء .
ويكون لكل ذى شأن التقدم إلى الجهة الإدارية بشكواه كتابة بخصوص أى إجراء من إجراءات التعاقد وفى ذات التوقيت إخطار مكتب شكاوى التعاقدات العمومية بصورة منها ، وإذا لم يفصل فيها بمعرفة الجهة الإدارية يكون له الحق فى التقدم بشكواه إلى المكتب وذلك قبل اللجوء إلى جهات القضاء .
ويجوز للمكتب وقف إجراءات العملية محل الشكوى لمدة يحددها قرار رئيس مجلس الوزراء للفصل فيها إذا كانت هناك ضرورة لذلك عدا الحالات الطارئة أو العاجلة التى يقدرها وفقا للاعتبارات التى تقدمها الجهة الإدارية ، ويلتزم المكتب بنشر نتيجة ما ينتهى إليه فحصه للشكاوى المقدمة له على بوابة التعاقدات العامة .$m248$,'d60582a6483e4ce6ce28a38e0426cb24',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(6,0,1,$m248$تخضع طرق التعاقد والإجراءات المنصوص عليها فى هذا القانون لمبادئ الشفافية ، وحرية المنافسة ، والمساواة ، وتكافؤ الفرص .$m248$,'3d26ce3c6c00c618422fcadcbd5a83fc',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(7,0,1,$m248$يكون التعاقد وفق أحكام هذا القانون فى الحالات وبالطرق الآتية :
1 - يكون التعاقد على شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية بطريق المناقصة العامة ، ويجوز استثناء وبقرار مسبب من السلطة المختصة بناء على عرض إدارة التعاقدات إجراء هذا التعاقد بإحدى الطرق الآتية :
(أ) الممارسة العامة .
(ب) الممارسة المحدودة .
(ج) المناقصة المحدودة .
(د) المناقصة ذات المرحلتين .
(هـ) المناقصة المحلية .
(و) الاتفاق المباشر .
2 - يكون التعاقد على بيع أو تأجير المنقولات أو العقارات أو المشروعات التى ليس لها الشخصية الاعتبارية ، والترخيص بالانتفاع أو استغلال العقارات والمشروعات ومن ذلك المنشآت السياحية والمقاصف عن طريق مزايدة علنية عامة أو مزايدة بالمظاريف المغلقة ، ويجوز استثناء بقرار مسبب من السلطة المختصة بناء على عرض إدارة التعاقدات إجراء هذا التعاقد بإحدى الطرق الآتية :
(أ) المزايدة المحدودة .
(ب) المزايدة المحلية .
(ج) الاتفاق المباشر .
ويجوز للجهة الإدارية التعاقد على احتياجاتها باتباع أى من طرق التعاقد الواردة بالفقرة الأولى من هذه المادة للوصول إلى إبرام اتفاق إطارى وفقا لحكم المادة (65) من هذا القانون .
ولا يجوز بأى حال تحويل أى من طرق التعاقد المنصوص عليها فى هذه المادة إلى طريق تعاقد آخر .
وفى جميع الحالات يتم التعاقد فى الحدود وفقا للشروط والقواعد والإجراءات الواردة بهذا القانون ولائحته التنفيذية .$m248$,'9791e9cbbba19185f703b584e9befd0a',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(8,0,1,$m248$يتعين على الجهات الخاضعة لأحكام هذا القانون مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية المعلنة من مجلس الوزراء فى تعاقداتها ، ومراعاة اعتبارات الجودة والتكلفة ، وتحقيق أفضل قيمة للمال العام على أساس كامل دورة الحياة لما يطرح ، ويجب تضمين متطلبات التعاقد المستدام شروط ومعايير التأهيل والتقييم ومؤشرات الأداء وغيرها .$m248$,'89b086000c5e8cdc86c6124dde431350',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(9,0,1,$m248$يجب على الجهة الإدارية وضع خطة باحتياجاتها السنوية بالتزامن مع تقديم مشروع موازنتها لوزارة المالية ، تتضمن العمليات المتوقع تنفيذها خلال السنة المالية المقبلة وذلك وفقا للنماذج التى تعدها الهيئة العامة للخدمات الحكومية لهذا الغرض ، ويتم اعتمادها من السلطة المختصة دون غيرها ، وتنشر على بوابة التعاقدات العامة بغرض إعلام المتعاملين معها ، ودون أن يرتب ذلك أى التزامات على الجهة الإدارية .
وعلى الجهة الإدارية تعديل خطة احتياجاتها فى ضوء ما تم تخصيصه وإقراره لها من اعتمادات مالية ، واعتماد هذا التعديل من السلطة المختصة دون غيرها ، ويجب نشر الخطة المعدلة على بوابة التعاقدات العامة فور بداية السنة المالية .
ويستثنى من النشر الحالات التى تقتضى اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة .$m248$,'cc30a28231caf4b194d51e97bd2ad6e4',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(10,0,1,$m248$يحظر اللجوء إلى تجزئة محل العقود التى تسرى عليها أحكام هذا القانون بقصد التحايل لتفادى الشروط والقواعد والإجراءات وغير ذلك من ضوابط وضمانات منصوص عليها فيه .$m248$,'e275492e5f3c6d328905350c3e95f602',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(11,0,1,$m248$يجب على الجهة الإدارية قبل البدء فى اتخاذ إجراءات الطرح التحقق من توافر الاعتمادات المالية المخصصة لديها لتنفيذ موضوع التعاقد على أن تتضمن شروط الطرح ما يفيد ذلك ، ويكون التعاقد فى حدود الاحتياجات الفعلية الضرورية .
ويجوز إبرام عقود التوريدات والخدمات الدورية لمدة تجاوز السنة المالية بشرط ألا يترتب عليها زيادة الالتزامات فى إحدى السنوات المالية التالية عما هو مقرر فى السنة التى يتم فيها التعاقد .
ويكون التعاقد بالنسبة للمشروعات الاستثمارية المدرجة بالخطة فى حدود التكاليف الكلية المعتمدة ، على أن يتم الصرف فى حدود الاعتمادات المالية المقررة .
ويحظر التعاقد بقصد استنفاد الاعتمادات المالية ، كما يخطر التعاقد فى الشهر الأخير من السنة المالية إلا فى الحالات الاستثنائية التى تقتضيها ضرورة العمل ، وبموافقة السلطة المختصة .$m248$,'0675e50fc34a27bac7c289024547f0fc',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(12,0,1,$m248$يجوز للجهة الإدارية إصدار طلب للحصول على معلومات أو مقترحات أو مواصفات أو غيرها ، بغرض استيفاء إجراءات دراسة السوق أو تحديد احتياجاتها على نحو دقيق وفقا لمستجدات السوق أو لإعداد خطة احتياجاتها السنوية ، على أن تعلن عن ذلك بإحدى الصحف اليومية واسعة الانتشار أو توجه الطلب بدعوة المشتغلين بنوع النشاط المطلوب ، وذلك بالإضافة للنشر على بوابة التعاقدات العامة .$m248$,'a0a724f48c984719f24660f8eacc0cd0',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(13,0,1,$m248$للجهة الإدارية حال رغبتها فى معرفة المشاركين المحتملين أو المهتمين بالدخول فى عملية معينة تنوى طرحها بأى من طرق التعاقد أن تصدر طلبا لإبداء الاهتمام قبل الشروع فى طرح العملية على أن تعلن عنه بإحدى الصحف اليومية واسعة الانتشار وذلك بالإضافة لنشره على بوابة التعاقدات العامة ، ولا يجوز بأى حال أن يؤدى طلب إبداء الاهتمام إلى الحد من عدد المشاركين حال الطرح ، ولا أن يترتب عليه أى حق لمن قاموا بالرد على الطلب .$m248$,'8efce7107bf69afedfa3aa3eb10d56f8',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(14,0,1,$m248$يكون الطرح على أساس مواصفات ورسومات فنية دقيقة ومفصلة ، أو معايير أداء عامة وكافية توضع بمعرفة لجنة فنية متخصصة ، ويوصف موضوع الطرح وصفا موضوعيا وعاما ، ويحدد فى ذلك الخصائص التقنية والنوعية ذات الصلة والخصائص المتعلقة بالأداء والجودة ومتطلبات الفحص والاختبار ، على أن تراعى المواصفات القياسية المصرية أو الدولية مع تجنب الإشارة إلى علامة تجارية معينة أو اسم تجارى أو براءة اختراع أو تصميم أو نوع أو منتج أو بلد معين أو الرقم الوارد فى قوائم الموردين أو مواصفات تنطبق على نماذج خاصة أو مميزة أو إدراج إشارة إلى أى منها ، ويستثنى من ذلك الأصناف التى يتعذر توصيفها بإضافة عبارة ما يعادلها أو ما يماثلها أو ما يكافئها فى الأداء .$m248$,'09760466fb1c3077b373c38cf2060dd9',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(15,0,1,$m248$تشكل بقرار من السلطة المختصة لجنة تضم الخبرات والتخصصات النوعية اللازمة ، وتتولى إعداد القيمة التقديرية أو الثمن الأساسى للعملية محل التعاقد من خلال دراسة السوق وتعاقدات الجهة الإدارية السابقة أو تعاقدات غيرها من الجهات الإدارية إن وجدت ، آخذا فى الاعتبار المواصفات التى تتناسب واحتياجاتها ، وذلك قبل البدء فى اتخاذ إجراءات الطرح .
كما تتولى فى حالة البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال تحديد الثمن أو القيمة الأساسية لمحل التعاقد .
وفى جميع الأحوال ، يجب اعتماد القيمة التقديرية أو الثمن الأساسى من السلطة المختصة ، وتكون سرية فيما عدا الحالة المنصوص عليها فى المادة رقم (71) من هذا القانون .
ولا يجوز أن يشارك أعضاء اللجنة التى وضعت القيمة التقديرية أو الثمن الأساسى فى أى من اللجان الأخرى المنصوص عليها فى هذا القانون للعملية ذاتها .$m248$,'9b362fa18566453598d8a937af7d1a2c',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(16,0,1,$m248$تحدد السلطة المختصة مبلغ التأمين المؤقت ضمن شروط الطرح ، ويجب تقديره دون مبالغة وبما لا يجاوز النسبة المنصوص عليها قرين العمليات الآتية :
1 - فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية : نسبة (1.5%) من القيمة التقديرية وبما يتماشى مع طبيعة العملية وحجمها ، وفى حالة الطرح فى مجموعات متجانسة يحسب التأمين المؤقت لكل مجموعة بذات النسبة .
2 - فى عمليات شراء أو استئجار العقارات : نسبة (0.5%) من القيمة التقديرية للعملية المطروحة .
3 - فى عمليات بيع وتأجير المنقولات والعقارات والمشروعات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات : يتم تحديد مبلغ التأمين المؤقت حسب طبيعة وأهمية المزايدة .
وفى جميع الأحوال ، يجب أن يكون التأمين المؤقت ساريا لمدة ثلاثين يوما بعد تاريخ انتهاء مدة صلاحية سريان العطاء أو تاريخ انتهاء مدة مد صلاحيته .$m248$,'bc496c210113d9264fff9638f0e11573',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(17,0,1,$m248$على إدارة التعاقدات أن تعد مذكرة أو أكثر للعرض على السلطة المختصة للموافقة على البدء فى اتخاذ إجراءات الطرح والتعاقد وغيرها من الإجراءات ، ويجب أن تتضمن هذه المذكرة على وجه الخصوص بيان محل الطرح وطريقة التعاقد ومدة سريان العطاءات ، وغير ذلك من البيانات التى تحددها اللائحة التنفيذية لهذا القانون .$m248$,'cb24c052e50ac624264b2ecb0c571d16',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(18,0,1,$m248$تحدد اللائحة التنفيذية لهذا القانون الصور والشروط والأوضاع الخاصة بالتأمين المؤقت ، وكيفية أدائه ورده واستبداله ، والإجراءات الواجب اتباعها فى شأنه .$m248$,'86368e2cd28a72ee2136c135ab6e5aa0',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(19,0,1,$m248$على الجهة الإدارية قبل الإعلان أو الدعوة للاشتراك فى جميع طرق التعاقد الواردة بهذا القانون والتعاقد بطريق الاتفاق المباشر إذا تطلبت طبيعة العملية ذلك ، أن تعد كراسة للشروط والمواصفات تتضمن الإحالة لجميع القواعد والأحكام والإجراءات والشروط المنصوص عليها فى هذا القانون ولائحته التنفيذية ، ويجب أن تتضمن كراسة الشروط على وجه الخصوص طريقة التعاقد ، والمواصفات والأطر الفنية لموضوع التعاقد ومكان التنفيذ ، والبرنامج الزمنى المتوقع للإجراءات ومواعيد ومكان انعقاد الجلسات ، وشروط الطرح العامة والخاصة ، والتأمينات ، وطريقة السداد ، وتوقيتات تقديم الشكاوى ، وأسلوب التقييم ، وشروط فسخ العقد ، والجزاءات والغرامات ، ونسخة من مشروع العقد المزمع إبرامه متضمنا حقوق والتزامات طرفى التعاقد ، وأى بيانات أخرى بحسب طبيعة العملية .
ويجوز للجهة الإدارية إدخال تعديلات على كراسة الشروط والمواصفات إذا اقتضت المصلحة العامة ذلك أو بناء على جلسة الاستفسارات ، على أن يتم اعتماد تلك التعديلات من السلطة المختصة ، وإخطار من قاموا بشراء كراسة الشروط بها ، وذلك خلال ثلاثة أيام على الأكثر من تاريخ إجراء التعديلات أو جلسة الاستفسارات ، وفى جميع الأحوال ، لا يجوز أن تقل المدة بين الإخطار بهذه التعديلات والموعد المحدد لفتح المظاريف الفنية عن سبعة أيام ، ويتعين الرد كتابة على مقدمى الاستفسارات ومن قاموا بشراء كراسة الشروط بكتاب يرسل بالبريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ، بالإضافة إلى نشرها على بوابة التعاقدات العامة ، ولا يجوز التعديل فى كراسة الشروط والمواصفات بعد الموعد المحدد لفتح المظاريف الفنية .
ويتعين على الجهة الإدارية :
1 - الالتزام بنماذج كراسات الشروط والمواصفات ، وأنماط العقود النموذجية والأدلة الإرشادية ، وغيرها الصادرة عن الهيئة العامة للخدمات الحكومية والتى تعدها الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها ، على أن تتخذ الجهة الإدارية ما يلزم بشأن تضمين كراسة الشروط النموذجية المواصفات الفنية والتوصيف الفنى الكافى لموضوع التعاقد وأى اشتراطات إضافية ترى تضمينها بها ، وكذا نموذج العقد وبما يتناسب مع طبيعة العملية محل الطرح .
2 - تحديد ثمن شراء كراسة الشروط والمواصفات وفقا للشرائح التى تحددها اللائحة التنفيذية لهذا القانون ، وترجم كراسة الشروط والقوائم والمواصفات والتوصيف الفنى بحسب الأحوال فى حال الطرح فى الخارج ، مع ذكر أن النص العربى هو النص المعول عليه فى حالة الخلاف أو الالتباس فى مضمونها .
3 - نشر صورة كاملة ومطابقة من كراسات الشروط والمواصفات على بوابة التعاقدات العامة ، عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة .
وتلتزم الجهات المخاطبة بأحكام هذا القانون بإخطار لجنة تفضيل المنتج الصناعى المصرى بنسخة من شروط ومواصفات الطرح أو العقود التى تزيد قيمتها التقديرية على مليون جنيه ولا تجاوز عشرة ملايين جنيه ، وذلك قبل اتخاذ إجراءات الإعلان عنها أو الدعوة إليها بمدة لا تقل عن خمسة أيام ، كما تلتزم بموافاتها بنسخة من هذه الشروط والمواصفات متى كانت قيمتها التقديرية تزيد على عشرة ملايين جنيه ، وذلك قبل اتخاذ إجراءات الإعلان عنها أو الدعوة إليها أو إسنادها بطريق الاتفاق المباشر ، وذلك بمدة لا تقل عن خمسة عشر يوما ، وعلى اللجنة أن توافى تلك الجهات بملاحظاتها إن وجدت خلال خمسة عشر يوما من تاريخ تسلمها شروط ومواصفات الطرح ، ولا يجوز لتلك الجهات التعاقد خلال هذه المدة .$m248$,'941fa4d9baf84ec3be7335a7c98b532a',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(20,0,1,$m248$يجب النشر عن العمليات التى يتم طرحها بجميع طرق التعاقد المنصوص عليها بالمادة (7) من هذا القانون على بوابة التعاقدات العامة ، عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة ، على أن يتضمن النشر طريق التعاقد وشروطه والأسباب المبررة لاتباع هذا الطريق ، وأسلوب التقييم الفنى والمالى ، وغيرهامن البيانات التى تحددها اللائحة التنفيذية لهذا القانون .
وفى حالة التعاقد عن طريق المناقصة العامة أو الممارسة العامة الداخلية أو المزايدة العلنية العامة أو المزايدة بالمظاريف المغلقة ، فيجب الإعلان مرة واحدة بإحدى الصحف اليومية واسعة الانتشار ، ويكون الإعلان عن المناقصة العامة والممارسة العامة الخارجية مرة واحدة بإحدى الصحف اليومية واسعة الانتشار ، وبإحدى الصحف الدولية وبالإعلام عنها من خلال السفارات والقنصليات .
وفى حالة التعاقد عن طريق المناقصة المحدودة أو المناقصة المحلية أو الممارسة المحدودة أو المزايدة المحدودة أو المزايدة المحلية ، فيجب توجيه الدعوة لأكبر عدد ممكن من المسجلين المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع الطرح .
وفى حالة إذا ما قررت الجهة الإدارية تأجيل موعد فتح المظاريف أو المزايدة ، فيجب أن يتم الإعلان عن الموعد الجديد بالطريقة ذاتها .
وفى جميع حالات الإعلان أو الدعوة للتعاقد المنصوص عليها فى هذا القانون يتعين الحصول على موافقة السلطة المختصة ، ويجوز بموافقتها الإعلان فى أكثر من صحيفة مصرية أو دولية وفقا لأهمية وطبيعة التعاقد فى الحالات التى تقتضى ذلك .$m248$,'f33bd0103f36a64bb9c929efb1463912',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(21,0,1,$m248$يجوز للجهة الإدارية إصدار طلب للتأهيل المسبق للتحقق من توافر القدرات الفنية والإمكانيات المالية والإدارية والبشرية وغيرها فى طالبى التأهل لتنفيذ أحد العقود بالكفاءة المطلوبة قبل دعوتهم لتقديم عطاءات حال الطرح ، وذلك وفقا لمتطلبات ومعايير التقييم المحددة بمستندات طلب التأهيل المسبق ، ويتم الإعلان عن التأهيل المسبق بإحدى الصحف اليومية واسعة الانتشار بالإضافة للنشر عنه على بوابة التعاقدات العامة .$m248$,'15f949c7f05570c06f34a49e273c2f09',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(22,0,1,$m248$فى غير حالات التعاقد بالاتفاق المباشر المطلوب فيها سداد تأمين مؤقت ، يجب أن يؤدى مع كل عطاء تأمين مؤقت لضمان جديته ، ويستبعد كل مقدم عطاء أو متزايد لم يسدد مبلغ التأمين المحدد .
وإذا انسحب مقدم العطاء من العملية قبل الميعاد المحدد لجلسة فتح المظاريف الفنية يصبح التأمين المؤقت المؤدى حقا للجهة الإدارية دون حاجة إلى إنذار أو الالتجاء إلى القضاء أو اتخاذ أى إجراءات أو إقامة الدليل على حصول ضرر ، أو استئدائه من أى مبالغ مستحقة أو تستحق لديها أو لدى أى جهة إدارية أخرى لصاحب العطاء المذكور .
ويجب رد التأمين المؤقت إلى أصحاب العطاءات غير المقبولة فنيا دون توقف على طلب منهم ، وذلك فور انتهاء جميع إجراءات مرحلة البت الفنى ، ويجب رد التأمين المؤقت إلى المتزايدين الذين لم ترس عليهم المزايدة فورا دون توقف على طلب منهم .
وفى جميع حالات التأخير فى رد التأمين المؤقت من الجهة الإدارية ، تلتزم الجهة الإدارية بأن تؤدى لمقدمه قيمة المظاريف البنكية لتجديد خطاب الضمان ، وتكلفة التمويل أو الفائدة المستحقة عن فترة التأخير فى الرد وفقا لسعر الائتمان والخصم المعلن من البنك المركزى ، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك .$m248$,'c649c226d885cccc6c86dd8fe156557a',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(23,0,1,$m248$تقدم العطاءات فى مظروفين مغلقين ، أحدهما للعرض الفنى والآخر للعرض المالى ، وتلتزم الجهة الإدارية بالحصول على إقرار من مقدم العطاء يضمنه بمظروفه الفنى يفيد التزامه بالتأمين على العمالة وفقا لقوانين التأمينات السائدة إذا تطلبت طبيعة العملية ذلك .
ويكون فتح مظاريف العطاءات فى الوقت والمكان المحددين بكراسة الشروط والمواصفات فى جلسة علنية عامة بحضور من يرغب من مقدمى العطاءات ، ويجوز لمقدمى العطاءات تفويض من يرونه لحضور جلسة فتح المظاريف شريطة تقديم التفويض الدال على ذلك .
ويقتصر فتح مظاريف العروض المالية على العروض المقبولة فنيا .$m248$,'69190cc8e4d4cbfcd62afb42dcb017e1',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(24,0,1,$m248$فى حالة وفاة مقدم العطاء إذا كان شخصا طبيعيا ، أو مالك شركة الشخص الواحد ، أو الشريك مع الغير بحصة حاكمة تسمح له بالتأثير فى اتخاذ قرار ذى صلة بالعطاء قبل البت ، جاز للجهة الإدارية استبعاد العطاء المقدم منه ورد التأمين المؤقت ، أو السماح للورثة بالاستمرار فى الإجراءات بشرط أن يعينوا عنهم وكيلا بتوكيل مصدق على التوقيعات فيه ، وتوافق عليه السلطة المختصة .$m248$,'7799d2de1c8a6584ec9171424964fe0e',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(25,0,1,$m248$يجوز لمقدم العطاء أن يعهد ببعض بنود العملية محل التعاقد إلى غيره من الباطن على أن يتضمن عطاؤه بياناتهم وخبراتهم ، وما سيتم إسناده إليهم من بنود وذلك وفقا للمحددات وأى اشتراطات أخرى تضمنها الجهة الإدارية بكراسة الشروط والمواصفات .
ولا يجوز للمتعاقد تغيير أى منهم دون موافقة الجهة الإدارية المتعاقدة . وفى جميع الأحوال ، يظل المتعاقد دون غيره مسئولا أمام الجهة الإدارية المتعاقدة عن تنفيذ العقد .$m248$,'1d559270cc7f4ca286f208246234ac8e',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(26,0,1,$m248$مع عدم الإخلال بأحكام القانون رقم 106 لسنة 2013 فى شأن حظر تعارض مصالح المسئولين فى الدولة ، وكذا القواعد الحاكمة للسلوك الوظيفى والمهنى ، يحظر على الموظفين والعاملين بالجهات الخاضعة لأحكام هذا القانون التقدم بالذات أو بالواسطة بعطاءات أو عروض لتلك الجهات ، ولا يجوز شراء أصناف منهم أو تكليفهم بأعمال .
ولا يسرى ذلك على شراء كتب من تأليفهم أو تكليفهم بأعمال فنية أو شرائها منهم إذا كانت ذات صلة بالأعمال المصلحية ، وبشرط ألا يشاركوا بأى صورة من الصور فى إجراءات قرار الشراء أو التكليف ، وأن يتم كل منهما فى الحدود ووفقا للقواعد والإجراءات التى تبينها اللائحة التنفيذية لهذا القانون .
كما يحظر على الموظفين والعاملين بالجهات المشار إليها فى الفقرة الأولى من هذه المادة ، الدخول بالذات أو بالواسطة فى المزايدات بأنواعها إلا إذا كانت الأصناف المشتراة لاستعمالهم الخاص ، وكانت مطروحة للبيع عن طريق جهات إدارية أخرى غير جهة عملهم ولا تخضع لإشراف هذه الجهة .$m248$,'5b8b7ce294725879f7c63f45b7593ac7',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(27,0,1,$m248$يجب أن تتضمن مذكرة الطرح مدة سريان العطاءات ، بشرط ألا تقل هذه المدة عن خمسة وأربعين يوما وألا تجاوز تسعين يوما وفقا لطبيعة العملية . ويجوز استثناء تجاوز الحد الأقصى فى الحالات التى تتطلب طبيعتها ذلك ، ويتعين فى كل الحالات تضمين كراسة الشروط مدة سريان العطاءات المعتمدة من السلطة المختصة ، وتحسب مدة سريان العطاءات اعتبارا من التاريخ المحدد لفتح المظاريف الفنية .
وفى جميع الأحوال ، يجب أن يتم البت والإخطار بالترسية قبل انتهاء مدة سريان هذه العطاءات . فإذا تعذر ذلك ، تعين على إدارة التعاقدات العرض على السلطة المختصة بالأسباب التى أدت إلى التأخير ، واقتراح المدة المطلوب مدها للانتهاء من إجراءات الترسية ، ويجب حال موافقة السلطة المختصة على هذه المدة إخطار مقدمى العطاءات كتابة لمد مدة سريان عطاءاتهم لهذه المدة ، ومد مدة صلاحية التأمين المؤقت على أن يتم ذلك كله قبل تاريخ انتهاء مدة سريان العطاءات بخمسة عشر يوما ، ويستبعد كل عطاء لم يقبل صاحبه مد مدة سريان عطائه كتابة ، ويرد إليه تأمينه فور انتهاء مدة سريان العطاء .$m248$,'313b4262193dfec6c2f19abbd5d6da75',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(28,0,1,$m248$تتولى إجراءات جميع طرق التعاقد المنصوص عليها بالمادة (7) من هذا القانون لجان تشكل بقرار من السلطة المختصة ، تضم عناصر فنية ومالية وقانونية وفقا لأهمية وطبيعة التعاقد ، على أن يتضمن قرار تشكيلها موعد انتهائها من أعمالها .
وتباشر هذه اللجان عملها على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .
ويكون البت فى المناقصات بأنواعها عن طريق لجنتين ، تتولى إحداهما فتح المظاريف وتتولى الأخرى البت فى المناقصة ، على أنه بالنسبة للمناقصة التى لا تجاوز قيمتها ثلاثمائة ألف جنيه ، يكون فتح المظاريف والبت فيها عن طريق لجنة واحدة .
ولا يجوز الجمع بين رئاسة اللجان المنصوص عليها بهذا القانون واعتماد أعمالها .$m248$,'8263710077f465425111a2e0aba1f00d',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(29,0,1,$m248$يجب أن يشترك فى عضوية لجان فتح المظاريف ولجان البت فى المناقصات ولجنة الممارسة ممثل لوزارة المالية إذا تجاوزت القيمة التقديرية مليون جنيه ، وعضو من إدارة الفتوى المختصة بمجلس الدولة إذا تجاوزت القيمة التقديرية مليونى جنيه .
ويشترك فى عضوية لجنة البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال ممثل لوزارة المالية متى بلغ الثمن الأساسى مليون جنيه ، وعضو من إدارة الفتوى المختصة بمجلس الدولة متى بلغ الثمن الأساسى مليونى جنيه .
أما فى حالة شراء أو استئجار أو بيع أو تأجير العقارات التى تتم فى الخارج ، فيشترك فى العضوية ممثل لوزارة المالية وعضو من إدارة الفتوى المختصة بمجلس الدولة إذا تجاوزت القيمة التقديرية أو بلغ الثمن الأساسى ثمانية ملايين جنيه .
ويجب اشتراك ممثل لوزارة الإسكان فى عضوية اللجان المشار إليها فى حالات شراء أو استئجار العقارات .
وفى جميع الأحوال ، لا يكون انعقاد اللجنة صحيحا إلا بحضور ممثل وزارة المالية وعضو إدارة الفتوى المختصة بمجلس الدولة بحسب الأحوال ، وممثل لوزارة الإسكان فى الحالات التى تتطلب ذلك .$m248$,'4d073d0b4fb3b835d581cc8fc5cc3db8',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(30,0,1,$m248$فى حالة التعاقد بالاتفاق المباشر على شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ، تتولى الإجراءات لجنة تشكل بقرار من السلطة المختصة من أهل الخبرة من بينهم عناصر فنية ومالية وقانونية وفقا لأهمية التعاقد وطبيعته ، ويقع على عاتقهم مسئولية التحقق من مطابقة محل التعاقد من النواحى الفنية المطلوبة ومناسبة الأسعار مقارنة بأسعار السوق السائدة وقت التعاقد أو لتحديد أقل العروض سعرا ، والذى يلبى جميع الشروط والمتطلبات التى حددتها الجهة الإدارية فى طلبها وذلك من واقع ما يتم الحصول عليه من عروض أسعار ، وكذا أسس اختيار المتعاقد معه ، ويكون اعتماد نتيجة عمل اللجنة من السلطة المختصة .$m248$,'6cd5b3291dfe293c318061b2779567d1',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(31,0,1,$m248$مع مراعاة تشكيل اللجان المنصوص عليها فى هذا القانون ، تشكل بقرار من السلطة المختصة لجان متخصصة وفقا لطبيعة العملية تكون مهمتها مباشرة الإجراءات الواردة بأحكام هذا القانون ولائحته التنفيذية .$m248$,'2f31fbc809a21a358fc1fe96cad72251',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(32,0,1,$m248$يتعين على الجهة الإدارية التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة فيمن يتم التعامل معهم وغيرها من المعايير الموضوعية التى تحددها الجهة الإدارية ضمن شروط الطرح ، وبما يتفق مع الأحكام المنصوص عليها فى هذا القانون ولائحته التنفيذية .$m248$,'c4dad3ae980803b8cf99353212c4f8d6',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(33,0,1,$m248$يحظر على مقدمى العطاءات التقدم بالذات أو بالشراكة مع الغير بأكثر من عطاء لعملية واحدة ، ما لم يكن المتقدم شريكا مع الغير بحصة لا تسمح له بالتأثير فى اتخاذ قرار ذى صلة بالعطاء .
ويجب على الجهة الإدارية حال مخالفة الحظر المنصوص عليه فى الفقرة الأولى من هذه المادة استبعاد العطاءات المخالفة ، وأيلولة التأمين المؤقت إلى الجهة الإدارية ، أو فسخ العقد أو التنفيذ على الحساب ، وأيلولة التأمين النهائى ، وتحميل المتعاقد بأى خسارة تلحق بها إذا تبين لها مخالفة الحظر بعد التعاقد .
كما يجب على الجهات الإدارية إخطار جهاز حماية المنافسة ومنع الممارسات الاحتكارية بأى مخالفة لأحكام هذا القانون وتكون ذات صلة بأحكام قانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005$m248$,'3a91bbfb87023e302c341fb24a582723',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(34,0,1,$m248$تتولى لجنة البت دراسة العطاءات المقدمة وفق أحكام هذا القانون ولائحته التنفيذية الشروط والمواصفات المعلن عنها ، ويجوز للجنة البت أن تعهد إلى لجان فرعية تشكلها من بين أعضائها بدراسة النواحى الفنية والمالية فى العطاءات المقدمة ومدى مطابقتها للشروط ، وعلى اللجنة التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة فى مقدمى العطاءات ، وذلك كله وفقا للشروط والمواصفات الواردة بكراسة الشروط ، وللجنة البت أن تضم لعضوية اللجان الفرعية التى تشكلها من ترى الاستعانة برأيهم من أهل الخبرة .
وتقدم اللجان الفرعية تقارير بنتائج أعمالهم وتوصياتها إلى لجنة البت .$m248$,'beab0dda119032c9b6e2bf7657a81963',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(35,0,1,$m248$يجب استبعاد العطاءات غير المطابقة للشروط والمواصفات طبقا لأحكام هذا القانون ولائحته التنفيذية ، والشروط والمواصفات والمتطلبات المحددة بكراسة الشروط والمواصفات .
وتتم ترسية المناقصة أو الممارسة على صاحب العطاء الأفضل شروطا والأقل سعرا أو الذى يتم ترجيحه وفقا لنظام النقاط المحددة عناصره وأسسه بشروط الطرح ، وذلك بعد توحيد أسس المقارنة بين العطاءات من جميع النواحى الفنية والمالية ، مع الأخذ فى الاعتبار العناصر التى تؤثر فى تحديد القيمة المقارنة للعطاءات بحسب ظروف موضوع التعاقد وطبيعته .
ولا يجوز التعديل فى هذه الشروط بعد الموعد المحدد لفتح المظاريف الفنية .
وإذا تبين للجنة البت أن العطاء الأقل سعرا منخفض انخفاضا غير عادى مقارنة بالعطاءات الأخرى والقيمة التقديرية ، وجب عليها طلب تفاصيل العطاء المقدم كتابة ، فإذا تبين لها من دراسة ما قدمه من تفاصيل ومعلومات أن العرض المقدم منه ما يزال يثير الريبة ويتعذر التنفيذ به توصى اللجنة باستبعاده ، ويتعين أن توثق اللجنة كل ما يتخذ من إجراءات أدت إلى ذلك ، ووفقا لما تنظمه اللائحه التنفيذية لهذا القانون .
وترفع اللجنة محضرها متضمنا قراراتها وتوصياتها للسلطة المختصة للاعتماد أو لتقرير ما تراه .
ويجب أن يشتمل قرار الاستبعاد أو الترسية على الأسباب التى بنى عليها .
ومع مراعاة حكم المادة (4) من القانون رقم 5 لسنة 2015 فى شأن تفضيل المنتجات المصرية فى العقود الحكومية ، يعد المنتج المقدم عن توريدات مستوفية لنسبة المكون الصناعى المصرى أقل سعرا إذا لم تتجاوز نسبة الزيادة فيه (15%) من قيمة أقل عطاء غير مستوف .
ويعد العطاء المقدم عن الخدمات أو الأعمال الفنية التى تقوم بها جهات مصرية أقل سعرا إذا لم تتجاوز نسبة الزيادة فيه (15%) من قيمة أقل عطاء أجنبى ، ويستثنى من ذلك العطاءات المقدمة فى عقود المشروعات المنصوص عليها فى المادة (3) من القانون رقم 5 لسنة 2015 المشار إليه وما تشمله هذه المشروعات أو يكون لازما لها من خدمات أو أعمال فنية .
وفى جميع الأحوال ، يخطر صاحب العطاء الفائز بقبول عطائه بموجب خطاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ، كما يخطر باقى مقدمى العطاءات كتابة بما انتهت إليه الجهة الإدارية من قرارات مع وجوب إتاحة الفرصة لإيضاح أسباب عدم قبول العطاء لمن يطلب من مقدمى العطاءات .$m248$,'13be5676e3d45b9459ef30f667a30830',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(36,0,1,$m248$تتم ترسية المزايدة على مقدم أعلى سعر مستوف للشروط بشرط ألا يقل السعر المقدم عن الثمن أو القيمة الأساسية ، وترفع اللجنة محضرها متضمنا توصياتها للسلطة المختصة للاعتماد أو تقرير ما تراه ، ويجب أن يشتمل قرار الترسية على الأسباب التى بنى عليها .$m248$,'91ac536c6ef31c261ad9dac13e846625',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(37,0,1,$m248$تلغى المناقصة أو الممارسة بجميع أنواعها قبل البت فيها بقرار مسبب من السلطة المختصة إذا استغنى عنها نهائيا ، أو اقتضت المصلحة العامة ذلك ، أو فى حالة المنصوص عليها فى الفقرة الأولى من المادة (12) من القانون رقم 5 لسنة 2015 المشار إليه .
ويكون الإلغاء بقرار مسبب من السلطة المختصة سواء من تلقاء ذاتها أو بناء على توصية لجنة البت أو الممارسة إذا تبين وجود تواطؤ بين مقدمى العطاءات أو ممارسات احتيال أو فساد أو احتكار ، أو إذا تبين وجود نقص أو خطأ فى كراسة الشروط والمواصفات .
ويجوز الإلغاء فى أى من الحالات الآتية :
1 - إذا لم يقدم سوى عطاء وحيد ، أو لم يبق بعد العطاءات المستبعدة إلا عطاء واحد ما لم تكن حاجة العمل لاتسمح بإعادة الطرح ، ولا توجد فائدة ترجى من إعادة الطرح وبشرط أن يكون العطاء مطابقا للشروط ومناسبا للقيمة التقديرية .
2 - إذا اقترنت العطاءات كلها أو أغلبها بتحفظات .
3 - إذا كانت قيمة العطاء الأقل تجاوز القيمة التقديرية ، ما لم تبين دراسة لجنة البت أو لجنة الممارسة عدم جدوى إعادة الطرح والآثار المترتبة عليه .
ويكون الإلغاء فى الحالات المنصوص عليها فى الفقرة الثالثة من هذه المادة بقرار من السلطة المختصة بناء على توصية لجنة البت أو لجنة الممارسة ، ويجب أن يشتمل القرار على الأسباب التى بنى عليها ، ويخطر مقدمو العطاءات بذلك بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس ، بحسب الأحوال .
وفى جميع حالات الإلغاء ، يجب رد ثمن كراسة الشروط والمواصفات والتأمين المؤقت إلى أصحاب العطاءات عدا مقدمى العطاءات الذين تبين وجود تواطؤ بينهم أو ممارسات احتيال أو فساد أو احتكار .$m248$,'479d9bf8bcd9f66e73410333c2c57268',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(38,0,1,$m248$تلغى المزايدة قبل البت فيها إذا استغنى عنها نهائيا ، أو إذا اقتضت المصلحة العامة ذلك ، أو لم تصل نتيجتها إلى الثمن أو القيمة الأساسية ، أو إذا تبين للجهة الإدارية وجود تواطؤ بين المتزايدين أو ممارسات احتيال أو فساد أو احتكار ، ويجوز إلغاؤها إذا لم يقدم سوى عرض وحيد مستوف للشروط .
وترفع لجنة المزايدة محضرا متضمنا قراراتها وتوصياتها للسلطة المختصة للاعتماد أو تقرير ما تراه ، ويجب أن يشتمل قرار إلغاء المزايدة على الأسباب التى بنى عليها .$m248$,'369455e528239622412e297fb9e5cc4f',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(39,0,1,$m248$على إدارة التعاقدات إخطار مقدمى العطاءات بنتائج قرارات اللجان بالقبول أو الاستبعاد أو الإلغاء فور اعتماد السلطة المختصة لها بخطابات ترسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس ، بحسب الأحوال ، وفقا لعناوينهم وبياناتهم الواردة بالعطاء ، ويكون لهم حق التقدم بشكواهم كتابة خلال سبعة أيام تبدأ من اليوم التالى لإخطارهم بالقرار .
ويخطر صاحب العطاء الفائز بقبول عطائه خلال مدة لا تجاوز يومين بعد انقضاء السبعة الأيام المنصوص عليها فى الفقرة الأولى كما يخطر باقى مقدمى العطاءات بذلك .
وفور إرسال خطابات الإخطار ينشر عن نتائج قرارات اللجان ، وكذا عن نتيجة الترسية فى لوحة الإعلانات المخصصة لهذا الغرض والمحدد لها مكان ظاهر للكافة ، كما يتم النشر على بوابة التعاقدات العامة على أن يتضمن النشر الآتى :
1 - نتائج القرارات ، وأسبابها بالقبول أو الاستبعاد أو الإلغاء أو الترسية للعطاءات أو استبعاد المنتج الصناعى المصرى إن وجدت .
2 - القيمة النهائية للمشروع ، وقيمة المكون الصناعى المصرى الذى تم التعاقد عليه إن وجد .
3 - منشأ الصنع وبلده للمنتجات التى تضمنتها العقود التى أبرمت لشراء منتجات صناعية .$m248$,'33ad02bfe193c4dc7cef795684dce977',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(40,0,1,$m248$على صاحب العطاء الفائز أن يؤدى التأمين النهائى بالنسب وخلال المدد بالأحكام المبينة قرين الحالات الآتية :
1 - عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية ، خلال عشرة أيام عمل بنسبة (5%) من قيمة العقد تبدأ من اليوم التالى لإخطاره بقبول عطائه ، وبالنسبة للعقود التى تبرم مع متعاقد فى الخارج يكون الأداء خلال عشرين يوم عمل ، ويتم الإخطار بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، معه تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ، ويجوز بموافقة السلطة المختصة منح مهلة إضافية للأداء بما لا يجاوز عشرة أيام عمل .
وفى حالات التعاقد بالاتفاق المباشر والتى تتطلب بحسب طبيعتها ضمان المتعاقد لسلامة محل التعاقد ، فيحجز ما يعادل نسبة (5%) من مستحقاته .
ولا يحصل من صاحب العطاء الفائز التأمين النهائى إذا ورد جميع الأصناف التى رسا عليه توريدها وقبلتها الجهة الإدارية بصفة نهائية خلال المهلة المحددة لأداء التأمين النهائى وذلك إذا لم يكن لهذه الأصناف مدة ضمان ، أما فى الحالات التى تتطلب طبيعتها ضمان المتعاقد لسلامة محل العقد فيتم خصم نسبة (5%) من مستحقاته .
2 - عمليات شراء العقارات : تحجز نسبة (3%) من الثمن ، وترد إلى البائع فور التسجيل أو مضى عام من تاريخ تسليم العقار للجهة الإدارية أيهما أبعد لمواجهة إصلاح أى عيوب قد تظهر خلال هذه المدة .
3 - حال بيع المنقولات ، يجب على من يرسو عليه المزايدة أن يسدد نسبة (30%) من قيمة ما تم ترسيته عليه فور الرسو .
4 - عمليات بيع العقارات والمشروعات : يجب على من ترسو عليه المزايدة أن يسدد نسبة (10%) من قيمة ما تم ترسيته عليه فور الرسو .
5 - فى حالة تأجير المنقولات والعقارات والمشروعات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات : يجب على من يرسو عليه المزاد فى العقود التى لا تزيد مدتها على ثلاث سنوات أن يقدم تأمينا نهائيا بما يعادل (10%) من القيمة الكلية الراسى بها المزاد عن مدة العقد بالكامل وذلك فور رسو المزاد ، ويجب أن يظل التأمين ساريا طوال مدة العقد ، فإذا زادت مدة العقد على ثلاث سنوات يحسب التأمين النهائى الواجب تقديمه بواقع (10%) من قيمة العقد عن الثلاث سنوات الأولى ، ويجدد هذا التأمين قبل بداية الثلاث سنوات التالية أو الفترة المتبقية من العقد أيهما أقل ، وذلك بمراعاة الزيادة السنوية فى قيمة التعاقد المنصوص عليها بالعقد .
ويكون التأمين النهائى ضامنا لتنفيذ العقد ، ويجب رده أو ما تبقى منه فور انتهاء مدة الضمان المحددة بالعقد بغير طلب خلال عشرة أيام عمل ما لم تعدل مدة التعاقد ، وإلا التزمت الجهة الإدارية بأن تؤدى للمتعاقد قيمة المصاريف البنكية لتجديد خطاب الضمان وتكلفة التمويل أو الفائدة المستحقة عن فترة التأخير فى الرد وفقا لسعر الائتمان والخصم المعلن من البنك المركزى ، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك .
وإذا تجاوزت قيمة التأمين المؤقت التأمين النهائى وجب رد الزيادة فورا بغير طلب .
وفى جميع حالات عدم السداد يكون التأمين المؤقت من حق الجهة الإدارية .$m248$,'6063f9e951a727af4aeb833662de226e',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(41,0,1,$m248$إذا لم يقم صاحب العطاء الفائز بأداء التأمين النهائى خلال المهلة المحددة ، جاز للجهة الإدارية ، بموجب إخطار بكتاب يرسل له بخدمة البريد السريع ، عن طريق الهيئة القومية للبريد مع تعزيزه فى ذات الوقت بالبريد الإلكترونى أو الفاكس بحسب الأحوال ودون حاجة لاتخاذ أى إجراء آخر ، إلغاء العقد أو تنفيذه بواسطة أحد مقدمى العطاءات التالية لعطائه بحسب ترتيب أولوياتها .
ويصبح التأمين المؤقت فى جميع الحالات من حق الجهة الإدارية ، كما يكون لها أن تخصم قيمة كل خسارة تلحق بها إذا تبين أنه المتسبب فيها من أى مبالغ مستحقة أو تستحق لديها لصاحب هذا العطاء ، وفى حالة عدم كفايتها تلجأ إلى خصمها من مستحقاته لدى أى جهة إدارية أخرى ، أيا كان سبب الاستحقاق ، وذلك كله مع عدم الإخلال بحقها فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى .$m248$,'b22dd909d59268d8bcb6dfb92514546c',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(42,0,1,$m248$تحدد اللائحة التنفيذية لهذا القانون الصور والشروط والأوضاع الخاصة بالتأمين النهائى ، وكيفية أدائه ورده واستبداله ، والإجراءات الواجب اتباعها فى شأنه .$m248$,'7b008ae581dde52cc267caa1384429b1',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(43,0,1,$m248$يكون تنفيذ العقود طبقا لما اشتملت عليه ، وبطريقة تتفق مع ما يوجبه حسن النية ، وفى الحدود ووفقا للشروط والقواعد والإجراءات الواردة بهذا القانون ولائحته التنفيذية .$m248$,'91734ff8ffa570babe3d7420cb910642',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(44,0,1,$m248$يجوز للجهة الإدارية المتعاقدة بموافقة السلطة المختصة صرف دفعة مقدمة من قيمة التعاقد مقابل خطاب ضمان بنكى معتمد دون أى قيد أو شرط بالقيمة والعملة ذاتهما ، بشرط تضمين كراسة الشروط والمواصفات نسبة الدفعة وطلب تحديد أوجه صرفها ، ويتم استنزال قيمة الدفعة المقدمة مما يتم صرفه للمتعاقد مقابل تخفيض قيمة خطاب ضمان الدفعة المقدمة بالنسبة ذاتها .
وتحدد اللائحة التنفيذية لهذا القانون نسب وإجراءات صرف الدفعة المقدمة للمتعاقد ، ويجوز تجاوز تلك النسب بموافقة وزير المالية .$m248$,'d4874f49a05e0eb0746a7316b441c18f',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(45,0,1,$m248$مع مراعاة شروط التعاقد ، يصرف ثمن الأصناف الموردة أو الخدمات المؤداة فى أقرب وقت ممكن وبما لا يجاوز ثلاثين يوما تحسب من تاريخ الفحص والقبول والاعتماد .
وفى مقاولات الأعمال تصرف الجهة الإدارية دفعات تحت الحساب تبعا لتقدم العمل ، وذلك خلال ستين يوما تحسب من تاريخ تقديم المستخلص لها معززا بالمستندات على النحو الوارد بشروط التعاقد وقبول هذه المستندات من الجهة الإدارية ، وتلتزم خلالها بمراجعته والوفاء بقيمة ما يعتمد .
ويجوز للمقاول فى حالة رفض الجهة الإدارية استلام المستخلص المستوفى لشروط التعاقد إرساله مرفقا به كافة المستندات المبينة بشروط التعاقد بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، على أن يكون تاريخ استلام الجهة الإدارية للمستخلص بالبريد هو بداية المدة اللازمة للبدء فى إجراءات الصرف .
وفى جميع الأحوال ، إذا لم يتم الوفاء بالمبالغ المستحقة للمتعاقد فى المواعيد المحددة تلتزم الجهة الإدارية بأن تؤدى للمتعاقد ما يعادل تكلفة التمويل لقيمة المطالبة أو المستخلص المعتمد عن فترة التأخير وفقا لسعر الائتمان والخصم المعلن من البنك المركزى وقت المحاسبة شريطة تقديم مستندات رسمية بالمبلغ المطالب به ، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك .$m248$,'9bd3a4cd710a873fa0ec77c021d5f3f2',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(46,0,1,$m248$إذا طرأ من المستجدات بعد إبرام العقد ما يوجب تعديل حجم التعاقد يكون للجهة الإدارية أن تعدل عقودها بالزيادة أو النقص وبما لا يجاوز (25%) من كمية كل بند لعقود المقاولات ، وبما لا يجاوز (15%) من كمية كل بند لباقى العقود بذات الشروط والمواصفات والأسعار ، على أن تتضمن كراسة الشروط والمواصفات مضمون ذلك .
ويتعين لتعديل العقد الحصول على موافقة السلطة المختصة أو مجلس الوزراء بحسب الأحوال ، ووجود الاعتماد المالى اللازم ، وأن يصدر التعديل خلال فترة سريان العقد ، وألا يؤثر ذلك على أولوية المتعاقد فى ترتيب عطائه ، وأن تعدل مدة العقد الأصلى إذا تطلب الأمر ذلك بالقدر الذى يتناسب وحجم الزيادة أو النقص .$m248$,'355e5212bc763d16123442465eefc8c3',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(47,0,1,$m248$فى عقود مقاولات الأعمال التى تكون مدة تنفيذها ستة أشهر فأكثر ، تلتزم الجهة الإدارية فى نهاية كل ثلاثة أشهر تعاقدية من التاريخ المحدد لفتح المظاريف الفنية أو تاريخ التعاقد المبنى على أمر الإسناد بالاتفاق المباشر بحسب الأحوال ، بتعديل قيمة العقد وفقا للزيادة أو النقص فى تكاليف بنود العقد التى طرأت بعد التاريخ المحدد لفتح المظاريف الفنية أو بعد تاريخ التعاقد المبنى على أمر الإسناد بالاتفاق المباشر وبمراعاة البرنامج الزمنى للتنفيذ من واقع نشرة الأرقام القياسية للمنتجين الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء ، ويكون هذا التعديل ملزما لطرفى التعاقد ، ويتعين تضمين العقد مضمون ذلك .
وعلى الجهة الإدارية تحديد البنود المتغيرة أو مكوناتها بكراسة الشروط والمواصفات وفقا للقائمة التى تصدرها وزارة الإسكان ، على أن يضع المقاول معاملاتها فى المظروف الفنى ، ويقع باطلا كل اتفاق يخالف ذلك .
وتبين اللائحة التنفيذية لهذا القانون الضوابط والإجراءات المتبعة فى هذا الشأن ، ومعادلة تغير الأسعار واشتراطات تطبيقها .$m248$,'e076caf29fb5bf9a4f9d35a8a589290b',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(48,0,1,$m248$إذا تأخر المتعاقد أثناء تنفيذ العقد عن الميعاد المحدد له بالجدول الزمنى أو مدة التنفيذ المحددة بالعقد ، جاز للسلطة المختصة لدواعى المصلحة العامة إعطاؤه مهلة لإتمام التنفيذ دون تحصيل مقابل للتأخير منه إذا كان التأخير راجعا لسبب خارج عن إرادته .
وفى حالة عدم الالتزام بالتنفيذ ، لسبب راجع للمتعاقد ، يحصل مقابل للتأخير يحسب من بداية المهلة دون حاجة إلى تنبيه أو إنذار أو اتخاذ أى إجراء آخر وفقا للآتى :
1 - فى مقاولات الأعمال بما لا يجاوز مجموع مقابل التأخير نسبة (10%) من قيمة العقد إذا لم تتجاوز مدة التأخير نسبة (10%) من المدة الكلية للعملية ، ويزيد مقابل التأخير إلى نسبة (15%) إذا جاوزت مدة التأخير ذلك .
ويحسب مقابل التأخير من قيمة الأعمال المتأخرة فقط إذا رأت الجهة الإدارية أن الجزء المتأخر لا يمنع الانتفاع بما تم تنفيذه بشكل مباشر أو غير مباشر على الوجه الأكمل فى المواعيد المحددة ، أما إذا رأت أن الجزء المتأخر يمنع الانتفاع بما تم تنفيذه فيكون حساب مقابل التأخير من قيمة ختامى العملية .
ويتم تطبيق معادلة تغير الأسعار للكميات التى نفذت خلال المهلة بشرط أن يكون التأخير راجعا لأسباب خارجة عن إرادة المتعاقد ، على أن يعدل الجدول الزمنى بما يتفق عليه الطرفان إذا تطلب الأمر ذلك وبما يتناسب مع مدة التأخير .
2 - فى باقى العقود بما لا يجاوز مجموع مقابل التأخير نسبة (3%) من قيمة العقد إذا لم تتجاوز مدة التأخير نسبة (10%) من المدة الكلية للعقد ، ويزيد مقابل التأخير إلى نسبة (5%) إذا جاوزت مدة التأخير ذلك .
ويحسب مقابل التأخير من قيمة الجزء المتأخر فقط إذا رأت الجهة الإدارية أن الجزء المتأخر لا يمنع الانتفاع بما تم توريده أو تنفيذه بشكل مباشر أو غير مباشر على الوجه الأكمل فى المواعيد المحددة ، أما إذا رأت أن الجزء المتأخر يمنع الانتفاع بما تم توريده أو تنفيذه فيكون حساب مقابل التأخير من القيمة الإجمالية للعقد .
وفى جميع حالات تحصيل مقابل التأخير ، يكون الإعفاء منه بقرار من السلطة المختصة إذا تبين أن التأخير لأسباب خارجة عن إرادة المتعاقد ، وللسلطة المختصة فى غير هذه الحالة إعفاء المتعاقد من مقابل التأخير جزئيا أو كليا إذا لم ينتج عن التأخير ضرر ، ويجوز للسلطة المختصة استطلاع رأى إدارة الفتوى المختصة بمجلس الدولة إذا ارتأت ذلك .
ولا يخل تحصيل مقابل التأخير بحق الجهة الإدارية فى الرجوع على المتعاقد بكامل التعويض المستحق عما أصابها من أضرار بسبب التأخير .$m248$,'1dca0bb046e5eb23c5e7d519834f451c',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(49,0,1,$m248$يجب على الجهة الإدارية استلام محل التعاقد فى المواعيد المحددة بالعقد حال مطابقتها للمواصفات والشروط المتفق عليها بالعقد ، وللمتعاقد حال تقاعس الجهة المتعاقدة عن الاستلام التقدم بطلب للسلطة المختصة لتشكيل لجنة محايدة لدراسة أسباب التقاعس ، وصورة منه لمكتب شكاوى التعاقدات العمومية وذلك للمتابعة .
وتلتزم السلطة المختصة خلال سبعة أيام من تاريخ استلامها للطلب بتشكيل لجنة ثلاثية متخصصة من جهات محايدة وتكون الجهة المتعاقدة طرفا فيها على أن تبدأ أعمالها فور صدور قرار تشكيلها وسداد المتعاقد أتعاب الجهات الخارجية المشاركة فيها ، وتقدم اللجنة تقريرها خلال مدة زمنية أقصاها ثلاثون يوما ما لم تتطلب طبيعة العملية وحجمها مدة تتجاوز ذلك ، ويكون تقريرها ملزما للطرفين ، وحال تبين تقاعس الجهة المتعاقدة عن الاستلام يتم رد أتعاب اللجنة للمتعاقد ، وإحالة المتسبب للتحقيق وتحميله بأتعاب اللجنة .
وتصدر السلطة المختصة قرارا بإنهاء إجراءات الاستلام فى مدة زمنية لا تجاوز مدة الفحص والاستلام المتفق عليها مسبقا بشروط الطرح والتعاقد .$m248$,'c161799b01c87810baf8ac8c649e8947',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(50,0,1,$m248$يجب فسخ العقد فى الحالات الآتية :
1 - إذا تبين أن المتعاقد استعمل بنفسه أو بواسطة غيره الغش أو التلاعب فى تعامله مع الجهة الإدارية المتعاقدة أو فى حصوله على العقد .
2 - إذا تبين وجود تواطؤ أو ممارسات احتيال أو فساد أو احتكار .
3 - إذا أفلس المتعاقد أو أعسر .
ويتم الفسخ فى الأحوال المشار إليها تلقائيا ، ويشطب اسم المتعاقد فى الحالتين المنصوص عليهما فى البندين (1 ، 2) من سجل المتعاملين بعد أخذ رأى إدارة الفتوى المختصة بمجلس الدولة ، وتخطر الهيئة العامة للخدمات الحكومية بذلك لنشر قرار الشطب بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة .
ويعاد قيد المتعاقد الذى شطب اسمه فى سجل المتعاملين بناء على طلبه إذا انتفى سبب الشطب بصدور قرار من النيابة العامة بألا وجه لإقامة الدعوى الجنائية ضده أو بحفظها إداريا أو بصدور حكم نهائى ببراءته مما نسب إليه ، على أن تخطر الهيئة العامة للخدمات الحكومية بقرار إعادة القيد لنشره بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة .$m248$,'211e96eaac2efef5956df8b66cf04a87',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(51,0,1,$m248$يجوز للجهة الإدارية فسخ العقد أو تنفيذه على حساب المتعاقد ، إذا أخل بأى شرط جوهرى من شروطه .
ويكون الفسخ أو التنفيذ على حساب المتعاقد بقرار مسبب من السلطة المختصة ، يخطر به المتعاقد بكتاب يرسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد ، مع تعزيزه فى الوقت ذاته بالبريد الإلكترونى أو الفاكس بحسب الأحوال على عنوانه المبين فى العقد .
ولا يجوز للجهة الإدارية الجمع بين كل من الإجراءين المنصوص عليهما فى الفقرة السابقة لأى سبب .
وفى جميع حالات الفسخ أو التنفيذ على حساب المتعاقد يكون التأمين النهائى من حق الجهة الإدارية ، كما يكون لها أن تخصم ما تستحقه من مقابل التأخير وقيمة كل خسارة تلحق بها من أى مبالغ مستحقة أو تستحق للمتعاقد لديها ، وفى حالة عدم كفايتها تلجأ إلى خصمها من مستحقاته لدى أى جهة إدارية أخرى أيا كان سبب الاستحقاق ، دون حاجة إلى اتخاذ أى إجراءات قضائية ، وذلك كله مع عدم الإخلال بحقها فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى .$m248$,'01e72628deebc17fdc53db6111aedfe5',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(52,0,1,$m248$فى حالة وفاة المتعاقد أثناء التنفيذ ، يحق للجهة الإدارية إنهاء العقد ورد التأمين النهائى للورثة ما لم يكن لها مطالبات قبل المتعاقد أو السماح لهم بالاستمرار فى تنفيذ العقد ، وإذا كان العقد مبرما مع أكثر من متعاقد وتوفى أحدهم ، جاز للجهة الإدارية إنهاء العقد مع رد التأمين النهائى ما لم يكن لها مطالبات أو السماح لباقى المتعاقدين بالاستمرار فى تنفيذه .$m248$,'c6648470eb12df5695b7a93085c92b9f',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(53,0,1,$m248$تسرى أحكام هذا الباب على عمليات شراء أو استئجار المنقولات والعقارات ، والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية .$m248$,'5a1676412e490898165de7025da30126',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(54,0,1,$m248$يكون التعاقد بطريق الممارسة العامة فى الحالات التى تتوافر فيها الشروط الآتية :
1 - أن يكون متاحا للجهة الإدارية وضع توصيف محدد ودقيق لموضوع التعاقد .
2 - أن يكون لموضوع التعاقد معايير قابلة للقياس الكمى والتى على أساسها يتم تحديد مدى استجابة العروض فنيا .
3 - أن يكون معلوما للجهة الإدارية وجود عدد كاف من الموردين أو المقاولين أو مقدمى الخدمات للمشاركة فى العملية لضمان تحقيق المنافسة الفعالة .$m248$,'f78238d348ac289a3204ae0ddb7ef841',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(55,0,1,$m248$مع مراعاة حكمى البندين (1، 2) من المادة (54) من هذا القانون ، يقتصر التعاقد بطريق الممارسة المحدودة فى أى من الحالات الآتية :
1 - الأصناف التى يتم تصنيعها أو استيرادها أو تقديمها من قبل أشخاص أو كيانات بذاتها ، أو الأصناف التى تقتضى طبيعتها أو الغرض من الحصول عليها أن يكون اختيارها أو شراؤها من أماكن إنتاجها .
2 - التعاقدات المرتبطة باعتبارات الأمن القومى .
3 - الأصناف أو الأعمال أو الخدمات التى تتطلب أن تكون متوافقة مع ما هو موجود حاليا بسبب عدم وجود بدائل لها وتكون متوافرة لدى أكثر من مصدر .$m248$,'51e6f1e3cc89111287e8de7fa443417f',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(56,0,1,$m248$تتم الممارسة بنوعيها بقيام مقدمى العطاءات المقبولة عروضهم فنيا دون غيرهم بالتمارس فى الجلسة المحددة لذلك من خلال جولة أو عدة جولات وصولا لاختيار العطاء الأفضل شروطا تعاقدية والأقل سعرا ، ما لم يكن التقييم فيها بنظام النقاط .
وتستخدم المنظومة الإلكترونية المخصصة لذلك فور اكتمالها وانتظامها وذلك فيما يتم ميكنته وإتاحته من إجراءات .$m248$,'5fa573b00aa703f6f778813ea326d30f',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(57,0,1,$m248$يكون التعاقد بطريق المناقصة المحدودة فى أى من الحالات الآتية :
1 - العمليات التى تتطلب طبيعتها قصر الاشتراك فيها على موردين أو مقاولين أو فنيين أو استشاريين أو خبراء بذاتهم ، سواء فى مصر أو فى الخارج .
2 - العمليات التى أتخذت الجهة الإدارية إجراءات تأهيل مسبق فى شأنها ، وبحيث يتم دعوة من تم تأهيلهم للاشتراك فيها .
3 - التعاقدات المرتبطة باعتبارات الأمن القومى .
4 - توفير المستحضرات والأجهزة الطبية والأدوية ، وغيرها من المستلزمات المرتبطة بالمحافظة على الحياة والصحة .
5 - إذا كان الوقت أو التكلفة اللازمان للطرح بطريقة المناقصة العامة لا يتناسبان مع قيمة التعاقد .
6 - عزوف مقدمى العطاءات عن المشاركة فى المناقصات العامة التى تم طرحها مرة أو أكثر وانتهت دراسة الجهة الإدارية إلى مناسبة تغيير طريقة الطرح .$m248$,'9b3febd08292e400a9edd61abba5b8c7',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(58,0,1,$m248$يجوز التعاقد تطبيقا لأحكام هذا الباب بطريق المناقصة ذات المرحلتين بما يمكن الجهة الإدارية من تحديد الجوانب الفنية أو التعاقدية بشكل متكامل للحصول على عطاءات تنافسية فى أى من الحالات التالية :
1 - التعاقدات ذات المواصفات الفنية المركبة .
2 - عندما ترغب الجهة الإدارية أن تأخذ فى الاعتبار مختلف الحلول الفنية أو التعاقدية والمزايا النسبية لتلك الحلول قبل اتخاذ قرار فى شأن المواصفات الفنية النهائية والشروط التعاقدية .
3 - عندما لا تتوافر تفاصيل المواصفات الفنية الدقيقة أو خصائص الموضوع محل التعاقد عند البدء فى إجراءات الطرح .
ويتم الإعلان عن المناقصة ذات المرحلتين بإحدى الصحف اليومية واسعة الانتشار أو بدعوة المسجلين أو المؤهلين من المشتغلين بالنشاط ، ويجب أن تتضمن كراسة الشروط والمواصفات فى المرحلة الأولى الغرض من التعاقد ، والأداء المتوقع ، والخطوط العريضة للمواصفات الفنية والميزات والمواصفات التى ترغب الجهة الإدارية فى التعاقد عليها ، والمؤهلات المطلوبة لتنفيذ العقد ، ويطلب من مقدمى العطاءات تقديم عروضهم الفنية الأولية بدون أسعار ، وكذلك تقديم ملاحظاتهم على شروط العقد المقترحة ، وأى شروط أخرى .
ويجوز للجهة الإدارية الدخول فى مناقشات فنية خلال المرحلة الأولى مع أى من أصحاب العروض المستجيبة للحد الأدنى من المتطلبات الأساسية الواردة بكراسة الشروط والمواصفات ، وذلك للوصول إلى إطار أعمال ومتطلبات فنية وتعاقدية مدققة تحقق احتياجات الجهة الإدارية وللوصول إلى أكبر قدر من المنافسة ، ويخطر مقدمو العروض بنتيجة المرحلة الأولى .
وتخطر الجهة الإدارية فى المرحلة الثانية مقدمى العروض المقبولة لتقديم عطاءاتهم ، متضمنة العرض الفنى والعرض المالى وفقا للشروط والمواصفات المدققة .
وفيما عدا إجراءات المرحلة الأولى تسرى على إجراءات المناقصة ذات المرحلتين ذات القواعد والإجراءات المنظمة للتعاقد بطريق المناقصة بحسب الأحوال .
ويجوز للجهة الإدارية إجراء تأهيل مسبق قبل الطرح إن ارتأت ذلك .$m248$,'4d55ab4e27a3080a840458f3852dce52',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(59,0,1,$m248$يكون التعاقد بطريق المناقصة المحلية فيما لا تزيد قيمته على أربعة ملايين جنيه ، ويقصر الاشتراك فيها على الموردين والمقاولين ومقدمى الخدمات والأعمال الفنية والاستشاريين المحليين الذين يقع نشاطهم فى نطاق المحافظة التى يتم بدائرتها تنفيذ موضوع التعاقد ومن بينهم المشروعات المتوسطة والصغيرة والمتناهية الصغر .
ويجوز قصر التعاقد بطريق المناقصة المحلية فيما لا تزيد قيمته على مليونى جنيه على المشروعات المتوسطة والصغيرة والمتناهية الصغر التى يقع نشاطها فى نطاق المحافظة التى يتم بدائرتها تنفيذ موضوع التعاقد ، ويجوز فى هذه الحالة فقط وبقرار من السلطة المختصة الاكتفاء بتقديم إقرار بديل عن التأمين المؤقت فى العملية محل الطرح مفادة الالتزام بالسير فى الإجراءات ، كما يجوز للسلطة المختصة صرف دفعة مقدمة وفقا لما تعتمده على أن تتضمن شروط الطرح ذلك .
وفى حالة عدم تقدم أى منها للمناقصة ، يكون للجهة الإدارية حال إعادة الطرح توجيه الدعوة لهم ولغيرهم ، ولا يتم فى هذه الحالة الاستثناء من شرط التأمين المؤقت .
ويتعين على الجهات الإدارية قبل الطرح إخطار جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر لإعلام أصحاب تلك المشروعات بالمحافظة التى يتم بدائرتها التنفيذ لحثهم على تسجيل بياناتهم وتحديثها على بوابة التعاقدات العامة .$m248$,'6ba1bcf42486c690ec418e20b4eaf608',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(60,0,1,$m248$تسرى على كل من المناقصة المحدودة والمناقصة ذات المرحلتين والمناقصة المحلية والممارسة بنوعيها ، الأحكام الخاصة بالمناقصة العامة فيما لم يرد فى شأنه نص خاص فى هذا القانون ولائحته التنفيذية .$m248$,'80fb24d55f4711ab150e4d8f9c247827',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(61,0,1,$m248$تسرى على شراء أو استئجار العقارات ذات الأحكام المنظمة لشراء أو استئجار المنقولات ، وبما لا يتعارض مع طبيعتها .$m248$,'030eb04017d17568d134321ee4d929c2',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(62,0,1,$m248$يجوز التعاقد بطريق الاتفاق المباشر فى أى من الحالات الآتية :
1 - الحالات الطارئة الناجمة عن الظروف الفجائية التى لم يكن فى الإمكان توقعها أو التنبؤ بها ، أو التى تتطلب الضرورة التعامل معها بشكل فورى ، ولا تحتمل اتباع إجراءات المناقصة أو الممارسة بنوعيهما .
2 - وجود مصدر واحد فقط لديه القدرة الفنية أو القدرة على تلبية متطلبات التعاقد أو لديه الحق الحصرى أو الاحتكارى لموضوع التعاقد .
3 - تحقيق أغراض التكامل مع ما هو موجود ، ولا يوجد له سوى مصدر واحد .
4 - عندما يكون موضوع التعاقد غير مشمول فى عقد قائم ، وتقتضى الضرورة الفنية تنفيذه بمعرفة المتعاقد القائم بالتنفيذ .
5 - الحالات العاجلة التى يكون التعاقد فيها خلال مدة زمنية لا تسمح باتخاذ إجراءات المناقصة أو الممارسة بنوعيهما ، وذلك لضمان سلامة وكفالة سير العمل بالجهات الإدارية ، وألا يكون ذلك ناجما عن سوء التقدير أو التأخر فى اتخاذ الإجراءات .
6 - فى حالة التوحيد القياسى مع ما هو قائم .
7 - فى حالات تعزيز السياسات الاجتماعية أو الاقتصادية التى تتبناها الدولة .
ويتعين الحصول على عروض أسعار عند التعاقد بالاتفاق المباشر فى الحالات المبينة قرين البنود (5)، و (6)، و(7) المشار إليها .$m248$,'c9c5c6aa81ce63bf837803e8453e04ec',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(63,0,1,$m248$يكون التعاقد بطريق الاتفاق المباشر طبقا لحكم المادة (62) من هذا القانون بناء على ترخيص من :
1 - رئيس الهيئة ، أو رئيس المصلحة ومن له سلطاته فى الجهات الإدارية الأخرى أو رئيس الصندوق ، وذلك فيما لا تجاوز قيمته مليون جنيه بالنسبة لشراء أو استئجار المنقولات أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ، وخمسة ملايين جنيه بالنسبة لمقاولات الأعمال .
2 - الوزير ومن له سلطاته ، أو المحافظ ، فيما لا تجاوز قيمته عشرة ملايين جنيه بالنسبة لشراء أو استئجار المنقولات أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ، وعشرين مليون جنيه بالنسبة لمقاولات الأعمال .
ولمجلس الوزراء فى حالة الضرورة القصوى أن يأذن بالتعاقد بطريق الاتفاق المباشر، وذلك فيما يجاوز الحدود المنصوص عليها فى البند (2) .
كما يجوز بموافقة السلطة المختصة التعاقد بالاتفاق المباشر على شراء أو استئجار المنقولات أو الأعمال أو تلقى الخدمات منخفضة القيمة والتى لا تتجاوز قيمتها عشرين ألف جنيه فى المرة الواحدة ، ولا تجاوز مائة ألف جنيه خلال السنة المالية ، ويتبع فى شأنها الإجراءات التى تبينها اللائحة التنفيذية لهذا القانون ، ويجوز للسلطة المختصة التفويض فى اختصاصاتها فى هذه الحالة فقط .
3 - الوزير المختص بالصحة بالنسبة للأمصال واللقاحات والعقاقير الطبية ذات الطبيعة الاستراتيجية وألبان الأطفال ، وفقا للضوابط والشروط التى تحددها اللائحة التنفيذية لهذا القانون .
ولا يجوز لأى من هذه السلطات التفويض فى الاختصاصات الممنوحة لها للتعاقد بهذا الطريق .
ويستثنى من العرض على لجنة تفضيل المنتج الصناعى المصرى فى العقود الحكومية إذا اقتضت المصلحة العامة ذلك فى الحالات التى يصدر بها قرار من رئيس مجلس الوزراء ، بناء على عرض الوزير المختص بالتجارة والصناعة .
ويجب على إدارة التعاقدات توثيق مبررات اتباع طريق الاتفاق المباشر ، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .$m248$,'35328a1d75a9443b670af690cbb00297',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(64,0,1,$m248$يجوز فى الحالات الطارئة ، أو فى الحالات العاجلة ، أو لدواعى المصلحة العامة أن يتم التعاقد على شراء أو استئجار العقارات بطريق الاتفاق المباشر ، وذلك بناء على ترخيص من :
1 - رئيس الهيئة ، أو رئيس المصلحة ومن له سلطاته فى الجهات الإدارية الأخرى أو رئيس الصندوق ، وذلك فيما لا تجاوز قيمته خمسمائة ألف جنيه بالنسبة للاستئجار ، ومليون جنيه بالنسبة للشراء خلال العام المالى .
2 - الوزير ومن له سلطاته أو المحافظ ، وذلك فيا لا تجاوز قيمته خمسة ملايين جنيه بالنسبة للاستئجار ، وعشرة ملايين جنيه بالنسبة للشراء خلال العام المالى .
ولا يجوز لأى من هذه السلطات التفويض فى الاختصاصات الممنوحة لها للتعاقد بهذا الطريق .
ولمجلس الوزراء فى حالة الضرورة القصوى ، أن يأذن بالتعاقد بطريق الاتفاق المباشر ، وذلك فيما يجاوز الحدود المنصوص عليها بالبند (2) .
ويجب على إدارة التعاقدات توثيق مبررات اتباع طريق الاتفاق المباشر ، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .$m248$,'0b395759c8eaf1a823d3311e76926e27',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(65,0,1,$m248$يجوز للجهة الإدارية طرح احتياجاتها أو احتياجات جهة إدارية أخرى أو أكثر باتباع طريق المناقصة أو الممارسة بنوعيهما أو طريق الاتفاق المباشر وبما يتفق وطبيعة العملية محل الطرح وإبرام اتفاق إطارى مع من يقع عليه الاختيار يتضمن القواعد والشروط التى سيجرى من خلالها إصدار أوامر التوريد أو الإسناد ، وذلك فى أى من الحالات الآتية :
1 - الحاجة للتعاقد المتكرر على الأصناف أو لتنفيذ الأعمال أو الخدمات أو تقديم الدراسات الاستشارية ، والتى تتسم أى منها بالعمومية أو شيوع الاستخدام .
2 - توقع الجهة الإدارية وفقا للمجرى العادى للأمور بسبب طبيعة الأصناف أو الأعمال أو الخدمات أو الدراسات الاستشارية المطلوبة أن الحاجة ستنشأ إليها مستقبلا بصورة عاجلة ، دون أن يكون معلوما لديها على وجه الدقة توقيت توريدها أو تنفيذها أو كمياتها .
3 - الحالات الأخرى التى ترى الجهة الإدارية مناسبة اتباع هذا النمط من التعاقدات بما فى ذلك استهداف تنمية بعض الصناعات أو تنميط الاحتياجات وغيرها من الحالات المماثلة .
ويشترط أن تتضمن شروط الطرح المواصفات الفنية ، والبيانات الإحصائية لمعدلات الطلب ، ومعدلات الاستهلاك التاريخية ، والمؤشرات المستقبلية الاسترشادية لمحل الطرح والتعاقد أو أطر الأعمال أو الخدمات أو الدراسات الاستشارية ، بحسب الأحوال .
ويكون اتباع الاتفاقية الإطارية وفقا للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص بالجهة الإدارية أو قرار مجلس الوزراء فى حال تعدد الجهات الإدارية ، وذلك بعد موافقة وزيرى المالية والتخطيط .
وتبين اللائحة التنفيذية لهذا القانون قواعد وإجراءات إبرام أو إنهاء الاتفاقية الإطارية ، وأنماطها المختلفة ، ومدتها ، وإصدار أوامر التوريد أو الإسناد ، وأداء التأمين وفقا لها .$m248$,'7f3a02ef0ffd3747eb49277ad37b0bc7',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(66,0,1,$m248$مع عدم الإخلال بأحكام قانون حماية حقوق الملكية الفكرية الصادر بالقانون رقم 82 لسنة 2002 ، يجوز للجهة الإدارية ودون التقيد بطرق التعاقد المنصوص عليها فى هذا القانون أن تعلن عن مسابقة للحصول على عمل ابتكارى يتم اختياره من خلال لجنة تحكيم متخصصة ومحايدة تشكل بقرار من السلطة المختصة لهذا الغرض وفقا لعناصر وأسس التقييم المعلنة لتحديد العمل الفائز .
وتحدد شروط المسابقة كيفية منح الجوائز أو المكافآت أو الامتيازات ، وكذا كيفية التعامل مع ملكية الأعمال المقدمة من المتسابقين .
ويكون الإعلان عن المسابقة بإحدى الصحف اليومية واسعة الانتشار ، بالإضافة إلى النشر عنها على بوابة التعاقدات العامة .$m248$,'527497387b299f56bb00c85c7b129066',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(67,0,1,$m248$تسرى أحكام هذا الباب على عمليات بيع وتأجير المنقولات والعقارات ، والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات .$m248$,'631479d75cecc7f568cdef1bbd9ed624',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(68,0,1,$m248$يكون التعاقد بطريق المزايدة المحدودة فى أى من الحالات الآتية :
1 - الأصناف التى يخشى عليها من التلف ببقاء تخزينها .
2 - الأصناف التى تتطلب طبيعتها قصر بيعها على المرخص لهم بالتعامل فيها .
3 - الحالات العاجلة التى لا تحتمل اتباع إجراءات المزايدة العلنية العامة أو بالمظاريف المغلقة .
4 - الحالات التى سبق عرضها فى مزايدة علنية عامة أو مزايدة بالمظاريف المغلقة لأكثر من مرة ، ولم تقدم عنها أى عروض أو لم يصل ثمنها إلى الثمن الأساسى ، وانتهت دراسة الجهة الإدارية إلى مناسبة تغيير طريقة الطرح .$m248$,'f32d11a45ba3ca6204cbdcf39ca9dd98',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(69,0,1,$m248$يكون التعاقد بطريق المزايدة المحلية فيما لا يجاوز ثمنه الأساسى ستمائة ألف جنيه ، ويقصر الاشتراك فيها على المتزايدين المحليين الذين يقع نشاطهم داخل نطاق المحافظة التى ينفذ بدائرتها موضوع التعاقد .$m248$,'73a0652b16ecfa5d9a03ba5de09c1a38',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(70,0,1,$m248$تسرى على بيع وتأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو استغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف ذات القواعد والإجراءات المنظمة لشراء المنقولات أو استئجارها فيما لم يرد بشأنه نص خاص ، وذلك كله بما لا يتعارض مع طبيعة البيع أو التأجير أو الترخيص أو الاستغلال .$m248$,'281d3a6c4726b19563068fecf7474e11',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(71,0,1,$m248$يجوز فى الحالات الطارئة أو العاجلة التى لا تحتمل اتباع إجراءات المزايدة بجميع أنواعها ، أن يتم التعاقد على بيع أو تأجير المنقولات أو العقارات أو المشروعات التى ليس لها الشخصية الاعتبارية أو الترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف بطريق الاتفاق المباشر من خلال لجنة مشكلة لهذا الغرض بناء على ترخيص من :
1 - رئيس الهيئة ، أو رئيس المصلحة ومن له سلطاته فى الجهات الإدارية الأخرى أو رئيس الصندوق ، وذلك فيما لا تجاوز قيمته خمسمائة ألف جنيه .
2 - الوزير ، ومن له سلطاته أو المحافظ فيما لا تجاوز قيمته مليون جنيه .
ويجوز استثناء من أحكام الفقرة السابقة وبموافقة الوزير المختص بالجهة الإدارية ، فى الحالات التى سبق عرضها فى مزايدة علنية عامة أو بالمظاريف المغلقة لأكثر من مرة ، ولم تقدم عنها عروض أو لم يصل ثمنها إلى الثمن الأساسى أن يتم البيع أو التأجير أو الترخيص بالانتفاع أو بالاستغلال بالاتفاق المباشر ، وذلك على النحو الآتى :
1 - العقارات التى لا تجاوز قيمتها مليونى جنيه ، يتم إعلان الثمن الأساسى ، وبشرط ألا يقل سعر البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال عن هذا الثمن الأساسى .
2 - بيع المنقولات أو المشروعات التى ليس لها الشخصية الاعتبارية أو تأجيرها أو الترخيص بالمشروعات أو استغلالها بما فى ذلك المنشآت السياحية والمقاصف، بحسب الأحوال ، التى لا تجاوز قيمتها مليون جنيه بشرط ألا يقل ثمن البيع أو التأجير أو الترخيص بالانتفاع أو الاستغلال عن الثمن أو القيمة الأساسية .
وذلك كله بشرط أن يتم التعاقد مع مقدم العرض الأفضل شروطا والأعلى سعرا .
ولا يجوز لأى من هذه السلطات التفويض فى الاختصاصات الممنوحة لها للتعاقد بهذا الطريق .
ويجب على إدارة التعاقدات توثيق مبررات اتباع طريق الاتفاق المباشر ، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون .$m248$,'6d1e2dce0f496efc95b7954b5a65f40f',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(72,0,1,$m248$تسرى على شراء أو استئجار أو بيع أو تأجير العقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات فى الخارج أحكام هذا القانون ولائحته التنفيذية بما لا يتعارض مع الإجراءات المعمول بها فى الدولة محل التعاقد ، وفى حالة تعذر ذلك يتعين الحصول على موافقة مجلس الوزراء على التعاقد وفقا للشروط والقواعد التى يعتمدها بناء على اقتراح الوزير المختص بالجهة الإدارية .$m248$,'e0b56f374e795d9a484ffa3c164dcef5',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(73,0,1,$m248$يكون التعاقد على الدراسات الاستشارية عن طريق المناقصة المحدودة أو المناقصة ذات المرحلتين أو المناقصة المحلية ، ويكون تقييم العطاءات بنظام النقاط ، على أن تتضمن شروط الطرح عناصر وأسس التقييم والحد الأدنى للقبول ، وكيفية التقييم للوصول إلى أفضلها شروطا وسعرا .
ويجوز استثناء فى العمليات ذات الطبيعة الروتينية أو البسيطة أو النمطية أو التى لها أطر فنية ثابتة التعاقد عليها بطريق المناقصة العامة أو المحلية أو الاتفاق المباشر إذا قدرت الجهة الإدارية أن أيا من هذه الطرق هو الأنسب بحسب طبيعة العملية وتتم الترسية فى هذه الحالات على أقل الأسعار من العروض المقبولة فنيا ، على أن تتضمن شروط الطرح المتطلبات الفنية والمؤهلات والخبرات وغيرها التى يتعين توافرها .
كما يجوز للجهة الإدارية التعاقد من خلال مناقصة محدودة أو مناقصة محلية أو اتفاق مباشر مع أحد الاستشاريين بذاته إذا قدرت أن المهام المطلوبة تعتمد بشكل كلى على خبراته ومؤهلاته .
ويصدر باتباع أى من هذه الطرق قرار مسبب من السلطة المختصة وفقا لظروف وطبيعة التعاقد ، وبما لا يتعارض مع القوانين المنظمة للمهن الحرة .
ويجوز للجهة الإدارية إجراء تأهيل مسبق قبل الطرح .$m248$,'8cc3b04a7a2dd1e9bb19e1adeb6f5af5',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(74,0,1,$m248$مع مراعاة حكم المادة (63) من هذا القانون ، يجوز بموافقة السلطة المختصة التعاقد بالاتفاق المباشر مع أى من مقدمى الخدمات الأساسية الذى تمتلك الدولة فيه حصة حاكمة تسمح لها بتعيين أغلبية أعضاء مجلس إدارته أو التحكم على أى نحو فى القرارات الصادرة من مجلس إدارته أو من الجمعية العامة له على تقديم الخدمات الأساسية ومن ذلك الكهرباء ، والمياه ، والغاز وغيرها من الخدمات الأساسية اللازمة لتسيير المرفق العام ذات الطبيعة المماثلة والمحددة أسعارها من الدولة .
وفى هذه الحالة يستثنى مقدمو الخدمات الأساسية من تقديم خطاب ضمان الدفعة المقدمة ومن أداء التأمين بنوعيه ، ويكتفى بما يقدم منهم من تعهدات أو ضمانات تقرها السلطة المختصة .
وللسلطة المختصة التفويض فى أى من الاختصاصات المنصوص عليها فى هذه المادة .$m248$,'51dd044cc5b53a98305ed9e2960d6ebd',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(75,0,1,$m248$يجب على الجهة الإدارية مراعاة إمكانيات المشروعات المتوسطة والصغيرة والمتناهية الصغر عند فتح باب التسجيل للمشتغلين بالأنشطة المختلفة أو عند إعدادها لشروط التأهيل المسبق أو مستندات الطرح ومعايير التقييم وغيرها ، وبما يتيح لهذه المشروعات المشاركة فى العمليات التى يتم طرحها ، ودون أن يؤثر ذلك على تكافؤ الفرص والالتزام بمعايير الجودة والأداء فى التنفيذ .
كما يجب على الجهة الإدارية إتاحة نسبة لا تقل عن (20%) من قيمة احتياجاتها السنوية للتعاقد مع تلك المشروعات ، ومن واقع ما تدرجه ويتم إقراره بخطتها السنوية المنصوص عليها بالمادة (9) من هذا القانون .
وعلى ممثلى وزارة المالية من أعضاء اللجان المنصوص عليها فى هذا القانون وبالوحدات الحسابية بالجهات الإدارية التحقق من التزام الجهات بتنفيذ ذلك .$m248$,'c20d9708007100e8997729bf593f5bf0',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(76,0,1,$m248$فى حالات الضرورة ، يجوز لمجلس الوزراء أن يصرح لجهة إدارية بعينها ، لاعتبارات يقدرها ترتبط بطبيعة عمل تلك الجهة ونشاطها أو طبيعة العملية ، بالتعاقد بأى من طرق التعاقد المنصوص عليها بالمادة (7) من هذا القانون وفقا للشروط والقواعد التى يحددها .
كما يجوز لمجلس الوزراء أن يرخص لجهة إدارية بعينها بالتعاقد بالاتفاق المباشر مع الشخص الطبيعى أو الاعتبارى المصرى أو الأجنبى حال تقدمه بمشروع استثمارى متكامل شاملا التمويل إذا كان هذا المشروع يحقق للجهة الإدارية المتعاقدة الأهداف الاقتصادية والتنموية للدولة ، وذلك بناء على عرض من الوزير المختص بنتائج الجدوى الفنية والاقتصادية والاجتماعية للمشروع والدراسة التحليلية للهيكل الفنى والمالى له ، وعلى أن يكون ذلك بعد موافقة وزيرى المالية والتخطيط ، وذلك كله ما لم ينظم التعاقد قوانين أخرى .
وإذا لم ينطو المشروع المقدم على حقوق ملكية فكرية حصرية لمقدمه ورغبت الجهة الإدارية فى تنفيذه ، يحق لها فى ضوء دراستها طرحه للحصول على عطاءات تنافسية له، ويتم التعاقد وفقا للأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرامه ، والتى تقرها اللجنة المنصوص عليها بالمادة (4) من هذا القانون ويعتمدها مجلس الوزراء ويصدر بها دليل إجرائى ينظمها .$m248$,'3926af0e6bfcf8f50d77a00ea447a71d',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(77,0,1,$m248$يجوز لوزارات الدفاع والإنتاج الحربى والداخلية وأجهزتها فى حالات الضرورة التى تقتضيها اعتبارات الأمن القومى ، التعاقد بطريق المناقصة المحدودة أو المناقصة ذات المرحلتين أو المناقصة المحلية أو الممارسة المحدودة أو الاتفاق المباشر ، وذلك مع إعمال أحكام القانون رقم 204 لسنة 1957 بشأن إعفاء العقود الخاصة بالتسليح من الضرائب والرسوم والقواعد المالية .
وللسلطة المختصة التفويض فى أى من الاختصاصات المقررة فى هذا الشأن .$m248$,'bf30d1365b2ee87eed4aee692f5ad79b',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(78,0,1,$m248$يجوز للجهات المخاطبة بأحكام هذا القانون التعاقد فيما بينها بطريق الاتفاق المباشر بموافقة السلطة المختصة بكل منها ، وذلك دون التقيد بالإجراءات والحدود المالية الواردة بهذا القانون ، كما يجوز أن تنوب عن بعضها فى مباشرة إجراءات التعاقد فى مهمة معينة وفقا للقواعد المعمول بها فى الجهة الإدارية طالبة التعاقد .
ويحظر التنازل لغير هذه الجهات عن العقود التى تتم فيما بينها .
وتسرى أحكام هذه المادة على الهيئة العربية للتصنيع ، والهيئة القومية للإنتاج الحربى ، والمخابرات العامة ، ويجوز لأى منها إسناد التعاقدات المبرمة تطبيقا لأحكام هذه المادة مباشرة إلى أى من وحداتها التابعة .$m248$,'67f657a6d727c66628eaab457099fb6a',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(79,0,1,$m248$استثناء من أحكام هذا القانون ، يجوز للجهة الإدارية التعاقد على الصفقات التى تتطلب منها السرعة فى اتخاذ قرار التعاقد بحكم طبيعتها أو التقلبات فى أسعارها وكمياتها الاقتصادية أو التى تغطى مدى زمنى مستقبلى أو العمليات المتعلقة بالمعاملات المنجزة فى الأسواق المالية الدولية أو عقود المشتقات المالية والمشتريات الآجلة والمستقبلية وما يرتبط بها ، وذلك كله وفقا للممارسات التجارية الدولية المطبقة التى تحددها السلطة المختصة بالجهة الإدارية وتقرها اللجنة المنصوص عليها بالمادة (4) من هذا القانون ويعتمدها مجلس الوزراء .
كما يجوز للجهة الإدارية استثناء من أحكام هذا القانون إبرام التعاقدات ذات الطبيعة المركبة أو المتشابكة أو متعددة الأطراف ، أو التعاقدات التى تتطلب هيكلا تمويليا كمشروعات البناء والتملك والتشغيل ونقل الملكية BOOT ، والبناء والتملك والتشغيل BOO ، والتصميم والاشتراء والتشييد + التمويل EPC+Finance وغيرها ، وذلك إذا كانت هذه التعاقدات تحقق للجهة الإدارية المتعاقدة أهدافها الاقتصادية والتنموية العاجلة ، أو استلزمت الظروف الاقتصادية أو الاجتماعية سرعة إتمامها فى توقيت معين . وتتم هذه التعاقدات وفقا للأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرامها والتى تقرها اللجنة المنصوص عليها فى المادة (4) من هذا القانون ، ويعتمدها مجلس الوزراء ويصدر بها دليل إجرائى ينظمها ، على أن يضع الوزير المختص بالجهة الإدارية القواعد الخاصة بكل مشروع بالاتفاق مع وزيرى المالية والتخطيط ، ويجب اعتماد هذه القواعد من مجلس الوزراء بناء على عرض الوزير المختص بالجهة الإدارية .
وتبين اللائحة التنفيذية لهذا القانون ضوابط وأوضاع إبرام هذه التعاقدات .$m248$,'6deffe5b0acbdeb40fe93000e4af864b',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(80,0,1,$m248$يجوز التعامل بالاتفاق المباشر على العقارات بالبيع أو التأجير أو الترخيص بالانتفاع أو بالاستغلال فى حالات الضرورة ، لتحقيق اعتبارات اجتماعية أو اقتصادية تقتضيها المصلحة العامة ، وذلك بالاتفاق بين وزير المالية والوزير المختص بالجهة الإدارية أو المحافظ المختص ، بناء على مبررات تبديها الوزارة أو المحافظة طالبة الترخيص بالتعامل مع اقتراح مقابل التعامل وأسلوب السداد ، على أن تتحقق اللجنة العليا للتقييم بالهيئة العامة للخدمات الحكومية من مناسبة هذا المقابل ، ويعرض وزير المالية ما تنتهى إليه اللجنة على مجلس الوزراء للاعتماد .
وذلك كله وفقا للقواعد وبالضوابط والشروط التى يصدر بها قرار من مجلس الوزراء بناء على اقتراح وزير المالية .$m248$,'a7b61b6527175cc4a35b2a16ccc8cdd0',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(81,0,1,$m248$مع مراعاة الحالات التى يحظر هذا القانون التفويض فيها . يجوز للسلطة المختصة أن تفوض فى أى من اختصاصاتها الواردة به لشاغلى الوظائف القيادية دون غيرهم ، وذلك وفقا للضوابط والإجراءات التى تبينها اللائحة التنفيذية لهذا القانون .$m248$,'36d1ed80dc6b59a0fdc21637b9080dfb',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(82,0,1,$m248$تلتزم إدارة التعاقدات بالجهة الإدارية بفتح ملف لكل عملية تحفظ به جميع المستندات والبيانات المتعلقة بالإجراءات ، ويتضمن جميع المخاطبات الداخلية والمراسلات التى أرسلت منذ بداية إجراءات العملية ، مع الحفاظ على ما يحتويه الملف من مستندات وبيانات .
ولا يجوز إفشاء أى من هذه المستندات والبيانات أو الاطلاع عليها من أطراف أو أفراد غير معنيين بها إلا لجهات التفتيش والفحص والمراجعة ، وفقا للقوانين والقرارات المنظمة لذلك .$m248$,'c38953c70f285b0063c050ca82adef11',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(83,0,1,$m248$تتولى الهيئة العامة للخدمات الحكومية نشر هذا القانون ولائحته التنفيذية وأى تعديلات عليهما ، وكذلك المنشورات العامة والكتب الدورية والقرارات المتعلقة بتطبيقهما فور صدورها، بما فيها قرارات الشطب أو إعادة القيد وغيرها، وذلك على بوابة التعاقدات العامة بالإضافة إلى قواعد النشر المقررة .$m248$,'05a96928e03663d7124d26bee625539e',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(84,0,1,$m248$يجب على الجهات الخاضعة لأحكام هذا القانون اتخاذ إجراءات التعاقد إلكترونيا وفقا لما يتم ميكنته من إجراءات من خلال منظومة موحدة ومنتظمة ومؤمنة إلكترونيا ، على أن تتبع الإجراءات الميكنة حال اكتمالها وانتظامها .
وتبين اللائحة التنفيذية لهذا القانون محتوى المنظومة الإلكترونية وكيفية تشغيلها والضوابط والإجراءات المتبعة ذات الصلة .$m248$,'12afb95296f1f64eac019e7d7c691d05',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(85,0,1,$m248$تمسك كل جهة إدارية سجلا لقيد الأسماء والبيانات الكافية للراغبين فى التعامل معها متضمنا تصنيفهم طبقا لقدراتهم الفنية والمالية وسمعتهم التجارية وخبراتهم السابقة وشهادات مزاولة النشاط ورقم الحساب البنكى الخاص بكل منهم ، وغيرها من المستندات المطلوبة طبقا للقوانين المنظمة ليتم من خلاله التعامل معهم ، ويتعين على الجهة الإدارية التحقق من تحديث تلك البيانات بصفة دورية سنويا قبل بداية العام المالى بشهر على الأقل .
ولا يجوز للجهة الإدارية التعامل مع المسجلين لديها بسجلاتها أو غيرهم إلا بعد تسجيلهم لبياناتهم على بوابة التعاقدات العامة أو تحديثها حال تعديلها ، وأن تطابق الجهة الإدارية تلك البيانات واعتمادها من واقع قاعدة البيانات ، على أن تتضمن بياناتهم رقم السجل التجارى أو الصناعى أو المهنى أو سجل مزاولة المهنة بحسب الأحوال ، ورقم البطاقة الضريبية أو أى بيانات أخرى ليتم من خلاله التعامل معهم .
وتمسك الهيئة العامة للخدمات الحكومية سجلا لقيد أسماء الممنوعين من التعامل مع أى جهة من الجهات الإدارية المذكورة سواء كان المنع بنص فى القانون ، أو بموجب قرارات إدارية ، أو لمن صدر ضده حكم نهائى فى إحدى الجرائم الواردة فى المادة (93) من هذا القانون ، ويحظر التعامل مع المقيدين فى هذا السجل ما لم يتم رفع هذا الحظر بانتفاء سببه .
ويقع باطلا كل عقد أو اتفاق يتم بالمخالفة لأحكام الفقرة السابقة .$m248$,'651e963bca711cd5a3710c527b93dbcb',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(86,0,1,$m248$يجب على الجهة الإدارية استيفاء تقييم أداء المتعاقدين معها فى نهاية كل عام مالى أو بانتهاء التعاقد وفقا للنماذج التى تعدها والمعايير التى تحددها الهيئة العامة للخدمات الحكومية ، ويتم نشرها على بوابة التعاقدات العامة على أن يتضمن النشر أسماء المتعاقدين الذين أخلوا بشروط التعاقد والجزاءات التى وقعت عليهم ، ويستثنى من النشر العمليات التى تتطلب اعتبارات الأمن القومى أن تتم بطريقة سرية وفقا لما تقدره السلطة المختصة ، بالإضافة إلى الاحتفاظ بها بملف العملية ، على أن يتم توثيق أداء المتعاقد أولا بأول ، وبما يسهم فى إنجاز مشروعات الدولة بالجودة المطلوبة وفى الزمن المحدد .
كما يجب على الجهة الإدارية فى نهاية كل عام مالى إجراء استقصاء مع المتعاقدين معها بغرض إظهار الإيجابيات ، والوقوف على الإجراءات السلبية التى واجهتهم فى تعاملاتهم ، واتخاذ الإجراءات التصحيحية اللازمة ، وتقويم أداء العاملين بإدارة التعاقدات .$m248$,'16c4a3c1d5a0ec625c5ac01654a98486',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(87,0,1,$m248$يجب على كل جهة إدارية إعداد قاعدة بيانات لجميع العقارات المملوكة لها ، وما تم التصرف فيه منها وأسلوب التصرف وقيمته والبيانات الكافية عن المتصرف إليهم .
وتخطر الهيئة العامة للخدمات الحكومية بصفة دورية بجميع ما يثبت من بيانات بتلك الجهات لإثباتها بقاعدة البيانات المركزية المنشأة لديها .$m248$,'369776b5fcd0a9408398dc2a34f87df7',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(88,0,1,$m248$يشترط لشغل وظائف التعاقدات بالجهات الخاضعة لأحكام هذا القانون أو الاستمرار فى شغلها اجتياز التدريب اللازم لذلك . ويحدد وزير المالية بداية تنفيذ ذلك ومراحله، وتضع وزارة المالية (الهيئة العامة للخدمات الحكومية) لمقدمى خدمات التدريب والمراكز التدريبية برامج هذا التدريب ومناهجه ، كما يجوز لها المشاركة فى المبادرات التى من شأنها رفع كفاءة المتعاملين مع الجهات الإدارية ، وتحدد اللائحة التنفيذية لهذا القانون مستوى البرامج التدريبية المطلوبة ، وإجراءات التقدم لها ، وآلية اعتمادها ، وغيرها .$m248$,'8676cf940c99c844a60e06ab24294e63',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(89,0,1,$m248$مع عدم الإخلال بحق ذوى الشأن فى إقامة الدعوى المدنية أو الجنائية ، يؤاخذ تأديبيا كل من خالف أحكام هذا القانون أو لائحته التنفيذية ، أو مدونة السلوك الوظيفى للعاملين بالتعاقدات والتى يصدر بها قرار من وزير المالية .$m248$,'bb645da3e5ef11c655b4559f35524301',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(90,0,1,$m248$تتولى إدارة الفتوى المختصة بمجلس الدولة مراجعة مشروعات العقود التى تكون الجهة الإدارية طرفا فيها ، ونماذج كراسات الشروط ، وأنماط العقود النموذجية والأدلة الإرشادية وغيرها مما هو منصوص عليه فى المادة (19) من هذا القانون .$m248$,'f2678205b249feb99a7c6cc43b869a8d',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(91,0,1,$m248$يجوز لطرفى العقد فى حالة حدوث خلاف أثناء تنفيذه ، وقبل اللجوء إلى القضاء أو التحكيم بحسب الأحوال ، الاتفاق على تسويته عن طريق التوفيق أو الوساطة ، وذلك إذا تضمنت شروط الطرح أو العقد جواز ذلك ، وبموافقة السلطة المختصة مع التزام كل طرف بالاستمرار فى تنفيذ التزاماته الناشئة عن العقد .
كما يجوز للمتعاقد اللجوء إلى القضاء للمطالبة بالتعويض عما يكون قد لحقه من أضرار نتيجة إخلال الجهة الإدارية بتنفيذ التزاماتها الواردة بالعقد بخطأ منها ، ما لم يوافق الوزير المختص بالجهة الإدارية على اللجوء إلى التحكيم وتتضمنه شروط العقد ، ويتفق عليه الطرفان وفقا للقواعد والإجراءات المنصوص عليها فى قانون التحكيم فى المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة 1994$m248$,'c3b429ecfdb14c0a9d7dff799815e0e8',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(92,0,1,$m248$لا يجوز للمتعاقد النزول عن العقد أو عن المبالغ المستحقة له كلها أو بعضها ، ومع ذلك يجوز أن يتنازل عن تلك المبالغ لأحد البنوك ، ويكتفى فى هذه الحالة بتصديق البنك دون الإخلال بمسئولية المتعاقد عن تنفيذ العقد ، كما لا يخل قبول نزوله عن المبالغ المستحقة له بما يكون للجهة الإدارية قبله من حقوق .$m248$,'fce03ef6347521f38d733d927b2f8b41',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$),
(93,0,1,$m248$تخطر الجهات المختصة الهيئة العامة للخدمات الحكومية بمن صدر بحقه حكم نهائى فى إحدى الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات ، أو فى جرائم التهرب الضريبى أو الجمركى .$m248$,'363003d57a2357f474909fd143492343',DATE '2018-11-03',NULL,'active',NULL,NULL,$m248$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 39 مكرر (د) فى 3 أكتوبر 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة إن وجدت، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m248$);

DO $m248$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m248_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m248_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[248] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m248_art) <> 99 OR (SELECT sum(char_length(body)) FROM m248_art) <> 70701 OR (SELECT count(*) FROM m248_ver) <> 99 THEN
    RAISE EXCEPTION '[248] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=182 AND law_year=2018 AND kind='law';
  IF v_law IS NOT NULL AND (v_title NOT LIKE '%التعاقدات%' OR v_title NOT LIKE '%الجهات العامة%') THEN
    RAISE EXCEPTION '[248] يوجد مستند آخر برقم 182 لسنة 2018 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (182, 2018, $t247$القانون رقم 182 لسنة 2018 بإصدار قانون تنظيم التعاقدات التى تبرمها الجهات العامة (النص الأصلى كما نشر بالجريدة الرسمية)$t247$, $t247$قانون تنظيم التعاقدات العامة 182/2018$t247$, 'other', 'in_force', NULL, DATE '2018-10-03', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m248_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m248_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m248_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 99 THEN
    RAISE EXCEPTION '[248] عدد صفوف النص % بدل 99', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 99 THEN
    RAISE EXCEPTION '[248] عدد نسخ النص % بدل 99', v_vcnt;
  END IF;
  RAISE NOTICE '[248] قانون 182/2018: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m248$;
